comms.text:
@1 וַאֲמַר יְיָ לְמשֶׁה אֱמַר לְכַהֲנַיָּא בְּנֵי אַהֲרֹן וְתֵימַר לְהוֹן עַל מִית לָא יִסְתָּאַב בְּעַמֵּיהּ:
@2 אֶלָּהֵן לְקָרִיבֵיהּ דְּקָרִיב לֵיהּ לְאִמֵּיהּ וְלַאֲבוּהִי וְלִבְרֵיהּ וְלִבְרַתֵּיהּ וְלַאֲחוּהִי:
@3 וְלַאֲחָתֵיהּ בְּתֻלְתָּא דְּקָרִיבָא לֵיהּ דִּי לָא הֲוַת לִגְבָר לַהּ יִסְתָּאָב:
@4 לָא יִסְתָּאַב רַבָּא בְעַמֵּיהּ לְאַחֲלוּתֵיהּ:
@5 לָא יִמְרְטוּן מְרַט בְּרֵישְׁהוֹן וּפָאתָא דְדִקְנְהוֹן לָא יְגַלְּחוּן וּבְבִשְׂרְהוֹן לָא יְחַבְּלוּן חִבּוּל:
@6 קַדִּישִׁין יְהוֹן קֳדָם אֱלָהֲהוֹן וְלָא יְחַלּוּן שְׁמָא דֶּאֱלָהֲהוֹן אֲרֵי יָת קֻרְבְּנַיָּא דַיְיָ קֻרְבָּן אֱלָהֲהוֹן אִנּוּן מַקְרִיבִין וִיהוֹן קַדִּישִׁין:
@7 אִתְּתָא מַטְעֲיָא וּמְחַלְּלָא לָא יִסְּבוּן וְאִתְּתָא דִּמְתָרְכָא מִבַּעְלַהּ לָא יִסְּבוּן אֲרֵי קַדִּישׁ הוּא קֳדָם אֱלָהֵיהּ:
@8 וּתְקַדְּשִׁנֵּיהּ אֲרֵי יָת קֻרְבַּן אֱלָהָךְ הוּא מְקָרֵב קַדִּישׁ יְהֵי לָךְ אֲרֵי קַדִּישׁ אֲנָא יְיָ מְקַדִּשְׁכוֹן:
@9 וּבַת גְּבַר כָּהֵן אֲרֵי תִתְחַל לְמִטְעֵי מִקְּדֻשַּׁת אֲבוּהָ הִיא מִתַּחֲלָא בְּנוּרָא תִּתּוֹקָד:
@10 וְכַהֲנָא דְאִתְרַבָּא מֵאֲחוֹהִי דְּ יִתָּרִיק עַל רֵישֵׁיהּ מִשְׁחָא דִרְבוּתָא וְדִי קָרִיב יָת קֻרְבָּנֵיהּ לְמִלְבַּשׁ יָת לְבוּשַׁיָּא יָת רֵישֵׁיהּ לָא יְרַבֵּי פֵרוּעַ וּלְבוּשׁוֹהִי לָא יִבְזַע:
@11 וְעַל כָּל נַפְשַׁת מֵתָא לָא יֵיעוֹל לַאֲבוּהִי וּלְאִמֵּיהּ לָא יִסְתָּאָב:
@12 וּמִין מַקְדְּשָׁא לָא יִפּוֹק וְלָא יַחֵל יָת מַקְדְּשָׁא דֶאֱלָהֵיהּ אֲרֵי כְּלִיל מְשַׁח רְבוּתָא דֶאֱלָהֵיהּ עֲלוֹהִי אֲנָא יְיָ:
@13 וְהוּא אִתְּתָא בִּבְתֻלְתָּהָא יִסָּב:
@14 אַרְמְלָא וּמְתָרְכָא וְחַלִּילָא מַטְעֲיָא יָת אִלֵּין לָא יִסָּב אֱלָהֵן בְּתֻלְתָּא מֵעַמֵּיהּ יִסַּב אִתְּתָא:
@15 וְלָא יַחֵל זַרְעֵיהּ בְּעַמֵּיהּ אֲרֵי אֲנָא יְיָ מְקַדְּשֵׁיהּ:
@16 וּמַלִּיל יְיָ עִם משֶׁה לְמֵימָר:
@17 מַלֵּל עִם אַהֲרֹן לְמֵימָר גְּבַר מִבְּנָיךְ לְדָרֵיהוֹן דִּי יְהֵי בֵיהּ מוּמָא לָא יִקְרַב לְקָרָבָא קֻרְבָּנָא קֳדָם אֱלָהֵיהּ:
@18 אֲרֵי כָל גְּבַר דִּי בֵיהּ מוּמָא לָא יִקְרָב גְּבַר עַוִּיר אוֹ חֲגִיר אוֹ חָרִים אוֹ שְׂרִיעַ:
@19 אוֹ גְבַר דִּי יְהֵי בֵיהּ תְּבַר רַגְלָא אוֹ תְּבַר יְדָא:
@20 אוֹ גְבִין אוֹ דֻקָּא אוֹ חִלִּיז בְּעֵינֵיהּ אוֹ גַרְבָן אוֹ חֲזָזָן אוֹ מְרַס פַּחֲדִין:
@21 כָּל גְּבַר דִּי בֵיהּ מוּמָא מִזַּרְעָא דְּאַהֲרֹן כַּהֲנָא לָא יִקְרַב לְקָרָבָא יָת קֻרְבָּנַיָּא דַיְיָ מוּמָא בֵיהּ יָת קֻרְבַּן אֱלָהֵיהּ לָא יִקְרַב לְקָרָבָא:
@22 קֻרְבַּן אֱלָהֵיהּ מִקֹּדֶשׁ קוּדְשַׁיָּא וּמִן קוּדְשַׁיָּא יֵיכוּל:
@23 בְּרַם לְפָרֻכְתָּא לָא יֵיעוֹל וּלְמַדְבְּחָא לָא יִקְרַב אֲרֵי מוּמָא בֵיהּ וְלָא יַחֵל יָת מַקְדְּשַׁי אֲרֵי אֲנָא יְיָ מְקַדִּשְׁהוֹן:
@24 וּמַלִּיל משֶׁה עִם אַהֲרֹן וְעִם בְּנוֹהִי וְעִם כָּל בְּנֵי יִשְׂרָאֵל:
@25 וּמַלִּיל יְיָ עִם משֶׁה לְמֵימָר:
@26 מַלֵּיל עִם אַהֲרֹן וְעִם בְּנוֹהִי וְיִפָּרְשׁוּן מִקּוּדְשַׁיָּא דִבְנֵי יִשְׂרָאֵל וְלָא יְחַלּוּן יָת שְׁמָא דְקוּדְשִׁי דִּי אִנּוּן מְקַדְּשִׁין קֳדָמַי אֲנָא יְיָ:
@27 אֱמַר לְהוֹן לְדָרֵיכוֹן כָּל גְּבַר דִּי יִקְרַב מִכָּל בְּנֵיכוֹן לְקוּדְשַׁיָּא דִּי יְקַדְּשׁוּן בְּנֵי יִשְׂרָאֵל קֳדָם יְיָ וְסֹאבְתֵיהּ עֲלוֹהִי וְיִשְׁתֵּיצֵי אֲנָשָׁא הַהִיא מִן קֳדָמַי אֲנָא יְיָ:
@28 גְּבַר גְּבַר מִזַּרְעָא דְאַהֲרֹן וְהוּא סְגִיר אוֹ דָאִיב בְּקוּדְשַׁיָּא לָא יֵיכוּל עַד דִּי יִדְכֵּי וּדְיִקְרַב בְּכָל טְמֵא נַפְשָׁא אוֹ גְבַר דִּי תִפּוֹק מִנֵּיהּ שִׁכְבַת זַרְעָא:
@29 אוֹ גְבַר דִּי יִקְרַב בְּכָל רִחֲשָׁא דִּי יִסְתָּאַב לֵיהּ אוֹ בַאֲנָשָׁא דִּי יִסְתָּאַב לֵיהּ לְכֹל סֹאבְתֵיהּ:
@30 אֱנַשׁ דִּי יִקְרַב בֵּיהּ וִיהֵי מְסָאָב עַד רַמְשָׁא וְלָא יֵיכוּל מִן קוּדְשַׁיָּא אֱלָהֵן אַסְחֵי בִשְׂרֵיהּ בְּמַיָּא:
@31 וּבְמֵעַל שִׁמְשָׁא וְיִדְכֵּי וּבָתַר כֵּן יֵיכוּל מִן קוּדְשַׁיָּא אֲרֵי לַחְמֵיהּ הוּא:
@32 נְבִילָא וּתְבִירָא לָא יֵיכוּל לְאִסְתָּאָבָא בַהּ אֲנָא יְיָ:
@33 וְיִטְּרוּן יָת מַטְּרַת מֵימְרִי וְלָא יְקַבְּלוּן עֲלוֹהִי חוֹבָא וִימוּתוּן בֵּיהּ אֲרֵי יְחַלֻּנֵּיהּ אֲנָא יְיָ מְקַדִּשְׁהוֹן:
@34 וְכָל חִלּוֹנַי לָא יֵיכוּל קוּדְשָׁא תּוֹתָבָא דְכַהֲנָא וַאֲגִירָא לָא יֵיכוּל קוּדְשָׁא:
@35 וְכָהֵן אֲרֵי יִקְנֵי נְפַשׁ קִנְיַן כַּסְפֵּיהּ הוּא יֵיכוּל בֵּיהּ וִילִיד בֵּיתֵיהּ אִנּוּן יֵיכְלוּן בְּלַחְמֵיהּ:
@36 וּבַת כָּהֵן אֲרֵי תְהֵי לִגְבַר חִלּוֹנָי הִיא בְּאַפְרָשׁוּת קוּדְשַׁיָּא לָא תֵיכוּל:
@37 וּבַת כָּהֵן אֲרֵי תְהֵי אַרְמְלָא וּמְתָרְכָא וּבַר לֵית לַהּ וּתְתוּב לְבֵית אֲבוּהָא כְּרַבְיוּתָהָא מִלַּחְמָא דַאֲבוּהָא תֵּיכוּל וְכָל חִלּוֹנַי לָא יֵיכוּל בֵּיהּ:
@38 וּגְבַר אֲרֵי יֵיכוּל קוּדְשָׁא בְּשָׁלוּ וְיוֹסֵף חוּמְשֵׁיהּ עֲלוֹהִי וִיתֵּן לְכַהֲנָא יָת קוּדְשָׁא:
@39 וְלָא יְחַלּוּן יָת קוּדְשַׁיָּא דִּבְנֵי יִשְׂרָאֵל יָת דִּי יַפְרְשׁוּן קֳדָם יְיָ:
@40 וִיקַבְּלוּן עֲלֵיהוֹן עֲוָיָן וְחוֹבִין בְּמֵיכָלְהוֹן בְּסוֹאַבָא יָת קוּדְשֵׁיהוֹן אֲרֵי אֲנָא יְיָ מְקַדִּשְׁהוֹן:
@41 וּמַלִּיל יְיָ עִם משֶׁה לְמֵימָר:
@42 מַלֵּיל עִם אַהֲרֹן וְעִם בְּנוֹהִי וְעִם כָּל בְּנֵי יִשְׂרָאֵל וְתֵימַר לְהוֹן גְּבַר גְּבַר מִבֵּית יִשָׂרָאֵל וּמִן גִּיּוֹרָא בְּיִשְׂרָאֵל דִּי יְקָרֵב קֻרְבָּנֵיהּ לְכָל נִדְרֵיהוֹן וּלְכָל נִדְבַתְהוֹן דִּי יְקָרְבוּן קֳדָם יְיָ לַעֲלָתָא:
@43 לְרַעֲוָא לְכוֹן שְׁלִים דְּכוּרָא בְּתוֹרֵי בְּאִמְרַיָּא וּבְעִזַּיָּא:
@44 כֹּל דִּי בֵיהּ מוּמָא לָא תְקָרְבוּן אֲרֵי לָא לְרַעֲוָא יְהֵי לְכוֹן:
@45 וּגְבַר אֲרֵי יְקָרֵב נִכְסַת קוּדְשַׁיָּא קֳדָם יְיָ לְפָרָשָׁא נִדְרָא אוֹ לִנְדַבְתָּא בְּתוֹרֵי אוֹ בְעָנָא שְׁלִים יְהֵי לְרַעֲוָא כָּל מוּמָא לָא יְהֵי בֵיהּ:
@46 עַוִּיר אוֹ תְבִיר אוֹ פְסִיק אוֹ יַבְּלָן אוֹ גַרְבָן אוֹ חֲזָזָן לָא תְקָרְבוּן אִלֵּין קֳדָם יְיָ וְקֻרְבָּנָא לָא תִתְּנוּן מִנְּהוֹן עַל מַדְבְּחָא קֳדָם יְיָ:
@47 וְתוֹר וְאִמַּר יַתִּיר וְחַסִּיר נְדַבְתָּא תַּעְבֵּד יָתֵיהּ וּלְנִדְרָא לָא יְהֵי לְרַעֲוָא:
@48 וְדִי מְרִיס וְדִי רְסִיס וְדִי שְׁלִיף וְדִי גְזִיר לָא תְקָרְבוּן קֳדָם יְיָ וּבְאַרְעֲכוֹן לָא תַעְבְּדוּן:
@49 וּמִן בַּר עַמְמִין לָא תְקָרְבוּן יָת קֻרְבַּן אֱלָהָכוֹן מִכָּל אִלֵּין אֲרֵי חִבּוּלְהוֹן בְּהוֹן מוּמָא בְהוֹן לָא לְרַעֲוָא יְהוֹן לְכוֹן:
@50 וּמַלִּיל יְיָ עִם משֶׁה לְמֵימָר:
@51 תּוֹר אוֹ אִמָּר אוֹ עִזָּא אֲרֵי יִתְיְלִיד וִיהֵי שִׁבְעָא יוֹמִין בָּתַר אִמֵּיהּ וּמִיּוֹמָא תְמִינָאָה וּלְהַלָּא יִתִּרְעֵי לְקָרָבָא קֻרְבָּנָא קֳדָם יְיָ:
@52 וְתוֹרְתָּא אוֹ שֵׂיתָא לַהּ וְלִבְרַהּ לָא תִכְּסוּן בְּיוֹמָא חָד:
@53 וַאֲרֵי תִכְּסוּן נִכְסַת תּוֹדְתָא קֳדָם יְיָ לְרַעֲוָא לְכוֹן תִּכְּסֻנֵּיהּ:
@54 בְּיוֹמָא הַהוּא יִתְאֲכֵל לָא תַשְׁאֲרוּן מִנֵּיהּ עַד צַפְרָא אֲנָא יְיָ:
@55 וְתִטְּרוּן פִּקּוֹדַי וְתַעְבְּדוּן יָתְהוֹן אֲנָא יְיָ:
@56 וְלָא תְחַלְּלוּן יָת שְׁמָא דְקוּדְשַׁי וְאִתְקַדַּשׁ בְּגוֹ בְּנֵי יִשְׂרָאֵל אֲנָא יְיָ מְקַדִּשְׁכוֹן:
@57 דְּאַפִּיק יָתְכוֹן מֵאַרְעָא דְמִצְרַיִם לְמֶהֱוֵי לְכוֹן לֵאלָהָא אֲנָא יְיָ:
@58 וּמַלִּיל יְיָ עִם משֶׁה לְמֵימָר:
@59 מַלֵּיל עִם בְּנֵי יִשְׁרָאֵל וְתֵימַר לְהוֹן מוֹעֲדַיָּא דַיְיָ דִּי תְעָרְעוּן יָתְהוֹן מְעָרְעֵי קַדִּישׁ אִלֵּין אִנּוּן מוֹעֲדָי:
@60 שִׁתָּא יוֹמִין תִּתְעֲבֵד עִבִידָא וּבְיוֹמָא שְׁבִיעָאָה שְׁבַת שְׁבָתָא מְעָרַע קַדִּישׁ כָּל עִבִידָא לָא תַעְבְּדוּן שַׁבְּתָא הִיא קֳדָם יְיָ בְּכֹל מוֹתְבָנֵיכוֹן:
@61 אִלֵּין מוֹעֲדַיָּא דַיְיָ מְעָרְעֵי קַדִּישׁ דִּי תְעָרְעוּן יָתְהוֹן בְּזִמְנֵיהוֹן:
@62 בְּיַרְחָא קַדְמָאָה בְּאַרְבְּעַת עַשְׂרָא לְיַרְחָא בֵּין שִׁמְשַׁיָּא פִּסְחָא קֳדָם יְיָ:
@63 וּבְחַמְשַׁת עַשְׂרָא יוֹמָא לְיַרְחָא הָדֵין חַגָּא דְּפַטִּירַיָּא קֳדָם יְיָ שִׁבְעָא יוֹמִין פַּטִּיר תֵּיכְלוּן:
@64 בְּיוֹמָא קַדְמָאָה מְעָרַע קַדִּישׁ יִהֵי לְכוֹן כָּל עִבִידַת פָּלְחַן לָא תַעְבְּדוּן:
@65 וּתְקָרְבוּן קֻרְבָּנָא קֳדָם יְיָ שִׁבְעָא יוֹמִין בְּיוֹמָא שְׁבִיעָאָה מְעָרַע קַדִּישׁ כָּל עִבִידַת פָּלְחָן לָא תַעְבְּדוּן:
@66 וּמַלִּיל יְיָ עִם משֶׁה לְמֵימָר:
@67 מַלֵּיל עִם בְּנֵי יִשְׂרָאֵל וְתֵימַר לְהוֹן אֲרֵי תֵעֲלוּן לְאַרְעָא דִּי אֲנָא יָהֵב לְכוֹן וְתַחְצְדוּן יָת חֲצָדַהּ וְתַיְתוּן יָת עוּמְרָא רֵישׁ חֲצָדְכוֹן לְוָת כַּהֲנָא:
@68 וִירִים יָת עוּמְרָא קֳדָם יְיָ לְרַעֲוָא לְכוֹן מִבָּתַר יוֹמָא טָבָא יְרִימִנֵּיהּ כַּהֲנָא:
@69 וְתַעְבְּדוּן בְּיוֹמָא דַאֲרָמוּתְכוֹן יָת עוּמְרָא אִמַּר שְׁלִים בַּר שַׁתֵּיהּ לַעֲלָתָא קֳדָם יְיָ:
@70 וּמִנְחָתֵיהּ תְּרֵין עֶשְׁרוֹנִין סֻלְתָּא דְּפִילָא בִמְשַׁח קֻרְבָּנָא קֳדָם יְיָ לְאִתְקַבָּלָא בְרַעֲוָא וְנִסְכֵּיהּ חַמְרָא רַבְעוּת הִינָא:
@71 וּלְחֵם וּקְלִי וּפֵרוּכָן לָא תֵיכְלוּן עַד כְּרַן יוֹמָא הָדֵין עַד אַיְתוֹאֵיכוֹן יָת קֻרְבָּן אֱלָהָכוֹן קְיַם עָלָם לְדָרֵיכוֹן בְּכֹל מוֹתְבָנֵיכוֹן:
@72 וְתִמְנוּן לְכוֹן מִבָּתַר יוֹמָא טָבָא מִיּוֹם אַיְתוֹאֵיכוֹן יָת עוּמְרָא דַאֲרָמוּתָא שִׁבְעָא שָׁבוּעִין שַׁלְמִין יְהֶוְיָן:
@73 עַד מִבָּתַר שְׁבוּעֲתָא שְׁבִיעֵתָא תִּמְנוּן חַמְשִׁין יוֹמִין וּתְקָרְבוּן מִנְחָתָא חֲדַתָּא קֳדָם יְיָ:
@74 מִמּוֹתְבָנֵיכוֹן תַּיְתוּן לְחֵם אֲרָמוּתָא תַּרְתֵּין (גְּרִיצַן) תְּרֵין עֶשְׁרוֹנִין סֻלְתָּא יְהֶוְיָן חֲמִיעַ יִתְאַפְיָן בִּכּוּרִין קֳדָם יְיָ:
@75 וּתְקָרְבוּן עַל לַחְמָא שִׁבְעָא אִמְּרִין שַׁלְמִין בְּנֵי שְׁנָא וְתוֹר בַּר תּוֹרֵי חַד וְדִכְרִין תְּרֵין יְהוֹן עֲלָתָא קֳדָם יְיָ וּמִנְחָתְהוֹן וְנִסְכֵּיהוֹן קֻרְבַּן דְּמִתְקַבֵּל בְּרַעֲוָא קֳדָם יְיָ:
@76 וְתַעְבְּדוּן צְפִיר בַּר עִזֵּי חַד לְחַטָּאתָא וּתְרֵין אִמְּרִין בְּנֵי שְׁנָא לְנִכְסַת קוּדְשַׁיָּא:
@77 וִירִים כַּהֲנָא יָתְהוֹן עַל לְחֵם בִּכּוּרַיָּא אֲרָמוּתָא קֳדָם יְיָ עַל תְּרֵין אִמְּרִין קוּדְשָׁא יְהוֹן קֳדָם יְיָ לְכַהֲנָא:
@78 וּתְעָרְעוּן בִּכְרַן יוֹמָא הָדֵין מְעָרַע קַדִּישׁ יְהֵי לְכוֹן כָּל עִבִידַת פָּלְחָן לָא תַעְבְּדוּן קְיַם עָלָם בְּכָל מוֹתְבָנֵיכוֹן לְדָרֵיכוֹן:
@79 וּבְמֶחֱצָדְכוֹן יָת חֲצָדָא דְאַרְעֲכוֹן לָא תְשֵׁיצֵי פָּאתָא דְחַקְלָךְ בְּמֶחֱצָדָךְ וּלְקָטָא דַחֲצָדָךְ לָא תְלַקֵּט לְעַנְיֵי וּלְגִיּוֹרֵי תִּשְׁבּוֹק יָתְהוֹן אֲנָא יְיָ אֱלָהָכוֹן:
@80 וּמַלִּיל יְיָ עִם משֶׁה לְמֵימָר:
@81 מַלֵּיל עִם בְּנֵי יִשְׂרָאֵל לְמֵימָר בְּיַרְחָא שְׁבִיעָאָה בְּחַד לְיַרְחָא יְהֵי לְכוֹן נְיָחָא דּוּכְרַן יַבָּבָא מְעָרַע קַדִּישׁ:
@82 כָּל עִבִידַת פָּלְחָנָא לָא תַעְבְּדוּן וּתְקָרְבוּן קֻרְבָּנָא קֳדָם יְיָ:
@83 וּמַלִּיל יְיָ עִם משֶׁה לְמֵימָר:
@84 בְּרַם בְּעַשְׂרָא לְיַרְחָא שְׁבִיעָאָה הָדֵין יוֹמָא דְכִפּוּרַיָּא הוּא מְעָרַע קַדִּישׁ יְהֵי לְכוֹן וּתְעַנּוּן יָת נַפְשָׁתֵיכוֹן וּתְקָרְבוּן קֻרְבָּנָא קֳדָם יְיָ:
@85 וְכָל עִבִידָא לָא תַעְבְּדוּן בִּכְרַן יוֹמָא הָדֵין אֲרֵי יוֹמָא דְכִפּוּרַיָּא הוּא לְכַפָּרָא עֲלֵיכוֹן קֳדָם יְיָ אֱלָהָכוֹן:
@86 אֲרֵי כָל אֲנָשָׁא דִּי לָא מִתְעַנֵּי בִּכְרַן יוֹמָא הָדֵין וְיִשְׁתֵּיצֵי מֵעַמָּהָא:
@87 וְכָל אֱנַשׁ דִּי תַעְבֵּד כָּל עִבִידָא בִּכְרַן יוֹמָא הָדֵין וְאוֹבֵד יָת אֲנָשָׁא הַהִיא מִגּוֹ עַמַּהּ:
@88 כָּל עִבִידָא לָא תַעְבְּדוּן קְיַם עָלָם לְדָרֵיכוֹן בְּכֹל מוֹתְבָנֵיכוֹן:
@89 שְׁבַת שְׁבָתָא הוּא לְכוֹן וּתְעַנּוּן יָת נַפְשָׁתֵיכוֹן בְּתִישְׁעָא לְיַרְחָא בְּרַמְשָׁא מֵרַמְשָׁא עַד רַמְשָׁא תְּנוּחוּן נְיַחֲכוֹן:
@90 וּמַלִּיל יְיָ עִם משֶׁה לְמֵימָר:
@91 מַלֵּיל עִם בְּנֵי יִשְׂרָאֵל לְמֵימָר בְּחַמְשָׁא עַשְׁרָא יוֹמָא לְיַרְחָא שְׁבִיעָאָה הָדֵין חַגָּא דִמְטַלַּיָּא שִׁבְעַת יוֹמִין קֳדָם יְיָ:
@92 בְּיוֹמָא קַדְמָאָה מְעָרַע קַדִּישׁ כָּל עִבִידַת פָּלְחָן לָא תַעְבְּדוּן:
@93 שִׁבְעָא יוֹמִין תְּקָרְבוּן קֻרְבָּנָא קֳדָם יְיָ בְּיוֹמָא תְמִינָאָה מְעָרַע קַדִּישׁ יְהֵי לְכוֹן וּתְקָרְבוּן קֻרְבָּנָא קֳדָם יְיָ כְּנֵשׁ תְּהוֹן כָּל עִבִידַת פָּלְחָן לָא תַעְבְּדוּן:
@94 אִלֵּין מוֹעֲדַיָּא דַיְיָ דִּי תְעָרְעוּן יָתְהוֹן מְעָרְעֵי קַדִּישׁ לְקָרָבָא קֻרְבָּנָא קֳדָם יְיָ עֲלָתָא וּמִנְחָתָא נִכְסַת קוּדְשִׁין וְנִסּוּכִין פִּתְגַם יוֹם בְּיוֹמֵיהּ:
@95 בַּר שַׁבַּיָּא דַיְיָ וּבַר מַתְּנָתֵיכוֹן וּבַר כָּל נִדְרֵיכוֹן וּבַר כָּל נִדְבָתֵיכוֹן דִּי תִתְּנוּן קֳדָם יְיָ:
@96 בְּרַם בְּחַמְשָׁא עֲשַׁר יוֹמָא לְיַרְחָא שְׁבִיעָאָה בְּמִכְנְשֵׁיכוֹן יָת עֲלַלַת אַרְעָא תְּחַגּוּן יָת חַגָּא קֳדָם יְיָ שִׁבְעָא יוֹמִין בְּיוֹמָא קַדְמָאָה נְיָחָא וּבְיוֹמָא תְמִינָאָה נְיָחָא:
@97 וְתִסְּבוּן לְכוֹן בְּיוֹמָא קַדְמָאָה פֵּרֵי אִילָנָא אֶתְרוֹגִין וְלֻלַּבִּין וַהֲדַסִּין וְעַרְבִין דִּנְחָל וְתֶחֱדוּן קֳדָם יְיָ אֱלָהָכוֹן שַׁבְעַת יוֹמִין:
@98 וּתְחַגּוּן יָתֵיהּ חַגָּא קֳדָם יְיָ שַׁבְעַת יוֹמִין בְּשַׁתָּא קְיַם עָלָם לְדָרֵיכוֹן בְּיַרְחָא שְׁבִיעָאָה תְּחַגּוּן יָתֵיהּ:
@99 בִּמְטַלַּיָּא תֵיתְבוּן שַׁבְעַת יוֹמִין כָּל יַצִּיבָא בְּיִשְׂרָאֵל יֵתְבוּן בִּמְטַלַּיָּא:
@100 בְּדִיל דִּיִדְּעוּן דָּרֵיכוֹן אֲרֵי בִמְטַלָּיוּת עֲנָנֵי אוֹתֵבִית יָת בְּנֵי יִשְׂרָאֵל בְּאַפָּקוּתִי יָתְהוֹן מֵאַרְעָא דְמִצְרָיִם אֲנָא יְיָ אֱלָהָכוֹן:
@101 וּמַלִּיל משֶׁה יָת סְדַר מוֹעֲדַיָּא דַיְיָ וְאַלֵּפִנּוּן לִבְנֵי יִשְׂרָאֵל:
@102 וּמַלִּיל יְיָ עִם משֶׁה לְמֵימָר:
@103 פַּקֵּד יָת בְּנֵי יִשְׂרָאֵל וְיִסְּבוּן לָךְ מְשַׁח זֵיתָא דַכְיָא כָּתִישָׁא לְאַנְהָרָא לְאַדְלָקָא בוֹצִינַיָּא תְּדִירָא:
@104 מִבָּרָא לְפָרֻכְתָּא דְסַהֲדוּתָא בְּמַשְׁכַּן זִמְנָא יַסְדַּר יָתֵיהּ אֲהֲרֹן מֵרַמְשָׁא עַד צַפְרָא קֳדָם יְיָ תְּדִירָא קְיָם עָלָם לְדָרֵיכוֹן:
@105 עַל מְנַרְתָּא דָכִיתָא יַסְדַּר יָת בּוֹצִינַיָּא קֳדָם יְיָ תְּדִירָא:
@106 וְתִסַּב סֻלְתָּא וְתֵיפֵי יָתַהּ תַּרְתָּא עַשְׂרֵי גְּרִיצָן תְּרֵין עֶשְׂרוֹנִין תְּהֵי גְּרִצְתָּא חֲדָא:
@107 וּתְשַׁוִּי יָתְהוֹן תַּרְתֵּין סִדְרִין שִׁית סִדְרָא עַל פָּתוֹרָא דַכְיָא קֳדָם יְיָ:
@108 וְתִתֵּן עַל סִדְרָא לְבֻנְתָּא דָכִיתָא וּתְהֵי לִלְחֵם לְאִדְכַּרְתָּא קֻרְבָּנָא קֳדָם יְיָ:
@109 בְּיוֹמָא דְשַׁבְּתָא בְּיוֹמָא דְשַׁבְּתָא יַסְדְּרִנֵּיהּ קֳדָם יְיָ תְּדִירָא מִן קֳדָם בְּנֵי יִשְׂרָאֵל קְיַם עָלָם:
@110 וּתְהֵי לְאַהֲרֹן וְלִבְנוֹהִי וְיֵכְלֻנֵּיהּ בַּאֲתַר קַדִּישׁ אֲרֵי קֹדֶשׁ קוּדְשִׁין הוּא לֵיהּ מִקֻּרְבָּנַיָּא דַיְיָ קְיַם עָלָם:
@111 וּנְפַק בַּר אִתְּתָא בַת יִשְׂרָאֵל וְהוּא בַּר גְּבַר מִצְרָאָה בְּגוֹ בְּנֵי יִשְׂרָאֵל וּנְצוֹ בְּמַשְׁרִיתָא בַּר אִתְּתָא בַת יִשְׂרָאֵל וְגַבְרָא בַּר יִשְׂרָאֵל:
@112 וּפָרֵשׁ בַּר אִתְּתָא בַת יִשְׂרָאֵל יָת שְׁמָא וְאַרְגֵּז וְאַיְתִיאוּ יָתֵיהּ לְוָת משֶׁה וְשׁוּם אִמֵּיהּ שְׁלֹּמִית בַּת דִּבְרִי לְשִׁבְטָא דְדָן:
@113 וְאַסְּרוֹהִי בְּבֵית מַטְּרָא עַד דְּיִתְפָּרַשׁ לְהוֹן עַל גְּזֵרַת מֵימְרָא דַיְיָ:
@114 וּמַלִּיל יְיָ עִם משֶׁה לְמֵימָר:
@115 אַפֵּק יָת דְּאַרְגֵּז לְמִבָּרָא לְמַשְׁרִיתָא וְיִסְמְכוּן כָּל דִּי שְׁמָעוּ יָת יְדֵיהוֹן עַל רֵישֵׁיהּ וְיִרְגְּמוּן יָתֵיהּ כָּל כְּנִשְׁתָּא:
@116 וְעִם בְּנֵי יִשְׂרָאֵל תְּמַלֵּל לְמֵימָר גְּבַר גְּבַר דִּי יַרְגֵּז קֳדָם אֱלָהֵיהּ וִיקַבֵּל חוֹבֵיהּ:
@117 וְדִי פָרֵשׁ שְׁמָא דַיְיָ אִתְקְטָלָא יִתְקְטֵל מִרְגַּם יִרְגְּמוּן בֵּיהּ כָּל כְּנִשְׁתָּא כְּגִיּוֹרָא כְּיַצִּיבָא בְּפָרָשׁוּתֵיהּ שְׁמָא יִתְקְטֵל:
@118 וּגְבַר אֲרֵי יִקְטוֹל כָּל נַפְשָׁא דַאֲנָשָׁא אִתְקְטָלָא יִתְקְטֵל:
@119 וּדְיִקְטוֹל נְפַשׁ בְּעִירָא יְשַׁלְּמִנַּהּ נַפְשָׁא חֲלַף נַפְשָׁא:
@120 וּגְבַר אֲרֵי יִתֵּן מוּמָא בְּחַבְרֵיהּ כְּמָא דִי עֲבַד כֵּן יִתְעֲבֶד לֵיהּ:
@121 תַּבְרָא חֳלַף תַּבְרָא עֵינָא חֳלַף עֵינָא שִׁנָּא חֳלַף שִׁנָּא כְּמָא דִי יִתֵּן מוּמָא בַּאֲנָשָׁא כֵּן יִתְיְהֶב בֵּיהּ:
@122 וּדְיִקְטוֹל בְּעִירָא יְשַׁלְּמִנַּהּ וּדְיִקְטוֹל אֲנָשָׁא יִתְקְטֵל:
@123 דִּינָא חֲדָא יְהֵי לְכוֹן כְּגִיּוֹרָא כְיַצִּיבָא יְהֵי אֲרֵי אֲנָא יְיָ אֱלָהָכוֹן:
@124 וּמַלִּיל משֶׁה עִם בְּנֵי יִשְׂרָאֵל וְאַפִּיקוּ יָת דְּאַרְגֵּז לְמִבָּרָא לְמַשְׁרִיתָא וּרְגָמוּ יָתֵיהּ אַבְנָא וּבְנֵי יִשְׂרָאֵל עֲבָדוּ כְּמָא דִי פַקֵּיד יְיָ יָת משֶׁה:

@1 **אמר אל הכהנים.** אמר ואמרת, לְהַזְהִיר גְּדוֹלִים עַל הַקְּטַנִּים (יבמות קי"ד):
@1 **בני אהרן.** יָכוֹל חֲלָלִים תַּ"ל הַכֹּהֲנִים:
@1 **בני אהרן.** אַף בַּעֲלֵי מוּמִין בְּמַשְׁמָע:
@1 **בני אהרן.** וְלֹא בְּנוֹת אַהֲרֹן (ספרא):
@1 **לא יטמא בעמיו.** בְּעוֹד שֶׁהַמֵּת בְּתוֹךְ עַמָּיו, יָצָא מֵת מִצְוָה (שם):
@2 **כי אם לשארו.** אֵין שְׁאֵרוֹ אֶלָּא אִשְׁתּוֹ (שם; יבמות כ"ב):
@3 **הקרובה.** לְרַבּוֹת אֶת הָאֲרוּסָה (ספרא; יבמות ס'):
@3 **אשר לא היתה לאיש.** לְמִשְׁכָּב:
@3 **לה יטמא.** מִצְוָה (ספרא; זבחים ק'):
@4 **לא יטמא בעל בעמיו להחלו.** לֹא יִטַּמָּא לְאִשְׁתּוֹ פְּסוּלָה שֶׁהוּא מְחֻלָּל בָּהּ בְּעוֹדָהּ עִמּוֹ, וְכֵן פְּשׁוּטוֹ שֶׁל מִקְרָא: לֹא יִטַּמָּא בַּעַל בִּשְׁאֵרוֹ בְּעוֹד שֶׁהוּא בְּתוֹךְ עַמָּיו — שֶׁיֵּשׁ לָהּ קוֹבְרִין, שֶׁאֵינָהּ מֵת מִצְוָה, וּבְאֵיזֶה שְׁאֵר אָמַרְתִּי? בְּאוֹתוֹ שֶׁהוּא לְהֵחַלּוֹ — לְהִתְחַלֵּל הוּא מִכְּהֻנָּתוֹ (עי' ספרא; יבמות צ'):
@5 **לא יקרחה קרחה.** עַל מֵת וַהֲלֹא אַף יִשְׂרָאֵל הֻזְהֲרוּ עַל כָּךְ? אֶלָּא לְפִי שֶׁנֶּאֱמַר בְּיִשְׂרָאֵל בֵּין עֵינֵיכֶם (דברים י"ד), יָכוֹל לֹא יְהֵא חַיָּב עַל כָּל הָרֹאשׁ, תַּ"ל בְּרֹאשָׁם, וְיִלָּמְדוּ יִשְׂרָאֵל מִכֹּהֲנִים בִּגְזֵרָה שָׁוָה, נֶאֱמַר כָּאן קָרְחָה וְנֶאֱמַר בְּיִשְׂרָאֵל קָרְחָה, מַה כָּאן כָּל הָרֹאשׁ אַף לְהַלָּן כָּל הָרֹאשׁ בְּמַשְׁמָע — כָּל מָקוֹם שֶׁיִּקְרַח בָּרֹאשׁ, וּמַה לְּהַלָּן עַל מֵת, אַף כָּאן עַל מֵת (מכות כ'):
@5 **ופאת זקנם לא יגלחו.** לְפִי שֶׁנֶּאֱמַר בְּיִשְֹרָאֵל לֹא תַשְׁחִית, יָכוֹל לִקְּטוֹ בְּמַלְקֵט וּרְהִיטְנִי יְהֵא חַיָּב, לְכָךְ נֶאֱמַר לֹא יְגַלֵּחוּ. שֶׁאֵינוֹ חַיָּב אֶלָּא עַל דָּבָר הַקָּרוּי גִּלּוּחַ וְיֵשׁ בּוֹ הַשְׁחָתָה, וְזֶהוּ תַעַר (שם):
@5 **ובבשרם לא ישרטו שרטת.** לְפִי שֶׁנֶּאֱמַר בְּיִשְׂרָאֵל וְשֶׂרֶט לָנֶפֶשׁ לֹא תִתְּנוּ (ויקרא י"ט), יָכוֹל שָׂרַט חָמֵשׁ שְׂרִיטוֹת לֹא יְהֵא חַיָּב אֶלָּא אַחַת, תַּ"ל לֹא יִשְׂרְטוּ שָׂרָטֶת, לְחַיֵּב עַל כָּל שְׂרִיטָה וּשְׂרִיטָה, שֶׁתֵּבָה זוֹ יְתֵרָה הִיא לִדְרֹשׁ, שֶׁהָיָה לוֹ לִכְתֹּב לֹא יִשְׂרְטוּ וַאֲנִי יוֹדֵעַ שֶׁהִיא שָׂרֶטֶת (ספרא; מב' כ'):
@6 **קדשים יהיו.** עַל כָּרְחָם יַקְדִּישׁוּם בֵּית דִּין בְּכָךְ (ספרא):
@7 **זנה.** שֶׁנִּבְעֲלָה בְעִילַת יִשְׂרָאֵל הָאָסוּר לָהּ, כְּגוֹן חַיָּבֵי כָּרֵתוֹת אוֹ נָתִין אוֹ מַמְזֵר (ספרא; יבמות ס"א):
@7 **חללה.** שֶׁנּוֹלְדָה מִן הַפְּסוּלִים שֶׁבַּכְּהֻנָּה, כְּגוֹן בַּת אַלְמָנָה מִכֹּהֵן גָּדוֹל אוֹ בַת גְּרוּשָׁה (וַחֲלוּצָה) מִכֹּהֵן הֶדְיוֹט, וְכֵן שֶׁנִּתְחַלְּלָה מִן הַכְּהֻנָּה עַל יְדֵי בִיאַת אֶחָד מִן הַפְּסוּלִים לִכְהֻנָּה (עי' ספרא, קידושין ע"ז):
@8 **וקדשתו.** עַל כָּרְחוֹ, שֶׁאִם לֹא רָצָה לְגָרֵשׁ הַלְקֵהוּ וְיַסְּרֵהוּ עַד שֶׁיְּגָרֵשׁ (ספרא; יבמות פ"ח):
@8 **קדש יהיה לך.** נְהֹג בּוֹ קְדֻשָּׁה, לִפְתֹּחַ רִאשׁוֹן בְּכָל דָּבָר וּלְבָרֵךְ רִאשׁוֹן בַּסְּעוּדָה (הוריות י"ב):
@9 **כי תחל לזנות.** כְּשֶׁתִּתְחַלֵּל עַ"יְ זְנוּת, שֶׁהָיְתָה בָהּ זִקַּת בַּעַל וְזָנְתָה, אוֹ מִן הָאֵרוּסִין אוֹ מִן הַנִּשּׂוּאִין; וְרַבּוֹתֵינוּ נֶחְלְקוּ בַדָּבָר וְהַכֹּל מוֹדִים שֶׁלֹּא דִּבֵּר הַכָּתוּב בִּפְנוּיָה (עי' סנהדרין נ"א):
@9 **את אביה היא מחללת.** חִלְּלָה וּבִזְּתָה אֶת כְּבוֹדוֹ, שֶׁאוֹמְרִים עָלָיו אָרוּר שֶׁזּוֹ יָלַד, אָרוּר שֶׁזּוֹ גִּדֵּל (שם):
@10 **לא יפרע.** לֹא יְגַדֵּל פֶּרַע עַל אֵבֶל, וְאֵיזֶהוּ גִּדּוּל פֶּרַע? יוֹתֵר מִשְּׁלוֹשִׁים יוֹם (שם):
@11 **ועל כל נפשת מת וגו'.** בְּאֹהֶל הַמֵּת:
@11 **נפשת מת.** לְהָבִיא רְבִיעִית דָּם מִן הַמֵּת שֶׁמְּטַמֵּא בָאֹהֶל (שם):
@11 **לאביו ולאמו לא יטמא.** לֹא בָא אֶלָּא לְהַתִּיר לוֹ מֵת מִצְוָה (ספרא; נזיר מ"ז):
@12 **ומן המקדש לא יצא.** אֵינוֹ הוֹלֵךְ אַחַר הַמִּטָּה (סנהדרין י"ח), וְעוֹד מִכָּאן לָמְדוּ רַבּוֹתֵינוּ שֶׁכֹּהֵן גָּדוֹל מַקְרִיב אוֹנֵן, וְכֵן מַשְׁמָעוֹ: אַף אִם מֵתוּ אָבִיו וְאִמּוֹ אֵינוֹ צָרִיךְ לָצֵאת מִן הַמִּקְדָּשׁ אֶלָּא עוֹבֵד עֲבוֹדָה:
@12 **ולא יחלל את מקדש.** שֶׁאֵינוֹ מְחַלֵּל בְּכָךְ אֶת הָעֲבוֹדָה, שֶׁהִתִּיר לוֹ הַכָּתוּב, הָא כֹּהֵן הֶדְיוֹט שֶׁעָבַד אוֹנֵן חִלֵּל (זבחים ט"ז; סנהדרין פ"ח):
@14 **וחללה.** שֶׁנּוֹלְדָה מִפְּסוּלֵי כְהֻנָּה (קידושין ע"ז):
@15 **ולא יחלל זרעו.** הָא אִם נָשָׂא אַחַת מִן הַפְּסוּלוֹת, זַרְעוֹ הֵימֶנָּה חָלָל מִדִּין קְדֻשַּׁת כְּהֻנָּה (שם):
@17 **לחם אלהיו.** מַאֲכַל אֱלֹהָיו, כָּל סְעוּדָה קְרוּיָה לֶחֶם, כְּמוֹ "עֲבַד לְחֶם רַב" (דניאל ה'):
@18 **כי כל איש אשר בו מום לא יקרב.** אֵינוֹ דִין שֶׁיִּקְרַב, כְּמוֹ הַקְרִיבֵהוּ נָא לְפֶחָתֶךָ (מלאכי א'):
@18 **חרם.** שֶׁחָטְמוֹ שָׁקוּעַ בֵּין שְׁתֵּי הָעֵינַיִם, שֶׁכּוֹחֵל שְׁתֵּי עֵינָיו כְּאַחַת (ספרא; בכורות מ"ג):
@18 **שרוע.** שֶׁאֶחָד מֵאֵבָרָיו גָּדוֹל מֵחֲבֵרוֹ — עֵינוֹ אַחַת גְּדוֹלָה וְעֵינוֹ אַחַת קְטַנָּה, אוֹ שׁוֹקוֹ אַחַת אֲרֻכָּה מֵחֲבֶרְתָּהּ (ספרא; בכורות מ'):
@20 **או גבן.** שׁורי"ציולש בְּלַעַז, שֶׁגְּבִינֵי עֵינָיו שְׂעָרָן אָרֹךְ וְשׁוֹכֵב:
@20 **או דק.** שֶׁיֵּשׁ לוֹ בְעֵינָיו דֹּק, שֶׁקּוֹרִים טיל"א, כְּמוֹ "הַנּוֹטֶה כַדֹּק" (ישעיהו מ'):
@20 **או תבלל.** דָּבָר הַמְבַלְבֵּל אֶת הָעַיִן, כְּגוֹן חוּט לָבָן הַנִּמְשָׁךְ מִן הַלֹּבֶן וּפוֹסֵק בַּסִּירָא, שֶׁהוּא עֹגֶל הַמַּקִּיף אֶת הַשָּׁחֹר שֶׁקּוֹרִים פרוני"לא, וְהַחוּט הַזֶּה פּוֹסֵק אֶת הָעֹגֶל וְנִכְנָס בַּשָּׁחֹר; וְתַרְגּוּם תְּבַלּוּל "חִלִּיז", לְשׁוֹן חִלָּזוֹן, שֶׁהוּא דוֹמֶה לְתוֹלַעַת אוֹתוֹ הַחוּט, וְכֵן כִּנּוּהוּ חַכְמֵי יִשְֹרָאֵל בְּמוּמֵי הַבְּכוֹר חִלָּזוֹן, נָחָשׁ, עֵינָב (בכורות ל"ח):
@20 **גרב או ילפת.** מִינֵי שְׁחִין הֵם; גָּרָב זוֹ הַחֶרֶס, שְׁחִין הַיָּבֵשׁ מִבִּפְנִים וּמִבַּחוּץ, יַלֶּפֶת הִיא חֲזָזִית הַמִּצְרִית, וְלָמָּה נִקְרֵאת יַלֶּפֶת? שֶׁמְּלַפֶּפֶת וְהוֹלֶכֶת עַד יוֹם הַמִּיתָה, וְהוּא לַח מִבַּחוּץ וְיָבֵשׁ מִבִּפְנִים, וּבְמָקוֹם אַחֵר קוֹרֵא לַגָּרָב שְׁחִין הַלַּח מִבַּחוּץ וְיָבֵשׁ מִבִּפְנִים, שֶׁנֶּאֱמַר "וּבַגָּרָב וּבֶחָרֶס" (דברים כ"ח), כְּשֶׁסָּמַךְ גָּרָב אֵצֶל חֶרֶס, קוֹרֵא לַיַּלֶּפֶת גָּרָב, וּכְשֶׁהוּא סָמוּךְ אֵצֶל יַלֶּפֶת, קוֹרֵא לַחֶרֶס גָּרָב, כָּךְ מְפֹרָשׁ בִּבְכוֹרוֹת (דף מ"א):
@20 **מרוח אשך.** לְפִי הַתַּרְגּוּם מְרַס פַּחֲדִין, שֶׁפְּחָדָיו מְרֻסָּסִין — שֶׁבֵּיצִים שֶׁלּוֹ כְתוּתִין, פְּחָדִין כְּמוֹ "גִּידֵי פַחֲדָו יְשֹׂרָגוּ" (איוב מ'):
@21 **כל איש אשר בו מום.** לְרַבּוֹת שְׁאָר מוּמִין:
@21 **מום בו.** בְּעוֹד מוּמוֹ בּוֹ פָּסוּל, הָא אִם עָבַר מוּמוֹ כָּשֵׁר (ספרא):
@21 **לחם אלהיו.** כָּל מַאֲכָל קָרוּי לֶחֶם:
@22 **מקדשי הקדשים.** אֵלּוּ קָדְשֵׁי הַקֳּדָשִׁים:
@22 **ומן הקדשים יאכל.** אֵלּוּ קָדָשִׁים קַלִּים, וְאִם נֶאֶמְרוּ קָדְשֵׁי הַקֳּדָשִׁים לָמָּה נֶאֱמַר קָדָשִׁים קַלִּים? אִם לֹא נֶאֱמַר, הָיִיתִי אוֹמֵר בְּקָדְשֵׁי הַקֳּדָשִׁים יֹאכַל בַּעַל מוּם, שֶׁמָּצִינוּ שֶׁהֻתְּרוּ לְזָר, שֶׁאָכַל מֹשֶׁה בְּשַׂר הַמִּלּוּאִים, אֲבָל בְּחָזֶה וְשׁוֹק שֶׁל קָדָשִׁים קַלִּים לֹא יֹאכַל, שֶׁלֹּא מָצִינוּ זָר חוֹלֵק בָּהֶן, לְכָךְ נֶאֶמְרוּ קָדָשִׁים קַלִּים, כָּךְ מְפֹרָשׁ בִּזְבָחִים (דף ק"א):
@23 **אך אל הפרכת.** לְהַזּוֹת שֶׁבַע הַזָּאוֹת שֶׁעַל הַפָּרֹכֶת.
@23 **ואל המזבח.** הַחִיצוֹן; וּשְׁנֵיהֶם הֻצְרְכוּ לִכָּתֵב, וּמְפֹרָשׁ בְּתֹ"כֹּ:
@23 **ולא יחלל את מקדשי.** שֶׁאִם עָבַד עֲבוֹדָתוֹ מְחֻלֶּלֶת לִפָּסֵל (ספרא):
@24 **וידבר משה.** הַמִּצְוָה הַזֹּאת.
@24 **אל אהרן ואל בניו ואל כל בני ישראל.** לְהַזְהִיר בֵּית דִּין עַל הַכֹּהֲנִים (עי' ספרא):
@26 **וינזרו.** אֵין נְזִירָה אֶלָּא פְרִישָׁה, וְכֵן הוּא אוֹמֵר "וַיִּנָּזֵר מֵאַחֲרַי" (יחזקאל י"ד), "נָזֹרוּ אָחוֹר" (ישעיהו א') — יִפְרְשׁוּ מִן הַקֳּדָשִׁים בִּימֵי טֻמְאָתָן (ספרא):
@26 **וינזרו מקדשי בני ישראל, אשר הם מקדשים לי ולא יחללו את שם קדשי.** סָרֵס הַמִּקְרָא וְדָרְשֵׁהוּ:
@26 **אשר הם מקדשים לי.** לְרַבּוֹת קָדְשֵׁי כֹהֲנִים עַצְמָן:
@27 **כל איש אשר יקרב.** אֵין קְרִיבָה זוֹ אֶלָּא אֲכִילָה, וְכֵן מָצִינוּ שֶׁנֶּאֶמְרָה אַזְהָרַת אֲכִילַת קָדָשִׁים בְּטֻמְאָה בִּלְשׁוֹן נְגִיעָה, "בְּכָל קֹדֶשׁ לֹא תִגָּע" (ויקרא י"ב), אַזְהָרָה לָאוֹכֵל, וּלְמָדוּהָ רַבּוֹתֵינוּ מִגְּזֵרָה שָׁוָה; וְאִאֶ"ל שֶׁחַיָּב עַל הַנְּגִיעָה, שֶׁהֲרֵי נֶאֱמַר כָּרֵת עַל הָאֲכִילָה בְּצַו אֶת אַהֲרֹן (ויקרא ז'), שְׁתֵּי כָּרֵתוֹת זוֹ אֵצֶל זוֹ, וְאִם עַל הַנְּגִיעָה חַיָּב, לֹא הֻצְרַךְ לְחַיְּבוֹ עַל הָאֲכִילָה וְכֵן נִדְרַשׁ בְּתֹ"כֹּ: וְכִי יֵשׁ נוֹגֵעַ חַיָּב? אִם כֵּן מַה תַּ"ל יִקְרַב? מִשֶּׁיִּכְשַׁר לִקָּרֵב, שֶׁאֵין חַיָּבִים עָלָיו מִשּׁוּם טֻמְאָה אֶלָּא אִ"כֵּ קָרְבוּ מַתִּירָיו (ספרא; זבחים מ"ה): וְאִ"תֹּ שָׁלוֹשׁ כָּרֵתוֹת בְּטֻמְאַת כֹּהֲנִים לָמָּה, כְּבָר נִדְרְשׁוּ בְּמַסֶּכֶת שְׁבוּעוֹת (דף ז'), אַחַת לִכְלָל וְאַחַת לִפְרָט וְכוּ':
@27 **וטמאתו עליו.** וְטֻמְאַת הָאָדָם עָלָיו, יָכוֹל בַּבָּשָׂר הַכָּתוּב מְדַבֵּר — וְטֻמְאָתוֹ שֶׁל בָּשָׂר עָלָיו — וּבְטָהוֹר שֶׁאָכַל אֶת הַטָּמֵא הַכָּתוּב מְדַבֵּר, עַל כָּרְחֲךָ מִמַּשְׁמָעוֹ אַתָּה לָמֵד — בְּמִי שֶׁטֻּמְאָתוֹ פּוֹרַחַת מִמֶּנּוּ הַכָּתוּב מְדַבֵּר, וְזֶהוּ הָאָדָם שֶׁיֵּשׁ לוֹ טָהֳרָה בִּטְבִילָה (ספרא):
@27 **ונכרתה.** יָכוֹל מִצַּד זֶה לְצַד זֶה — יִכָּרֵת מִמְּקוֹמוֹ וְיִתְיַשֵּׁב בְּמָקוֹם אַחֵר — תַּ"ל **אני ה'** , בְּכָל מָקוֹם אֲנִי (שם):
@28 **מזרע אהרן.** אין לי אלא זרעו, גופו מנין, תלמוד לומר והוא צרוע, שיכול הואיל ומקריב אונן יקריב צרוע וזב, תלמוד לומר והוא:
@28 **עד אשר יטהר.** ביאת השמש, או אינו אלא טבילה, נאמר כאן וטהר, ונאמר למטה וטהר (פסוק ז) ובא השמש וטהר, מה להלן ביאת שמש, אף כאן ביאת שמש:
@28 **בכל טמא נפש.** בְּמִי שֶׁנִּטְמָא בְמֵת:
@29 **בכל שרץ אשר יטמא לו.** בְּשִׁעוּר הָרָאוּי לְטַמֵּא — בְּכָעֲדָשָׁה (חגיגה י"א):
@29 **או באדם.** בְּמֵת:
@29 **אשר יטמא לו.** בְּשִׁעוּרוֹ לְטַמֵּא וְזֶהוּ כַּזַּיִת (אהלות פ"ב):
@29 **לכל טמאתו.** לְרַבּוֹת נוֹגֵעַ בְּזָב וְזָבָה נִדָּה וְיוֹלֶדֶת:
@30 **נפש אשר תגע בו.** בְּאֶחָד מִן הַטְּמֵאִים הַלָלוּ:
@31 **ואחר יאכל מן הקדשים.** נִדְרֶשֶׁת בִּיבָמוֹת (דף ע"ד), בִּתְרוּמָה שֶׁמֻּתָּר לְאָכְלָהּ בְּהַעֲרֵב הַשֶּׁמֶשׁ:
@31 **מן הקדשים.** וְלֹא כָל הַקֳּדָשִׁים:
@32 **נבלה וטרפה לא יאכל לטמאה בה.** לְעִנְיַן הַטֻּמְאָה הִזְהִיר כָּאן, שֶׁאִם אָכַל נִבְלַת עוֹף טָהוֹר שֶׁאֵין לָהּ טֻמְאַת מַגָּע וּמַשָּׂא אֶלָּא טֻמְאַת אֲכִילָה בְּבֵית הַבְּלִיעָה, אָסוּר לֶאֱכֹל בַּקֳּדָשִׁים; וְצָרִיךְ לוֹמַר "וּטְרֵפָה" — מִי שֶׁיֵּשׁ בְּמִינוֹ טְרֵפָה, יָצָא נִבְלַת עוֹף טָמֵא שֶׁאֵין בְּמִינוֹ טְרֵפָה:
@33 **ושמרו את משמרתי.** מִלֶּאֱכֹל תְּרוּמָה בְּטֻמְאַת הַגּוּף (סנהדרין פ"ג):
@33 **ומתו בו.** לִמְּדָנוּ שֶׁהִיא מִיתָה בִידֵי שָׁמָיִם (שם):
@34 **לא יאכל קדש.** בִּתְרוּמָה הַכָּתוּב מְדַבֵּר, שֶׁכָּל הָעִנְיָן דִּבֵּר בָּהּ:
@34 **תושב כהן ושכיר.** תּוֹשָׁבוֹ שֶׁל כֹּהֵן וּשְׂכִירוֹ, לְפִיכָךְ "תּוֹשַׁב" זֶה נָקוּד פַּתָּח, לְפִי שֶׁהוּא דָּבוּק; וְאֵיזֶהוּ תּוֹשָׁב? זֶה נִרְצָע שֶׁהוּא קָנוּי לוֹ עַד הַיּוֹבֵל, וְאֵיזֶהוּ שָֹכִיר? זֶה קָנוּי קִנְיַן שָׁנִים שֶׁיּוֹצֵא בְשֵׁשׁ, בָּא הַכָּתוּב וְלִמֶּדְךָ כָּאן שֶׁאֵין גּוּפוֹ קָנוּי לַאֲדוֹנָיו לֶאֱכֹל בִּתְרוּמָתוֹ (ספרא; יבמות ע'):
@35 **וכהן כי יקנה נפש.** עֶבֶד כְּנַעֲנִי שֶׁקָּנוּי לְגוּפוֹ:
@35 **ויליד ביתו.** אֵלּוּ בְנֵי הַשְּׁפָחוֹת; וְאֵשֶׁת כֹּהֵן אוֹכֶלֶת בִּתְרוּמָה מִן הַמִּקְרָא הַזֶּה, שֶׁאַף הִיא קִנְיַן כַּסְפּוֹ, וְעוֹד לָמֵד מִמִּקְרָא אַחֵר (במדבר י"ח), כָּל טָהוֹר בְּבֵיתְךָ וְגוֹ' בְּסִפְרֵי:
@36 **לאיש זר.** לְלֵוִי וְיִשְׂרָאֵל (ספרא):
@37 **אלמנה וגרושה.** מִן הָאִישׁ הַזָּר:
@37 **וזרע אין לה.** מִמֶּנּוּ:
@37 **ושבה.** הָא אִם יֵשׁ לָהּ זֶרַע מִמֶּנּוּ, אֲסוּרָה בִתְרוּמָה כָּל זְמַן שֶׁהַזֶּרַע קַיָּם (יבמות ע"ז):
@37 **וכל זר לא יאכל בו.** לֹא בָא אֶלָּא לְהוֹצִיא אֶת הָאוֹנֵן — שֶׁמֻּתָּר בִּתְרוּמָה, זָרוּת אָמַרְתִּי לְךָ וְלֹא אֲנִינוּת (שם שם ס"ח):
@38 **כי יאכל קדש.** תְּרוּמָה:
@38 **ונתן לכהן את הקדש.** דָּבָר הָרָאוּי לִהְיוֹת קֹדֶשׁ, שֶׁאֵינוֹ פוֹרֵעַ לוֹ מָעוֹת, אֶלָּא פֵּרוֹת שֶׁל חֻלִּין וְהֵן נַעֲשִֹין תְּרוּמָה (פסחים ל"ב):
@39 **ולא יחללו וגו'.** לְהַאֲכִילָם לְזָרִים:
@40 **והשיאו אותם.** אֶת עַצְמָם יִטְעֲנוּ עָוֹן **באכלם את קדשיהם** שֶׁהֻבְדְּלוּ לְשֵׁם תְּרוּמָה, וְקָדְשׁוּ וְנֶאֶסְרוּ עֲלֵיהֶן; וְאֻנְקְלוֹס שֶׁתִּרְגֵּם "בְּמֵיכָלְהוֹן בְּסוֹאֲבָא", שֶׁלֹּא לְצֹרֶךְ תִּרְגְּמוֹ כֵן:
@40 **והשיאו אותם.** זֶה אֶחָד מִשְּׁלוֹשָׁה אֶתִים שֶׁהָיָה רַבִּי יִשְׁמָעֵאל דּוֹרֵשׁ בַּתּוֹרָה שֶׁמְּדַבְּרִים בָּאָדָם עַצְמוֹ, וְכֵן "בְּיוֹם מְלֹאת יְמֵי נִזְרוֹ יָבִיא אֹתוֹ" (במדבר ו') — הוּא יָבִיא אֶת עַצְמוֹ, וְכֵן "וַיִּקְבֹּר אֹתוֹ בַגַּי" (דברים ל"ד) — הוּא קָבַר אֶת עַצְמוֹ, כָּךְ נִדְרָשׁ בְּסִפְרֵי:
@42 **נדריהם.** הֲרֵי עָלַי:
@42 **נדבותם.** הֲרֵי זוֹ:
@43 **לרצנכם.** הָבִיאוּ דָּבָר הָרָאוּי לְרַצּוֹת אֶתְכֶם לְפָנַי, שֶׁיְּהֵא לָכֶם לְרָצוֹן, אפיי"מנט בְּלַעַז, וְאֵיזֶהוּ הָרָאוּי לְרָצוֹן?
@43 **תמים זכר בבקר בכבשים ובעזים.** אֲבָל בְּעוֹלַת הָעוֹף אֵין צָרִיךְ תַּמּוּת וְזַכְרוּת, וְאֵינוֹ נִפְסָל בְּמוּם אֶלָּא בְּחֶסְרוֹן אֵבֶר (ספרא):
@45 **לפלא נדר.** לְהַפְרִישׁ בְּדִבּוּרוֹ:
@46 **עורת.** שֵׁם דָּבָר שֶׁל מוּם עִוָּרוֹן בְּלָשׁוֹן נְקֵבָה — שֶׁלֹּא יְהֵא בוֹ מוּם שֶׁל עִוָּרוֹן:
@46 **או שבור.** לֹא יִהְיֶה:
@46 **חרוץ.** רִיס שֶׁל עַיִן שֶׁנִּסְדַּק אוֹ שֶׁנִּפְגַּם וְכֵן שְׂפָתוֹ שֶׁנִּסְדְּקָה אוֹ נִפְגְּמָה (בכורות ל"ח):
@46 **יבלת.** ורו"אה בְּלַעַז:
@46 **גרב.** מִין חֲזָזִית וְכֵן יַלֶּפֶת, וּלְשׁוֹן יַלֶּפֶת כְּמוֹ וַיִּלְפֹּת שִׁמְשׁוֹן (שופטים ט"ז), שֶׁאֲחוּזָה בוֹ עַד יוֹם מִיתָה, שֶׁאֵין לָהּ רְפוּאָה:
@46 **לא תקריבו.** שָׁלוֹשׁ פְּעָמִים, לְהַזְהִיר עַל הַקְדָּשָׁתָן וְעַל שְׁחִיטָתָן וְעַל זְרִיקַת דָּמָן (תמורה ו'):
@46 **ואשה לא תתנו.** אַזְהָרַת הַקְטָרָתָן:
@47 **שרוע.** אֵבֶר גָּדוֹל מֵחֲבֵרוֹ:
@47 **וקלוט.** פַּרְסוֹתָיו קְלוּטוֹת (בכורות מ'):
@47 **נדבה תעשה אתו.** לְבֶדֶק הַבַּיִת:
@47 **ולנדר.** לַמִּזְבֵּחַ:
@47 **לא ירצה.** אֵי זֶה הֶקְדֵּשׁ בָּא לְרַצּוֹת? הֱוֵי אוֹמֵר זֶה הֶקְדֵּשׁ הַמִּזְבֵּחַ (תמורה ז'):
@48 **ומעוך וכתות ונתוק וכרות.** בַּבֵּיצִים אוֹ בַגִּיד:
@48 **מעוך.** בֵּיצָיו מְעוּכִין בַּיָּד:
@48 **כתות.** כְּתוּשִׁים יוֹתֵר מִמָּעוּךְ:
@48 **נתוק.** תְּלוּשִׁין בַּיָּד עַד שֶׁנִּפְסְקוּ חוּטִים שֶׁתְּלוּיִים בָּהֶן, אֲבָל נְתוּנִים הֵם בְּתוֹךְ הַכִּיס, וְהַכִּיס לֹא נִתְלַשׁ:
@48 **וכרות.** כְּרוּתִין בִּכְלִי וְעוֹדָן בַּכִּיס (בכורות ל"ט):
@48 [ **ומעוך.** תַּרְגּוּמוֹ וְדִי מְרִיס, זֶהוּ לְשׁוֹנוֹ בַּאֲרָמִית, לְשׁוֹן כְּתִישָׁה:
@48 **וכתות** תַּרְגּוּמוֹ וְדִי רְסִיס, כְּמוֹ "הַבַּיִת הַגָּדוֹל רְסִיסִים" (עמוס ו') — בְּקִיעוֹת דַּקּוֹת, וְכֵן "קָנֶה הַמְרֻסָּס" (שבת פ'):]
@48 **ובארצכם לא תעשו.** דָּבָר זֶה לְסָרֵס שׁוּם בְּהֵמָה וְחַיָּה, וַאֲפִלּוּ טְמֵאָה, לְכָךְ נֶאֱמַר בְּאַרְצְכֶם לְרַבּוֹת כָּל אֲשֶׁר בְּאַרְצְכֶם, שֶׁאִאֶ"לֹ לֹא נִצְטַוּוּ עַל הַסֵּרוּס אֶלָּא בָאָרֶץ, שֶׁהֲרֵי סֵרוּס חוֹבַת הַגּוּף הִיא וְכָל חוֹבַת הַגּוּף נוֹהֶגֶת בֵּין בָּאָרֶץ בֵּין בְּחוּצָה לָאָרֶץ:
@49 **ומיד בן נכר.** שֶׁהֵבִיא קָרְבָּן בְּיַד כֹּהֵן לְהַקְרִיבוֹ לַשָּׁמַיִם **לא תקריבו** לוֹ בַּעַל מוּם; וְאַעַ"פִּ שֶׁלֹּא נֶאֶסְרוּ בַעֲלֵי מוּמִים לְקָרְבַּן בְּנֵי נֹחַ אֶלָּא אִ"כֵּ מְחֻסְּרֵי אֵבֶר, זֹאת נוֹהֶגֶת בְּבָמָה שֶׁבַּשָּׂדוֹת, אֲבָל עַל הַמִּזְבֵּחַ שֶׁבַּמִּשְׁכָּן לֹא תַקְרִיבוּ, אֲבָל תְּמִימָה תְקַבְּלוּ מֵהֶם, לְכָךְ נֶאֱמַר לְמַעְלָה אִישׁ אִישׁ, לְרַבּוֹת אֶת הַגּוֹיִם שֶׁנּוֹדְרִים נְדָרִים וּנְדָבוֹת כְּיִשְׂרָאֵל (חולין י"ג):
@49 **משחתם.** חִבּוּלְהוֹן:
@49 **לא ירצו לכם.** לְכַפֵּר עֲלֵיכֶם:
@51 **כי יולד.** פְּרָט לְיוֹצֵא דֹפֶן (שם ל"ח):
@52 **אתו ואת בנו.** נוֹהֵג בַּנְּקֵבָה — שֶׁאָסוּר לִשְׁחֹט הָאֵם וְהַבֵּן אוֹ הַבַּת, וְאֵינוֹ נוֹהֵג בַּזְּכָרִים, וּמֻתָּר לִשְׁחֹט הָאָב וְהַבֵּן (שם ע"ח):
@52 **אתו ואת בנו.** אַף בְּנוֹ וְאוֹתוֹ בְּמַשְׁמָע (שם פ"ב):
@53 **לרצנכם תזבחו.** תְּחִלַּת זְבִיחַתְכֶם הִזָּהֲרוּ שֶׁתְּהֵא לְרָצוֹן לָכֶם, וּמַהוּ הָרָצוֹן?
@53 **ביום ההוא יאכל.** לֹא בָא לְהַזְהִיר אֶלָּא שֶׁתְּהֵא שְׁחִיטָה עַל מְנָת כֵּן — אַל תִּשְׁחֲטוּהוּ עַל מְנָת לְאָכְלוֹ לְמָחָר, שֶׁאִם תַּחְשְׁבוּ בוֹ מַחֲשֶׁבֶת פְּסוּל לֹא יְהֵא לָכֶם לְרָצוֹן; דָּ"אַ **לרצנכם** — לְדַעְתְּכֶם, מִכָּאן לַמִּתְעַסֵּק שֶׁפָּסוּל בִּשְׁחִיטַת קָדָשִׁים; וְאַעַ"פִּ שֶּׁפֵּרֵט בַּנֶּאֱכָלִים לִשְׁנֵי יָמִים, חָזַר וּפֵרֵט בַּנֶּאֱכָלִין לְיוֹם אֶחָד שֶׁתְּהֵא זְבִיחָתָן עַל מְנָת לְאָכְלָן בִּזְמַנָּן:
@54 **ביום ההוא יאכל.** לֹא בָא לְהַזְהִיר אֶלָּא שֶׁתְּהֵא שְׁחִיטָה עַל מְנָת כֵּן, שֶׁאִם לִקְבֹּעַ לוֹ זְמַן אֲכִילָה, כְּבָר כָּתוּב וּבְשַׂר זֶבַח תּוֹדַת שְׁלָמָיו וְגוֹ' (ויקרא ז'):
@54 **אני ה'.** דַּע מִי גָזַר עַל הַדָּבָר וְאַל יֵקַל בְּעֵינֶיךָ:
@55 **ושמרתם.** זוֹ הַמִּשְׁנָה:
@55 **ועשיתם.** זֶה הַמַּעֲשֶׂה (ספרא):
@56 **ולא תחללו.** לַעֲבֹר עַל דְּבָרַי מְזִידִין; מִמַּשְׁמָע שֶׁנֶּאֱמַר וְלֹא תְחַלְּלוּ מַה תַּ"לֹ וְנִקְדַּשְׁתִּי? מְסֹר עַצְמְךָ וְקַדֵּשׁ שְׁמִי. יָכוֹל בְּיָחִיד, תַּ"לֹ **בתוך בני ישראל;** וּכְשֶׁהוּא מוֹסֵר עַצְמוֹ יִמְסֹר עַצְמוֹ עַל מְנָת לָמוּת, שֶׁכָּל הַמּוֹסֵר עַצְמוֹ עַל מְנָת הַנֵּס, אֵין עוֹשִֹׁין לוֹ נֵס, שֶׁכֵּן מָצִינוּ בַחֲנַנְיָה מִישָׁאֵל וַעֲזַרְיָה שֶׁלֹּא מָסְרוּ עַצְמָן עַל מְנָת הַנֵּס, שֶׁנֶּאֱמַר (דניאל נ'), "וְהֵן לָא יְדִיעַ לֶהֱוֵא לָךְ מַלְכָּא" וְגוֹ', מַצִּיל וְלֹא מַצִּיל — "יְדִיעַ לֶהֱוֵא לָךְ" וְגו' (ספרא):
@57 **המוציא אתכם.** עַל מְנָת כֵּן:
@57 **אני ה'.** נֶאֱמָן לְשַׁלֵּם שָׂכָר (שם):
@59 **דבר אל בני ישראל, מועדי ה'.** עֲשֵׂה מוֹעֲדוֹת שֶׁיִּהְיוּ יִשְֹרָאֵל מְלֻמָּדִין בָּהֶם, שֶׁמְּעַבְּרִים אֶת הַשָּׁנָה עַל גָּלֻיּוֹת שֶׁנֶּעֶקְרוּ מִמְּקוֹמָן לַעֲלוֹת לָרֶגֶל וַעֲדַיִן לֹא הִגִּיעוּ לִירוּשָׁלַיִם (ספרא):
@60 **ששת ימים.** מָה עִנְיַן שַׁבָּת אֵצֶל מוֹעֲדוֹת? לְלַמֶּדְךָ שֶׁכָּל הַמְחַלֵּל אֶת הַמּוֹעֲדוֹת מַעֲלִין עָלָיו כְּאִלּוּ חִלֵּל אֶת הַשַּׁבָּתוֹת, וְכָל הַמְקַיֵּם אֶת הַמּוֹעֲדוֹת מַעֲלִין עָלָיו כְּאִלּוּ קִיֵּם אֶת הַשַּׁבָּתוֹת (שם):
@61 **אלה מועדי ה'.** לְמַעְלָה מְדַבֵּר בְּעִבּוּר שָׁנָה וְכָאן מְדַבֵּר בְּקִדּוּשׁ הַחֹדֶשׁ:
@62 **בין הערבים.** מִשֵּׁשׁ שָׁעוֹת וּלְמַעְלָה (שם):
@62 **פסח לה'.** הַקְרָבַת קָרְבָּן שֶׁשְּׁמוֹ פֶּסַח:
@65 **והקרבתם אשה וגו'.** הֵם הַמּוּסָפִין הָאֲמוּרִים בְּפָרָשַׁת פִּינְחָס, וְלָמָּה נֶאֶמְרוּ כָאן? לוֹמַר שֶׁאֵין הַמּוּסָפִין מְעַכְּבִין זֶה אֶת זֶה:
@65 **והקרבתם אשה לה'.** מִכָּל מָקוֹם — אִם אֵין פָּרִים הָבֵא אֵילִים, וְאִם אֵין פָּרִים וְאֵילִים הָבֵא כְבָשִׂים (שם):
@65 **שבעת ימים.** כָּל מָקוֹם שֶׁנֶּאֱמַר שִׁבְעַת שֵׁם דָּבָר הוּא — שָׁבוּעַ שֶׁל יָמִים, שטי"נא בְּלַעַז, וְכֵן כָּל לְשׁוֹן שְׁמוֹנַת שֵׁשֶׁת חֲמֵשֶׁת שְׁלוֹשֶׁת:
@65 **מלאכת עבדה.** אֲפִלּוּ מְלָאכוֹת הַחֲשׁוּבוֹת לָכֶם עֲבוֹדָה וְצֹרֶךְ — שֶׁיֵּשׁ חֶסְרוֹן כִּיס בְּבַטָּלָה שֶׁלָּהֶן — כְּגוֹן דָּבָר הָאָבֵד, כָּךְ הֵבַנְתִּי מִתֹּ"כֹּ, דְּקָתָנֵי יָכוֹל אַף חֻלּוֹ שֶׁל מוֹעֵד יְהֵא אָסוּר בִּמְלֶאכֶת עֲבוֹדָה וְכוּ':
@67 **ראשית קצירכם.** שֶׁתְּהֵא רִאשׁוֹנָה לַקָּצִיר (ספרא):
@67 **עמר.** עֲשִׂירִית הָאֵיפָה כָּךְ הָיְתָה שְׁמָהּ, כְּמוֹ וַיָּמֹדּוּ בָעֹמֶר (שמות ט"ז):
@68 **והניף.** כָּל תְּנוּפָה מוֹלִיךְ וּמֵבִיא מַעֲלֶה וּמוֹרִיד, מוֹלִיךְ וּמֵבִיא לַעֲצֹר רוּחוֹת רָעוֹת, מַעֲלֶה וּמוֹרִיד לַעֲצֹר טְלָלִים רָעִים (מנחות ס"ב):
@68 **לרצנכם.** אִם תַּקְרִיבוּ כְּמִשְׁפָּט זֶה יִהְיֶה לְרָצוֹן לָכֶם:
@68 **ממחרת השבת.** מִמָּחֳרַת יוֹם טוֹב הָרִאשׁוֹן שֶׁל פֶּסַח, שֶׁאִם אַתָּה אוֹמֵר שַׁבַּת בְּרֵאשִׁית אֵי אַתָּה יוֹדֵעַ אֵיזֶהוּ (ספרא; מנחות ס"ו):
@69 **ועשיתם … כבש.** חוֹבָה לָעֹמֶר הוּא בָא:
@70 **ומנחתו.** מִנְחַת נְסָכָיו:
@70 **שני עשרנים.** כְּפוּלָה הָיְתָה:
@70 **ונסכו יין רביעת ההין.** אַעַ"פִּ שֶׁמִּנְחָתוֹ כְפוּלָה אֵין נְסָכָיו כְּפוּלִים:
@71 **וקלי.** קֶמַח עָשׂוּי מִכַּרְמֶל רַךְ שֶׁמְּיַבְּשִׁין אוֹתוֹ בַּתַּנּוּר:
@71 **וכרמל.** הֵן קְלָיוֹת, שֶׁקּוֹרִין גרניי"ליש:
@71 **בכל משבתיכם.** נֶחְלְקוּ בוֹ חַכְמֵי יִשְֹרָאֵל, יֵשׁ שֶׁלָּמְדוּ מִכָּאן שֶׁהֶחָדָשׁ נוֹהֵג בְּחוּצָה לָאָרֶץ, וְיֵ"אֹ לֹא בָא אֶלָּא לְלַמֵּד שֶׁלֹּא נִצְטַוּוּ עַל הֶחָדָשׁ אֶלָּא לְאַחַר יְרֻשָּׁה וִישִׁיבָה, מִשֶּׁכִּבְּשׁוּ וְחִלְּקוּ (קידושין ל"ז):
@72 **ממחרת השבת.** מִמָּחֳרַת יוֹם טוֹב:
@72 **תמימת תהיינה.** מְלַמֵּד שֶׁמַּתְחִיל וּמוֹנֶה מִבָּעֶרֶב, שֶׁאִם לֹא כֵן אֵינָן תְּמִימוֹת (ספרא; מנחות ס"ו):
@73 **השבת השביעת.** כְּתַרְגּוּמוֹ שְׁבוּעֲתָא שְׁבִיעֵתָא:
@73 **עד ממחרת השבת השביעת תספרו.** וְלֹא עַד בִּכְלָל, וְהֵן אַרְבָּעִים וְתִשְׁעָה יוֹם:
@73 **חמשים יום והקרבתם מנחה חדשה לה'.** בַּיּוֹם הַחֲמִשִּׁים תַּקְרִיבוּהָ, וְאוֹמֵר אֲנִי זֶה מִדְרָשׁוֹ, אֲבָל פְּשׁוּטוֹ עַד מִמָּחֳרַת הַשַּׁבָּת הַשְּׁבִיעִת שֶׁהוּא יוֹם חֲמִשִּׁים תִּסְפְּרוּ, וּמִקְרָא מְסֹרָס הוּא:
@73 **מנחה חדשה.** הִיא הַמִּנְחָה הָרִאשׁוֹנָה שֶׁהוּבְאָה מִן הֶחָדָשׁ, וְאִ"תֹּ הֲרֵי קָרְבָה מִנְחַת הָעֹמֶר אֵינָהּ כִּשְׁאָר כָּל הַמְּנָחוֹת, שֶׁהִיא בָאָה מִן הַשְּׂעוֹרִים (מנחות י"ד):
@74 **ממושבתיכם.** וְלֹא מִחוּצָה לָאָרֶץ (ספרא):
@74 **לחם תנופה.** לֶחֶם תְּרוּמָה, הַמּוּרָם לְשֵׁם גָּבוֹהַּ, וְזוֹ הִיא הַמִּנְחָה הַחֲדָשָׁה הָאֲמוּרָה לְמַעְלָה:
@74 **בכורים.** רִאשׁוֹנָה לְכָל הַמְּנָחוֹת, אַף לְמִנְחַת קְנָאוֹת הַבָּאָה מִן שְׂעוֹרִים לֹא תִּקְרַב מִן הֶחָדָשׁ קֹדֶם לִשְׁתֵּי הַלֶּחֶם (שם):
@75 **על הלחם.** בִּגְלַל הַלֶּחֶם, חוֹבָה לַלֶּחֶם (ספרא; מנחות מ"ה):
@75 **ומנחתם ונסכיהם.** כְּמִשְׁפַּט מִנְחָה וּנְסָכִים הַמְפֹרָשִׁים בְּכָל בְּהֵמָה בְּפָרָשַׁת נְסָכִים, שְׁלוֹשָׁה עֶשְׂרוֹנִים לַפָּר וּשְׁנֵי עֶשְׂרוֹנִים לָאַיִל וְעִשָּׂרוֹן לַכֶּבֶשׂ, זוֹ הִיא הַמִּנְחָה, וְהַנְּסָכִים חֲצִי הַהִין לַפָּר וּשְׁלִישִׁית הַהִין לָאַיִל וּרְבִיעִית הַהִין לַכֶּבֶשׂ:
@76 **ועשיתם שעיר עזים.** יָכוֹל שִׁבְעַת הַכְּבָשִׂים וְהַשָּׂעִיר הָאֲמוּרִים כָּאן הֵם ז' הַכְּבָשִׂים וְהַשָּׂעִיר הָאֲמוּרִים בְּחֻמַּשׁ הַפְּקוּדִים, כְּשֶׁאַתָּה מַגִּיעַ אֵצֶל פָּרִים וְאֵילִים אֵינָן הֵם, אֱמֹר מֵעַתָּה אֵלּוּ לְעַצְמָן וְאֵלּוּ לְעַצְמָן — אֵלּוּ קָרְבוּ בִּגְלַל הַלֶּחֶם וְאֵלּוּ לַמּוּסָפִין (שם):
@77 **והניף הכהן אתם, תנופה.** מְלַמֵּד שֶׁטְּעוּנִין תְּנוּפָה חַיִּים, יָכוֹל כֻּלָּם, תַּ"לֹ "עַל שְׁנֵי כְבָשִֹים" (עי' מנחות ס"ב):
@77 **קדש יהיו.** לְפִי שֶׁשַּׁלְמֵי יָחִיד קָדָשִׁים קַלִּים, הֻזְקַק לוֹמַר בְּשַׁלְמֵי צִבּוּר שֶׁהֵן קָדְשֵׁי קָדָשִׁים:
@79 **ובקצרכם.** חָזַר וְשָׁנָה, לַעֲבֹר עֲלֵיהֶם בִּשְׁנֵי לָאוין; אָמַר ר' אַבְדִּימֵי בְּרַבִּי יוֹסֵף, מָה רָאָה הַכָּתוּב לִתְּנָהּ בְאֶמְצַע הָרְגָלִים — פֶּסַח וַעֲצֶרֶת מִכָּאן וְרֹאשׁ הַשָּׁנָה וְיוֹם הַכִּפּוּרִים וְחַג מִכָּאן — ? לְלַמֶּדְךָ שֶׁכָּל הַנּוֹתֵן לֶקֶט שִׁכְחָה וּפֵאָה לֶעָנִי כָּרָאוּי, מַעֲלִין עָלָיו כְּאִלּוּ בָּנָה בֵּית הַמִּקְדָּשׁ וְהִקְרִיב קָרְבְּנוֹתָיו בְּתוֹכוֹ (ספרא):
@79 **תעזב.** הַנַּח לִפְנֵיהֶם וְהֵם יִלְקְטוּ, וְאֵין לְךָ לְסַיֵּעַ לְאֶחָד מֵהֶם (פאה פ"ה):
@79 **אני ה' אלהיכם.** נֶאֱמָן לְשַׁלֵּם שָׂכָר:
@81 **זכרון תרועה.** זִכְרוֹן פְּסוּקֵי זִכְרוֹנוֹת וּפְסוּקֵי שׁוֹפָרוֹת (ספרא: ראש השנה ל"ב) לִזְכֹּר לָכֶם עֲקֵדַת יִצְחָק שֶׁקָּרַב תַּחְתָּיו אַיִל:
@82 **והקרבתם אשה.** הַמּוּסָפִין הָאֲמוּרִין בְּחֻמַּשׁ הַפְּקוּדִים:
@84 **אך.** כָּל אַכִין וְרַקִּין שֶׁבַּתּוֹרָה מִעוּטִים — מְכַפֵּר הוּא לַשָּׁבִים וְאֵינוֹ מְכַפֵּר עַל שֶׁאֵינָם שָׁבִים (ספרא):
@87 **והאבדתי.** לְפִי שֶׁהוּא אוֹמֵר כָּרֵת בְּכָל מָקוֹם וְאֵינִי יוֹדֵעַ מַה הוּא, כְּשֶׁהוּא אוֹמֵר וְהַאֲבַדְתִּי, לִמֵּד עַל הַכָּרֵת שֶׁאֵינוֹ אֶלָּא אֲבַדּוֹן:
@88 **כל מלאכה וגו'.** לַעֲבֹר עָלָיו בְּלָאוִין הַרְבֵּה, אוֹ לְהַזְהִיר עַל מְלֶאכֶת לַיְלָה כִּמְלֶאכֶת יוֹם:
@92 **מקרא קדשׁ.** קַדְּשֵׁהוּ בִכְסוּת נְקִיָּה וּבִתְפִלָּה, וּבִשְׁאָר יָמִים טוֹבִים בְּמַאֲכָל וּבְמִשְׁתֶּה וּבִכְסוּת נְקִיָּה וּבִתְפִלָּה (עי' ספרא):
@93 **עצרת הוא.** עָצַרְתִּי אֶתְכֶם אֶצְלִי; כְּמֶלֶךְ שֶׁזִּמֵּן אֶת בָּנָיו לִסְעוּדָה לְכָךְ וְכָךְ יָמִים, כֵּיוָן שֶׁהִגִּיעַ זְמַנָּן לִפָּטֵר, אָמַר, בָּנַי בְּבַקָּשָׁה מִכֶּם עַכְּבוּ עִמִּי עוֹד יוֹם אֶחָד, קָשָׁה עָלַי פְּרֵדַתְכֶם:
@93 **כל מלאכת עבדה.** אֲפִלּוּ מְלָאכָה שֶׁהִיא עֲבוֹדָה לָכֶם, שֶׁאִם לֹא תַעֲשׂוּהָ יֵשׁ חֶסְרוֹן כִּיס בַּדָּבָר.
@93 **לא תעשו.** יָכוֹל אַף חֻלּוֹ שֶׁל מוֹעֵד יְהֵא אָסוּר בִּמְלֶאכֶת עֲבוֹדָה, תַּ"לֹ "הִוא" (שם):
@94 **עלה ומנחה.** מִנְחַת נְסָכִים הַקְּרֵבָה עִם הָעוֹלָה:
@94 **דבר יום ביומו.** חֹק הַקָּצוּב בְּחֻמַּשׁ הַפְּקוּדִים:
@94 **דבר יום ביומו.** הָא אִם עָבַר יוֹמוֹ בָּטֵל קָרְבָּנוֹ (עי' ספרא):
@96 **אך בחמשה עשר יום, תחגו.** קָרְבַּן שְׁלָמִים לַחֲגִיגָה, יָכוֹל תִּדְחֶה אֶת הַשַּׁבָּת, תַּ"לֹ אַךְ, הוֹאִיל וְיֵשׁ לָהּ תַּשְׁלוּמִין כָּל שִׁבְעָה:
@96 **באספכם את תבואת הארץ.** שֶׁיְּהֵא חֹדֶשׁ שְׁבִיעִי זֶה בָּא בִּזְמַן אֲסִיפָה, מִכָּאן שֶׁנִּצְטַוּוּ לְעַבֵּר אֶת הַשָּׁנִים, שֶׁאִם אֵין הָעִבּוּר, פְּעָמִים שֶׁהוּא בְאֶמְצַע הַקַּיִץ אוֹ הַחֹרֶף:
@96 **תחגו.** שַׁלְמֵי חֲגִיגָה:
@96 **שבעת ימים.** אִם לֹא הֵבִיא בָזֶה, יָבִיא בָזֶה, יָכוֹל יְהֵא מְבִיאָן כָּל שִׁבְעָה, תַּלְמוּד לוֹמַר **וחגתם אתו** — יוֹם אֶחָד בְּמַשְׁמָע וְלֹא יוֹתֵר, וְלָמָּה נֶאֱמַר שִׁבְעָה? לְתַשְׁלוּמִין (חגיגה ט'):
@97 **פרי עץ הדר.** עֵץ שֶׁטַּעַם עֵצוֹ וּפִרְיוֹ שָׁוֶה (סכה ל"ה):
@97 **הדר.** הַדָּר בְּאִילָנוֹ מִשָּׁנָה לְשָׁנָה, וְזֶהוּ אֶתְרוֹג (שם):
@97 **כפת תמרים.** חָסֵר וי"ו, לִמֵּד שֶׁאֵינָהּ אֶלָּא אַחַת:
@97 **וענף עץ עבת.** שֶׁעֲנָפָיו קְלוּעִים כַּעֲבוֹתוֹת וְכַחֲבָלִים, וְזֶהוּ הֲדַס, הֶעָשׂוּי כְּמִין קְלִיעָה (שם ל"ב):
@99 **האזרח.** זֶה אֶזְרָח, **בישראל** — לְרַבּוֹת אֶת הַגֵּרִים (ספרא):
@100 **כי בסכות הושבתי.** עַנְנֵי כָבוֹד (שם; מכילתא י"ב):
@103 **צו את בני ישראל.** זוֹ פָרָשַׁת מִצְוַת הַנֵּרוֹת, וּפָרָשַׁת וְאַתָּה תְּצַוֶּה לֹא נֶאֶמְרָה אֶלָּא עַל סֵדֶר מְלֶאכֶת הַמִּשְׁכָּן, לְפָרֵשׁ צֹרֶךְ הַמְּנוֹרָה, וְכֵן מַשְׁמָע: וְאַתָּה סוֹפְךָ לְצַוּוֹת אֶת בְּנֵי יִשְׂרָאֵל עַל כָּךְ:
@103 **שמן זית זך.** שְׁלוֹשָׁה שְׁמָנִים יוֹצְאִים מִן הַזַּיִת, הָרִאשׁוֹן קָרוּי זָךְ, וְהֵן מְפֹרָשִׁין בִּמְנָחוֹת (דף פ"ו) וּבְתֹ"כֹּ:
@103 **תמיד.** מִלַּיְלָה לְלַיְלָה, כְּמוֹ עוֹלַת תָּמִיד, שֶׁאֵינָהּ אֶלָּא מִיּוֹם לְיוֹם:
@104 **לפרכת העדת.** שֶׁלִּפְנֵי הָאָרוֹן שֶׁהוּא קָרוּי עֵדוּת; וְרַבּוֹתֵינוּ דָרְשׁוּ עַל נֵר מַעֲרָבִי, שֶׁהוּא עֵדוּת לְכָל בָּאֵי עוֹלָם שֶׁהַשְּׁכִינָה שׁוֹרָה בְיִשְׂרָאֵל, שֶׁנּוֹתֵן בָּהּ שֶׁמֶן כְּמִדַּת חַבְרוֹתֶיהָ, וּמִמֶּנָּה הָיָה מַתְחִיל וּבָהּ הָיָה מְסַיֵּם (שבת כ"ב; מנחות פ"ו):
@104 **יערך אתו אהרן מערב עד בקר.** יַעֲרֹךְ אוֹתוֹ עֲרִיכָה הָרְאוּיָה לְמִדַּת כָּל הַלַּיְלָה, וְשִׁעֲרוּ חֲכָמִים חֲצִי לֹג לְכָל נֵר וָנֵר, וְהֵן כְּדַאי אַף לְלֵילֵי תְּקוּפַת טֵבֵת, וּמִדָּה זוֹ הֻקְבְּעָה לָהֶם (מנחות פ"ט):
@105 **המנרה הטהרה.** שֶׁהִיא זָהָב טָהוֹר; דָּ"אַ עַל טָהֳרָהּ שֶׁל מְנוֹרָה, שֶׁמְּטַהֲרָהּ וּמְדַשְּׁנָהּ תְּחִלָּה מִן הָאֵפֶר (עי' ספרא):
@107 **שש המערכת.** שֵׁשׁ חַלּוֹת הַמַּעֲרֶכֶת הָאַחַת:
@107 **השלחן הטהר.** שֶׁל זָהָב טָהוֹר; דָּ"אַ: עַל טָהֳרוֹ שֶׁל שֻׁלְחָן, שֶׁלֹּא יִהְיוּ הַסְּנִיפִין מַגְבִּיהִין אֶת הַלֶּחֶם מֵעַל גַּבֵּי הַשֻּׁלְחָן (שם; מנחות צ"ז):
@108 **ונתת על המערכת.** עַל כָּל אַחַת מִשְּׁתֵי הַמַּעֲרָכוֹת; וְהָיוּ שְׁנֵי בְזִיכֵי לְבוֹנָה מְלֹא קֹמֶץ לְכָל אַחַת:
@108 **והיתה.** הַלְּבוֹנָה הַזֹּאת:
@108 **ללחם לאזכרה.** שֶׁאֵין מִן הַלֶּחֶם לְגָבוֹהַּ כְּלוּם, אֶלָּא הַלְּבוֹנָה נִקְטֶרֶת כְּשֶׁמְּסַלְּקִין אוֹתוֹ בְּכָל שַׁבָּת וְשַׁבָּת, וְהִיא לְזִכָּרוֹן לַלֶּחֶם, שֶׁעַל יָדָהּ הוּא נִזְכָּר לְמַעְלָה, כַּקֹּמֶץ שֶׁהִיא אַזְכָּרָה לַמִּנְחָה (עי' ספרא):
@110 **והיתה.** הַמִּנְחָה הַזֹּאת, שֶׁכָּל דָּבָר הַבָּא מִן הַתְּבוּאָה בִּכְלַל מִנְחָה הוּא:
@110 **ואכלהו.** מוּסָב עַל הַלֶּחֶם שֶׁהוּא לְשׁוֹן זָכָר:
@111 **ויצא בן אשה ישראלית.** מֵהֵיכָן יָצָא? רַבִּי לֵוִי אוֹמֵר מֵעוֹלָמוֹ יָצָא, רַבִּי בְּרֶכְיָה אוֹמֵר מִפָּרָשָׁה שֶׁלְּמַעְלָה יָצָא, לִגְלֵג וְאָמַר "בְּיוֹם הַשַּׁבָּת יַעַרְכֶנּוּ" דֶּרֶךְ הַמֶּלֶךְ לֶאֱכֹל פַּת חַמָּה בְכָל יוֹם, שֶׁמָּא פַּת צוֹנֶנֶת שֶׁל תִּשְׁעָה יָמִים, בִּתְמִיהָ? וּמַתְנִיתָא אֲמַרָה מִבֵּית דִּינוֹ שֶׁל מֹשֶׁה יָצָא, מְחֻיָּב, בָּא לִטַּע אָהֳלוֹ בְתוֹךְ מַחֲנֵה דָן, אָמְרוּ לוֹ מַה טִּיבְךָ לְכָאן? אָמַר לָהֶם מִבְּנֵי דָּן אֲנִי, אָמְרוּ לוֹ "אִישׁ עַל דִּגְלוֹ בְאֹתֹת לְבֵית אֲבֹתָם" כְּתִיב (במדבר ב'), נִכְנַס לְבֵית דִּינוֹ שֶׁל מֹשֶׁה וְיָצָא מְחֻיָּב, עָמַד וְגִדֵּף (ספרא, ויקרא ל"ב):
@111 **בן איש מצרי.** הוּא הַמִּצְרִי שֶׁהָרַג מֹשֶׁה (שם):
@111 **בתוך בני ישראל.** מְלַמֵּד שֶׁנִּתְגַיֵּר (ספרא):
@111 **וינצו במחנה.** עַל עִסְקֵי הַמַּחֲנֶה:
@111 **ואיש הישראלי.** זֶה שֶׁכְּנֶגְדּוֹ שֶׁמִּחָה בוֹ מִטַּע אָהֳלוֹ:
@112 **ויקב.** כְּתַרְגּוּמוֹ "וּפָרֵשׁ", שֶׁנָּקַב שֵׁם הַמְיֻחָד וְגִדֵּף, וְהוּא שֵׁם הַמְפֹרָשׁ שֶׁשָּׁמַע מִסִּינַי (ספרא):
@112 **ושם אמו שלמית בת דברי.** שִׁבְחָן שֶׁל יִשְֹרָאֵל שֶׁפִּרְסְמָהּ הַכָּתוּב לְזוֹ, לוֹמַר שֶׁהִיא לְבַדָּהּ הָיְתָה זוֹנָה:
@112 **שלמית.** דַּהֲוָה פִּטְפְּטָה "שְׁלָם עֲלָךְ", "שְׁלָם עֲלֵיכוֹן", מְפַטְפֶּטֶת בִּדְבָרִים, שׁוֹאֶלֶת בִּשְׁלוֹם הַכֹּל:
@112 **בת דברי.** דַּבְּרָנִית הָיְתָה, מְדַבֶּרֶת עִם כָּל אָדָם, לְפִיכָךְ קִלְקְלָה:
@112 **למטה דן.** מַגִּיד שֶׁהָרָשָׁע גּוֹרֵם גְּנַאי לוֹ, גְּנַאי לְאָבִיו, גְּנַאי לְשִׁבְטוֹ; כַּיּוֹצֵא בוֹ "אָהֳלִיאָב בֶּן אֲחִיסָמָךְ לְמַטֵּה דָן" (שמות ל"א), שֶׁבַח לוֹ, שֶׁבַח לְאָבִיו, שֶׁבַח לְשִׁבְטוֹ (ספרא):
@113 **ויניחהו.** לְבַדּוֹ, וְלֹא הִנִּיחוּ מְקוֹשֵׁשׁ עִמּוֹ — שֶׁשְּׁנֵיהֶם הָיוּ בְּפֶרֶק אֶחָד — וְיוֹדְעִים הָיוּ שֶׁהַמְּקוֹשֵׁשׁ בְּמִיתָה, אֲבָל לֹא פֹרַשׁ לָהֶם בְּאֵיזוֹ מִיתָה לְכָךְ נֶאֱמַר (במדבר ט"ו), כִּי לֹא פֹרַשׁ מַה יֵּעָשֶֹה לוֹ; אֲבָל בַּמְּקַלֵּל הוּא אוֹמֵר לִפְרֹשׁ לָהֶם, שֶׁלֹּא הָיוּ יוֹדְעִים אִם חַיָּב מִיתָה אִם לָאו (ספרא; סנהדרין ע"ח):
@115 **השמעים.** אֵלּוּ הָעֵדִים:
@115 **כל.** לְהָבִיא אֶת הַדַּיָּנִים (ספרא):
@115 **את ידיהם.** אוֹמְרִים לוֹ דָּמְךָ בְּרֹאשְׁךָ, וְאֵין אָנוּ נֶעֱנָשִׁים בְּמִיתָתְךָ, שֶׁאַתָּה גָרַמְתָּ לְךָ (שם):
@115 **כל העדה.** בְּמַעֲמַד כָּל הָעֵדָה, (מִכָּאן) שֶׁשְּׁלוּחוֹ שֶׁל אָדָם כְּמוֹתוֹ (עי' שם):
@116 **ונשא חטאו.** בְּכָרֵת כְּשֶׁאֵין הַתְרָאָה:
@117 **ונקב שם.** אֵינוֹ חַיָּב עַד שֶׁיְּפָרֵשׁ אֶת הַשֵּׁם, וְלֹא הַמְקַלֵּל בְּכִנוּי (סנהדרין נ"ו):
@117 **ונקב.** לְשׁוֹן קְלָלָה כְּמוֹ (במדבר כ"ג) "מָה אֶקֹּב" (סנהדרין נ"ו):
@118 **ואיש כי יכה.** לְפִי שֶׁנֶּאֱמַר מַכֵּה אִישׁ וָמֵת (שמות כ"א), אֵין לִי אֶלָּא שֶׁהָרַג אֶת הָאִישׁ, אִשָּׁה וְקָטָן מִנַּיִן? תַּ"לֹ "כָּל נֶפֶשׁ אָדָם":
@121 **כן ינתן בו.** פֵּרְשׁוּ רַבּוֹתֵינוּ שֶׁאֵינוֹ נְתִינַת מוּם מַמָּשׁ אֶלָּא תַּשְׁלוּמֵי מָמוֹן, שָׁמִין אוֹתוֹ כְּעֶבֶד, לְכָךְ כָּתוּב בּוֹ לְשׁוֹן נְתִינָה — דָּבָר הַנָּתוּן מִיָּד לְיָד (בבא קמא פ"ד; כתובות ל"ב):
@122 **ומכה בהמה ישלמנה.** לְמַעְלָה דִּבֵּר בְּהוֹרֵג בְּהֵמָה וְכָאן דִּבֵּר בְּעוֹשֶׂה בָהּ חַבּוּרָה:
@122 **ומכה אדם יומת.** אֲפִלּוּ לֹא הֲרָגוֹ אֶלָּא עָשָׂה בוֹ חַבּוּרָה, שֶׁלֹּא נֶאֱמַר כָּאן נֶפֶשׁ; וּבְמַכֵּה אָבִיו וְאִמּוֹ דִּבֵּר הַכָּתוּב, וּבָא לְהַקִּישׁוֹ לְמַכֵּה בְהֵמָה, מַה מַּכֵּה בְהֵמָה מֵחַיִּים, אַף מַכֵּה אָבִיו מֵחַיִּים, פְּרָט לְמַכֶּה לְאַחַר מִיתָה; לְפִי שֶׁמָּצִינוּ שֶׁהַמְקַלְּלוֹ לְאַחַר מִיתָה חַיָּב, הֻצְרַךְ לוֹמַר בַּמַּכֶּה שֶׁפָּטוּר, וּמַה בִּבְהֵמָה בְּחַבָּלָה, שֶׁאִם אֵין חַבָּלָה אֵין תַּשְׁלוּמִין, אַף מַכֵּה אָבִיו אֵינוֹ חַיָּב עַד שֶׁיַּעֲשֶֹה בוֹ חַבּוּרָה (ספרא; סנהדרין פ"ד):
@123 **אני ה' אלהיכם.** אֱלֹהֵי כֻלְּכֶם, כְּשֵׁם שֶׁאֲנִי מְיַחֵד שְׁמִי עֲלֵיכֶם, כָּךְ אֲנִי מְיַחֲדוֹ עַל הַגֵּרִים:
@124 **ובני ישראל עשו.** כָּל הַמִּצְוָה הָאֲמוּרָה בַּסְּקִילָה בְּמָקוֹם אַחֵר — דְּחִיָּה, רְגִימָה וּתְלִיָּה (עי' ספרא; סנהדרין מ"ג):

@1 **אֱמֹר וְאָמַרְתָּ** לְהַזְהִיר גְּדוֹלִים עַל הַקְּטַנִּים, לְשׁוֹן רַשִׁ"י (רש"י על ויקרא כ"א:א') מִדִּבְרֵי רַבּוֹתֵינוּ (יבמות קיד). וְהָאַזְהָרָה הַזֹּאת לוֹמַר שֶׁלֹּא נְסַיֵּעַ בְּטֻמְאַת הַקְּטַנִּים בְּיָדַיִם, וּבָאוּ בָּזֶה אַזְהָרוֹת רַבּוֹת בַּתּוֹרָה כְּפִי מִדְרַשׁ רַבּוֹתֵינוּ (שם), בַּדָּם וּבַשְּׁרָצִים וְטֻמְאָה, וּמֵהֶם נִלְמוֹד לְכָל אִסּוּרִין שֶׁבַּתּוֹרָה שֶׁלֹּא נְסַיֵּעַ בְּאֶחָד מֵהֶם שֶׁיַּעַבְרוּ עָלָיו הַקְּטַנִּים. אֲבָל אִם יַעֲשׂוּ הֵם לְדַעַת עַצְמָן אֵין אָנוּ מְצֻוִּין עֲלֵיהֶם לְהַפְרִישָׁם. וְטַעַם הַכָּתוּב עַל פִּי מִדְרָשׁוֹ, אֱמֹר אֶל הַכֹּהֲנִים וְתַחְזֹר וְתֹאמַר אֲלֵיהֶם שֶׁלֹּא יִטַּמְּאוּ. וְרִבּוּי הָאַזְהָרוֹת שֶׁיְּצַוֶּה לְהַזְהִירָם, שֶׁיִּהְיוּ כָּל בְּנֵי אַהֲרֹן נִשְׁמָרִים מִזֶּה, גַּם הַקְּטַנִּים. וְאָמַר ר"א (אבן עזרא על ויקרא כ"א:א') בְּדֶרֶךְ הַפְּשָׁט, "אֱמֹר אֶל הַכֹּהֲנִים" - הַפָּרָשָׁה הַנִּזְכֶּרֶת לְמַעְלָה, כִּי הֵם מוֹרֵי הַתּוֹרָה וְהַמַּזְהִירִים אֶת הָעָם, "וְאָמַרְתָּ לָהֶם" - הַמִּצְוֹת שֶׁהֵם לְבַדָּם חַיָּבִים לְשָׁמְרָם. וְאֵינוֹ נָכוֹן. וְעַל דַּעְתִּי בִּפְשַׁט הַכָּתוּב, טַעַם "אֱמֹר" כְּמוֹ דַּבֵּר, "אֲמָרַי הַאֲזִינָה ה'" (תהלים ה ב) - דְּבָרַי, וְכֵן "אֲמָרִים אֱמֶת" (משלי כב כא), וְכֵן "כִּי הִיא שָׁמְעָה אֵת כָּל אִמְרֵי ה'" (יהושע כד כז), וּכְתִיב "בֹּא אֶל פַּרְעֹה וְדִבַּרְתָּ אֵלָיו" (שמות ט א), כְּמוֹ וְאָמַרְתָּ, "וַיְדַבֵּר מֹשֶׁה אֶל אַהֲרֹן וְאֶל אֶלְעָזָר וְאֶל אִיתָמָר בָּנָיו הַנּוֹתָרִים קְחוּ אֶת הַמִּנְחָה" (ויקרא י':י"ב) כְּמוֹ וַיֹּאמֶר, וְכֵן בִּמְקוֹמוֹת הַרְבֵּה "דַּבֵּר אֶל בְּנֵי יִשְׂרָאֵל וְאָמַרְתָּ אֲלֵיהֶם", וְהוּא נֶאֱמַר בְּפָרָשִׁיּוֹת אֲשֶׁר יִרְצֶה לְהַזְהִיר לָהֶם מְאֹד, אוֹ לְחֹמֶר הָעִנְיָן אוֹ לִהְיוֹתָם מֻרְגָּלִים לַחֲטֹא בָּהֵנָּה, וְכֵן יֹאמַר "אֱמֹר אֶל הַכֹּהֲנִים וְאָמַרְתָּ אֲלֵיהֶם", וְכָמוֹהוּ "כֹּה אָמַר ה' אֱלֹהֵי יִשְׂרָאֵל הָלֹךְ וְאָמַרְתָּ אֶל צִדְקִיָּהוּ מֶלֶךְ יְהוּדָה וְאָמַרְתָּ אֵלָיו כֹּה אָמַר ה'" וְגוֹ' (ירמיהו לד ב), שֶׁטַּעְמוֹ דַּבֵּר אֶל צִדְקִיָּהוּ, וְכֵן "וַתֹּאמֶר הָאִשָּׁה הַתְּקֹעִית אֶל הַמֶּלֶךְ וַתִּפֹּל עַל פָּנֶיהָ אַרְצָה וַתִּשְׁתָּחוּ וַתֹּאמֶר הוֹשִׁעָה הַמֶּלֶךְ" ( יד ד), כְּמוֹ וַתְּדַבֵּר הָאִשָּׁה אֶל הַמֶּלֶךְ וַתֹּאמֶר הוֹשִׁיעָה הַמֶּלֶךְ. וְהִנֵּה טַעַם "אֱמֹר אֶל הַכֹּהֲנִים וְאָמַרְתָּ אֲלֵיהֶם" כְּטַעַם דַּבֵּר אֶל הַכֹּהֲנִים וְאָמַרְתָּ אֲלֵיהֶם, דַּבֵּר אֶל בְּנֵי יִשְׂרָאֵל וְאָמַרְתָּ אֲלֵיהֶם, וְעִנְיָנוֹ דַּבֵּר אֶל הָעָם בִּשְׁמִי וְתֹאמַר לָהֶם כָּכָה, כְּעִנְיַן "בֹּא אֶל פַּרְעֹה וְאָמַרְתָּ אֵלָיו" (שמות ז כו). וְרַבִּים יֹאמְרוּ כִּי טַעַם "דַּבֵּר אֶל בְּנֵי יִשְׂרָאֵל" כְּטַעַם קְרִיאָה, דַּבֵּר אֶל בְּנֵי יִשְׂרָאֵל שֶׁיִּתְאַסְּפוּ אֵלֶיךָ וְתֹאמַר אֲלֵיהֶם כָּכָה, וְכֵן "אֱמֹר אֶל הַכֹּהֲנִים", שֶׁיִּקָּבְצוּ וְיִשְׁמְעוּ. וְטַעַם "הַכֹּהֲנִים", כִּי בַּמִּצְוֹת אֲשֶׁר הֵם בְּעִנְיְנֵי הַקָּרְבָּנוֹת יֹאמַר "אֶל אַהֲרֹן וְאֶל בָּנָיו" וְלֹא יַזְכִּירֵם בְּשֵׁם "הַכֹּהֲנִים", כִּי הָעִנְיָנִים הָהֵם בַּקָּרְבָּנוֹת אוֹ בְּמַעֲלוֹת הַקֹּדֶשׁ, אֲבָל בְּכָאן יַזְהִיר שֶׁלֹּא יִטַּמְּאוּ בַּמֵּת לְעוֹלָם, אֲפִלּוּ בְּעֵת שֶׁלֹּא יָבוֹאוּ בַּמִּקְדָּשׁ, וְהִיא מַעֲלָה לָהֶם בְּעַצְמָם, וּלְכָךְ הִזְכִּיר הַכָּתוּב "הַכֹּהֲנִים", לֵאמֹר כִּי בַּעֲבוּר שֶׁהֵם כֹּהֲנֵי ה' וּמְשָׁרְתֵי אֱלֹהֵינוּ יֹאמַר לָהֶם שֶׁיִּתְנַהֲגוּ כָּבוֹד וּגְדֻלָּה בְּעַצְמָם וְלֹא יִטַּמְּאוּ לְעוֹלָם. וְהִנֵּה הַחֲלָלִים מוּצָאִים מִן הַכְּלָל הַזֶּה. וְטַעַם "לֹא יִטַּמָּא", שֶׁתֹּאמַר לָהֶם שֶׁלֹּא יִטַּמָּא כָּל אֶחָד מֵהֶם לְנֶפֶשׁ בְּעַמָּיו, אוֹ יִמָּשֵׁךְ אֶל "בַּעַל בְּעַמָּיו" הַמֻּזְכָּר לְמַטָּה, וְשִׁעוּרוֹ, לְנֶפֶשׁ לֹא יִטַּמָּא הַבַּעַל בְּעַמָּיו. וְטַעַם "בַּעַל בְּעַמָּיו" כְּמוֹ "מִבַּעֲלֵי יְהוּדָה" (שמואל א ו ב), "בַּעֲלֵי גוֹיִם" (ישעיהו טז ח), הַנִּכְבָּדִים בָּהֶם אוֹ הָאֲדוֹנִים, מִלְּשׁוֹן "בְּעָלָיו אֵין עִמּוֹ" (שמות כב יג), "בַּעַל הַבַּיִת" (שם פסוק ז), כִּי הַנִּכְבָּדִים יִקָּרְאוּ אֲדוֹנִים. יֹאמַר, לֹא יִטַּמָּא נִכְבָּד בְּעַמָּיו לְהָחֵל אֶת כְּבוֹדוֹ. יְפָרֵשׁ הַכָּתוּב כִּי לְמַעֲלַת הַכֹּהֵן, בַּעֲבוּר שֶׁהוּא רָאוּי לִהְיוֹת הַגָּדוֹל וְהַנִּכְבָּד בְּעַמָּיו, יַזְהִירֶנּוּ שֶׁלֹּא יְחַלֵּל מַעֲלָתוֹ בְּטֻמְאַת הַמֵּתִים. וְיִתְכַּוֵּן הַכָּתוּב בָּזֶה שֶׁלֹּא יַעֲלֶה עַל דַּעְתֵּנוּ לוֹמַר שֶׁאֵין הָאַזְהָרָה אֶלָּא בְּבֹאָם אֶל אֹהֶל מוֹעֵד לְשָׁרֵת בַּקֹּדֶשׁ. וְכֵן בְּכָל הַפָּרָשָׁה יַזְהִיר כִּי הַכֹּל לְמַעֲלָתָם, "אֶת אָבִיהָ הִיא מְחַלֶּלֶת" (ויקרא כ"א:ט'), "וְלֹא יְחַלֵּל זַרְעוֹ" (ויקרא כ"א:ט"ו), וְכֵן תַּרְגּוּמוֹ שֶׁל אוּנְקְלוֹס "לָא יִסְתָּאַב רַבָּא בְּעַמֵּהּ לְאַחָלוּתֵיהּ". וּבְת"כ (אמור פרשה א טו) נִדְרָשׁ בְּבַעַל בְּאִשְׁתּוֹ, כְּמוֹ שֶׁכָּתַב רַשִׁ"י:
@6 **קְדֹשִׁים יִהְיוּ לֵאלֹהֵיהֶם** הַקְּדֻשָּׁה הִיא הַפְּרִישׁוּת, כַּאֲשֶׁר פֵּרַשְׁתִּי בְּסֵדֶר שֶׁל מַעְלָה (רמב"ן על ויקרא י"ט:ב'), יֹאמַר שֶׁאֲפִלּוּ בַּמֻּתָּר לְיִשְׂרָאֵל יִהְיוּ הַכֹּהֲנִים פְּרוּשִׁים, יִבָּדְלוּ מִטֻּמְאַת הַמֵּתִים וְנִשּׂוּאֵי הַנָּשִׁים שֶׁאֵינָן הֲגוּנוֹת לָהֶם בְּטַהֲרָה וּבִנְקִיּוּת:
@8 וְטַעַם **כִּי קָדוֹשׁ אֲנִי ה' מְקַדִּשְׁכֶם** עִם הַכֹּהֲנִים יְדַבֵּר כַּאֲשֶׁר הֵחֵל "אֱמֹר אֶל הַכֹּהֲנִים", אוֹ "אֲנִי ה' מְקַדִּשְׁכֶם" כֻּלְּכֶם, הַכֹּהֲנִים וְהָעָם. וְהַטַּעַם כִּי מֵאַחַר שֶׁהוּא מַקְרִיב לֶחֶם אֱלֹהֶיךָ קָדוֹשׁ יִהְיֶה לָךְ, כִּי עַל יָדוֹ אֲנִי מְקַדֵּשׁ אֶת כֻּלְּכֶם וּמַשְׁרֶה שְׁכִינָתִי בְּמִקְדַּשְׁכֶם. וְיִתָּכֵן עַל דֶּרֶךְ הָאֱמֶת, שֶׁיַּחְזֹר לְרֹאשׁ הַפָּסוּק, וּכְבָר נִתְפָּרֵשׁ:
@10 **אֶת רֹאשׁוֹ לֹא יִפְרָע וְגוֹ' וְעַל כָּל נַפְשֹׁת מֵת** נִמְשָׁךְ לְפָנָיו עִם "נַפְשׁוֹת מֵת", יֹאמַר שֶׁלֹּא יִפְרַע וְלֹא יִפְרֹם עַל כָּל נַפְשֹׁת מֵת וְלֹא יָבֹא עָלָיו:
@12 **וּמִן הַמִּקְדָּשׁ לֹא יֵצֵא** אֵינוֹ הוֹלֵךְ אַחַר הַמִּטָּה (ת"כ כאן וסנהרין יט). וְעוֹד מִכָּאן לָמְדוּ רַבּוֹתֵינוּ (הוריות יב) שֶׁכֹּהֵן גָּדוֹל מַקְרִיב אוֹנֵן, וְכֵן מַשְׁמָעוֹ, אַף אִם מֵתוּ אָבִיו וְאִמּוֹ אֵינוֹ צָרִיךְ לָצֵאת מִן הַמִּקְדָּשׁ אֶלָּא עוֹבֵד עֲבוֹדָה, **וְלֹא יְחַלֵּל אֵת מִקְדַּשׁ אֱלֹהָיו** , שֶׁאֵינוֹ מְחַלֵּל בְּכָךְ אֶת הָעֲבוֹדָה אִם עָבַד כְּשֶׁהוּא אוֹנֵן, שֶׁהִתִּיר לוֹ הַכָּתוּב לַעֲבֹד, הָא הֶדְיוֹט שֶׁעָבַד אוֹנֵן - חִלֵּל, לְשׁוֹן רַשִׁ"י (רש"י על ויקרא כ"א:י"ב). וּשְׁנֵי הַמִּדְרָשִׁים הַלָּלוּ חֲלוּקִים הֵם זֶה עִם זֶה, שֶׁאִם הַכָּתוּב הִתִּיר בְּכֹהֵן גָּדוֹל שֶׁאֵינוֹ צָרִיךְ לָצֵאת מִן הַמִּקְדָּשׁ מִפְּנֵי אֲנִינוּתוֹ כְּהֶדְיוֹט, אֲבָל יָכוֹל הוּא לַעֲבֹד כְּשֶׁהוּא אוֹנֵן, אִם כֵּן אֵין בְּכָאן אַזְהָרָה כְּלָל שֶׁלֹּא יֵצֵא אַחַר הַמִּטָּה. וְכֵן "לֹא יְחַלֵּל אֵת מִקְדַּשׁ אֱלֹהָיו" כְּפִי הַלָּשׁוֹן הַזֶּה אֵינוֹ אֶלָּא לוֹמַר שֶׁאֵין עֲבוֹדָתוֹ מְחֻלֶּלֶת, וּלְלַמֵּד שֶׁהַהֶדְיוֹט שֶׁעָבַד אוֹנֵן - חִלֵּל, וְאִם כֵּן הַכָּתוּב הַזֶּה שְׁלִילוּת, לֹא אַזְהָרָה. וּבַעֲלֵי הַהֲלָכוֹת מְנָאוּהוּ בַּלָּאוִין בַּהֲלָכוֹת פְּסוּקוֹת וּבַהֲלָכוֹת גְּדוֹלוֹת. וְעוֹד שֶׁכְּבָר כָּתַבְתִּי (רמב"ן על ויקרא י':ו') הַבָּרַיְתָא שֶׁהִיא שְׁנוּיָה בְּתוֹרַת כֹּהֲנִים (שמיני מילואים מב מג), וּמְפֹרָשׁ בָּהּ שֶׁהוּא לָאו גָּמוּר, כִּדְקָתָנֵי: "וּמִפֶּתַח אֹהֶל מוֹעֵד לֹא תֵצְאוּ" (ויקרא ח':ל"ג), יָכוֹל בִּשְׁעַת עֲבוֹדָה וְשֶׁלֹּא בִּשְׁעַת עֲבוֹדָה, תַּלְמוּד לוֹמַר "וּמִן הַמִּקְדָּשׁ לֹא יֵצֵא וְלֹא יְחַלֵּל", אֵימָתַי אֵינוֹ יוֹצֵא וְאֵין מְחַלֵּל, הֱוֵי אוֹמֵר בִּשְׁעַת עֲבוֹדָה. וְקָתָנֵי: אֵין לִי אֶלָּא אַהֲרֹן וּבָנָיו שֶׁנִּמְשְׁחוּ בְּשֶׁמֶן הַמִּשְׁחָה שֶׁאִם יָצְאוּ בִּשְׁעַת עֲבוֹדָה חַיָּבִין מִיתָה, מִנַּיִן לְכָל הַכֹּהֲנִים שֶׁבְּכָל הַדּוֹרוֹת וְכוּ'. וַהֲרֵי הוּא לָאו גָּמוּר, אַזְהָרָה שֶׁלֹּא יַנִּיחַ עֲבוֹדָה וְיֵצֵא. לְפִיכָךְ אֲנִי אוֹמֵר כְּדֵי לְקַיֵּם כָּל דִּבְרֵי חֲכָמִים, שֶׁעִקַּר הַכָּתוּב הַזֶּה יַזְהִיר בְּכֹהֵן גָּדוֹל שֶׁלֹּא יֵצֵא מִן הַמִּקְדָּשׁ בִּשְׁעַת עֲבוֹדָה עַל כָּל נַפְשֹׁת מֵת, וְלֹא יְחַלֵּל אֶת הַמִּקְדָּשׁ שֶׁיַּעֲזֹב עֲבוֹדָתוֹ לִכְבוֹד הַמֵּת, אֲבָל יִהְיֶה כְּבוֹד הַמִּקְדָּשׁ וַעֲבוֹדָתוֹ גָּדוֹל עָלָיו מִכְּבוֹד הַמֵּת וְאַהֲבָתוֹ אוֹתוֹ, וְכָל שֶׁכֵּן שֶׁאִם מַנִּיחַ עֲבוֹדָתוֹ לְלֹא דָּבָר וְיוֹצֵא שֶׁעוֹבֵר בַּלָּאו הַזֶּה. אֲבָל הִזְהִירוֹ הַכָּתוּב בְּעִנְיַן הַמֵּת לְהַתִּיר לוֹ הָעֲבוֹדָה כְּשֶׁהוּא אוֹנֵן, וּמֵאַחַר שֶׁהִיא מֻתֶּרֶת לוֹ, אִם יַנִּיחֶנָּה מֵרְצוֹן עַצְמוֹ יִהְיֶה חִלּוּל הַמִּקְדָּשׁ. וְזֶה הוּא פֵּרוּשׁ הַכָּתוּב הַזֶּה. וּכְבָר כְּתַבְתִּיו בְּסֵדֶר וַיְהִי בַּיּוֹם הַשְּׁמִינִי. וְעוֹד מָצִינוּ שֶׁנֶּחְלְקוּ רַבּוֹתֵינוּ בְּפֶרֶק שֵׁנִי שֶׁל מַסֶּכֶת זְבָחִים (זבחים ט"ז) וְאָמְרוּ, אוֹנֵן מְנָא לַן דְּמַחֵל עֲבוֹדָה, דִּכְתִיב "וּמִן הַמִּקְדָּשׁ לֹא יֵצֵא וְלֹא יְחַלֵּל", הָא אַחֵר שֶׁלֹּא יָצָא חִלֵּל. וְרַבִּי אִלְעַאי אָמַר מֵהָכָא, "הֵן הַיּוֹם הִקְרִיבוּ אֶת חַטָּאתָם וְאֶת עֹלָתָם" (ויקרא י':י"ט), אֲנִי הִקְרַבְתִּי, מִכְּלָל דְּאִי אִינְהוּ אַקְרְבוּ שַׁפִּיר וְכוּ'. וְרַבִּי אִלְעַאי מַאי טַעְמָא לָא אָמַר "וּמִן הַמִּקְדָּשׁ לֹא יֵצֵא", אֲמַר לָךְ מִי כְּתִיב הָא אַחֵר שֶׁלֹּא יָצָא חִלֵּל. וְהָעִנְיָן לוֹמַר כִּי כֵּיוָן שֶׁאָמַר הַכָּתוּב אַזְהָרָה בְּכֹהֵן גָּדוֹל שֶׁלֹּא יֵצֵא וְלֹא יְחַלֵּל הָעֲבוֹדָה בְּהַנִּיחוֹ אוֹתָהּ, אֵין לְכֹהֵן הֶדְיוֹט בַּמַּשְׁמָע הַזֶּה שֶׁיְּחַלֵּל כְּשֶׁיַּעֲבֹד. וּמִכָּאן רְאָיָה עוֹד שֶׁאֵינֶנּוּ רְשׁוּת לְהַתִּיר הָעֲבוֹדָה לְכֹהֵן גָּדוֹל וּלְהוֹדִיעוֹ שֶׁאֵין עֲבוֹדָתוֹ מְחֻלֶּלֶת בְּכָךְ, כִּי הָיָה יוֹצֵא מִזֶּה בְּוַדַּאי שֶׁכֹּהֵן הֶדְיוֹט מְחַלֵּל אוֹתָהּ. וְהִנֵּה יֵרָאֶה מִזֶּה בִּפְשׁוּטוֹ כִּי עַל דַּעַת הַפֵּרוּשׁ הָרִאשׁוֹן הוּא שְׁלִילוּת בְּכֹהֵן גָּדוֹל שֶׁאֵינוֹ מְחַלֵּל עֲבוֹדָתוֹ כִּלְשׁוֹן רַשִׁ"י. אֲבָל מִפְּנֵי שֶׁהַבָּרַיְתָא מְפֹרֶשֶׁת שֶׁהוּא אַזְהָרָה, נֹאמַר שֶׁהֵם יִסְבְּרוּ כִּי מֵאַחַר שֶׁאֵין הָאַזְהָרָה אֶלָּא בְּכֹהֵן גָּדוֹל, וּמִכְּלַל שֶׁהַהֶדְיוֹט יוֹצֵא וּמַנִּיחַ הָעֲבוֹדָה מִזֶּה נִלְמֹד שֶׁהִיא מְחֻלֶּלֶת, וְאִלּוּ הָיְתָה כְּשֵׁרָה לֹא יַתִּיר לוֹ לְהַנִּיחָהּ. וְכָךְ שְׁנוּיָה בְּתוֹרַת כֹּהֲנִים בַּפָּרָשָׁה הַזֹּאת (פרשה ב ו), וּמִנַּיִן שֶׁאִם עָבַד עֲבוֹדָתוֹ כְּשֵׁרָה, תַּלְמוּד לוֹמַר "וְלֹא יְחַלֵּל אֵת מִקְדַּשׁ אֱלֹהָיו", הָא כֹּהֵן הֶדְיוֹט שֶׁעָבַד עֲבוֹדָתוֹ פְּסוּלָה. וְהַסֻּגְיָא שֶׁשְּׁנוּיָה בְּסַנְהֶדְרִין (יט), "וּמִן הַמִּקְדָּשׁ לֹא יֵצֵא", שֶׁאֵינוֹ יוֹצֵא אַחַר הַמִּטָּה עִמָּהֶם אֶלָּא הֵם נִכְסִין וְהוּא נִגְלֶה הֵם נִגְלִין וְהוּא נִכְסֶה, דִּבְרֵי רַבִּי מֵאִיר, וְרַבִּי יְהוּדָה אוֹמֵר, אֵינוֹ יוֹצֵא מִן הַמִּקְדָּשׁ כְּלָל, שֶׁנֶּאֱמַר "וּמִן הַמִּקְדָּשׁ לֹא יֵצֵא", וּפֵרְשׁוּ בְּטַעְמוֹ שֶׁל רַבִּי מֵאִיר, "וּמִן הַמִּקְדָּשׁ" - מִקְּדֻשָּׁתוֹ לֹא יֵצֵא, וְכֵוָן דְּאִית לֵהּ הֶכֵּירָא לָא אָתֵי לְמִנְגַּע. וְרַבִּי יְהוּדָה, אַגַּב מְרָרֵהּ דִּלְמָא מִקְּרֵי וְנָגַע - כָּל זֶה אַסְמַכְתָּא מִדִּבְרֵיהֶם, שֶׁהֵם הִנְהִיגוּ סִלְסוּל בְּכֹהֵן גָּדוֹל שֶׁלֹּא יֵצֵא אַחַר הַמִּטָּה, לְפִי שֶׁהוּא אֵינוֹ מִטַּמֵּא לִקְרוֹבִים וְאָדָם בָּהוּל עַל מֵתוֹ שֶׁמָּא יִגַּע בָּהֶן, כְּעִנְיַן "וַיִּפֹּל יוֹסֵף עַל פְּנֵי אָבִיו" (בראשית נ א), אֲבָל כֹּהֵן הֶדְיוֹט עַל קְרוֹבָיו הוּא מִטַּמֵּא וְעַל אֲחֵרִים אֵינוֹ בָּהוּל שֶׁיִּטַּמָּא לָהֶן. וְכָל זֶה בְּכֹהֵן גָּדוֹל מַעֲלָה מִדִּבְרֵיהֶם, וְסָמְכוּ אוֹתָהּ לַכָּתוּב הַזֶּה כְּדֶרֶךְ הָאַסְמַכְתּוֹת בַּתַּלְמוּד. וְכָךְ מָצָאתִי בַּתּוֹסֶפְתָּא בְּסַנְהֶדְרִין (פ"ד ה"א), אָמְרוּ לְרַבִּי יְהוּדָה, אֵין "מִן הַמִּקְדָּשׁ לֹא יֵצֵא" אֶלָּא בִּשְׁעַת עֲבוֹדָה בִּלְבַד. וְעוֹד שָׁם בַּיְּרוּשַׁלְמִי (פ"ב ה"א) רְאָיוֹת אֵין כָּאן מְקוֹם הַזְכָּרָתָם:
@13 **וְהוּא אִשָּׁה בִבְתוּלֶיהָ יִקָּח** פֵּרוּשׁ אֲבָל לֹא בְּעוּלָה, וְהוּא לָאו הַבָּא מִכְּלַל עֲשֵׂה, וְאַחֲרֵי כֵן הִזְהִיר בְּלָאו עַל הָאַלְמָנָה וְהַפְּסוּלוֹת, וְאָמַר "כִּי אִם בְּתוּלָה מֵעַמָּיו יִקַּח אִשָּׁה" לְצַוּוֹת עָלָיו שֶׁיִּקָּחֶנָּה. וְזֶהוּ שֶׁאָמְרוּ רַבּוֹתֵינוּ (הוריות יא), מֻזְהָר עַל הָאַלְמָנָה וּמְצֻוֶּה עַל הַבְּתוּלָה. וְכָךְ שָׁנוּ בְּתוֹרַת כֹּהֲנִים (פרק ב ו), "כִּי אִם בְּתוּלָה", מְלַמֵּד שֶׁהוּא מְצֻוֶּה עַל הַבְּתוּלָה:
@15 **וְלֹא יְחַלֵּל זַרְעוֹ בְּעַמָּיו** הָא אִם נָשָׂא אַחַת מִן הַפְּסוּלוֹת - זַרְעוֹ מִמֶּנָּה חָלָל מִדִּין קְדֻשַּׁת כְּהֻנָּה, לְשׁוֹן רַשִׁ"י (רש"י על ויקרא כ"א:ט"ו). פֵּרְשׁוֹ הָרַב לִשְׁלִילוּת בִּלְבַד, אֶת אֵלֶּה לֹא יִקָּח שֶׁלֹּא יִתְחַלֵּל זַרְעוֹ. וְעַל דַּעַת רַבּוֹתֵינוּ (קידושין עח) הוּא לָאו שֵׁנִי, וְכָךְ אָמְרוּ, קִדֵּשׁ וּבָעַל - לוֹקֶה שְׁתַּיִם, אַחַת מִשּׁוּם "לֹא יִקָּח" וְאַחַת מִשּׁוּם "לֹא יְחַלֵּל". וְאָמְרוּ, בָּעַל וְלֹא קִדֵּשׁ - לוֹקֶה מִשּׁוּם "לֹא יְחַלֵּל". וְהִנֵּה הֵם שְׁנֵי לָאוִין, וְנִדְרָשׁ לָהֶם גַּם כֵּן כְּטַעַם קִדֵּשׁ וְלֹא בָּעַל אֵינוֹ לוֹקֶה, מָה טַעַם לֹא יִקַּח, מִשּׁוּם לֹא יְחַלֵּל. אִם כֵּן פֵּרוּשׁוֹ - אֶת אֵלֶּה לֹא יִקָּח כִּי אֲנִי מַזְהִירוֹ בְּלֹא יְחַלֵּל זַרְעוֹ. וּמֵאֵלֵינוּ נִלְמֹד שֶׁהַזֶּרַע מִן הַפְּסוּלוֹת הוּא מְחֻלָּל:
@17 **דַּבֵּר אֶל אַהֲרֹן אִישׁ מִזַּרְעֲךָ** לֹא אָמַר בְּכָאן "דַּבֵּר אֶל אַהֲרֹן וְאֶל בָּנָיו" כַּאֲשֶׁר יֹאמַר בַּפָּרָשִׁיּוֹת כֻּלָּן, וְהַטַּעַם כִּי שָׁם צִוָּה בְּפָרָשִׁיּוֹת הַקָּרְבָּנוֹת, זֹאת תּוֹרַת הָעוֹלָה (ויקרא ו':ב') וְזֹאת תּוֹרַת הַחַטָּאת (שם פסוק יח) וְהָאָשָׁם וְכַיּוֹצֵא בָּזֶה, אֲבָל בְּכָאן אִם אָמַר "דַּבֵּר אֶל אַהֲרֹן וְאֶל בָּנָיו" רָאוּי שֶׁיֹּאמַר "אִישׁ מִכֶּם לְדֹרֹתֵיכֶם", וְלֹא יִרְצֶה לְהַזְהִיר אֶת אַהֲרֹן עַצְמוֹ בְּתוֹרַת הַמּוּמִין, כִּי אַהֲרֹן קְדוֹשׁ ה' כֻּלּוֹ יָפֶה וּמוּם לֹא יִהְיֶה בּוֹ, אֲבָל יַזְהִירֶנּוּ עַל זַרְעוֹ שֶׁיּוֹרֵם וְיַזְהִיר אוֹתָם לְדֹרֹתָם. וּבְפָרָשַׁת הַטֻּמְאָה בְּסָמוּךְ (ויקרא כ"ב:ב') "דַּבֵּר אֶל אַהֲרֹן וְאֶל בָּנָיו וְיִנָּזְרוּ מִקָּדְשֵׁי בְנֵי יִשְׂרָאֵל", כִּי יִתָּכֵן שֶׁגַּם בְּאַהֲרֹן אֵרַע טֻמְאַת הַמַּגָּע בְּמֵת אוֹ בְּשֶׁרֶץ. וְכַאֲשֶׁר בָּא לְהַזְכִּיר הַצָּרַעַת וְהַזּוֹב, חָזַר וְאָמַר (שם פסוק ד) "אִישׁ אִישׁ מִזֶּרַע אַהֲרֹן", כִּי לֹא יֶאֱרַע זֶה בְּגוּפוֹ כִּי מַלְאַךְ ה' צְבָאוֹת הוּא. וְאָמַר בְּסוֹף הַפָּרָשָׁה (ויקרא כ"א:כ"ד) "וַיְדַבֵּר מֹשֶׁה אֶל אַהֲרֹן וְאֶל בָּנָיו", שֶׁרָצָה מֹשֶׁה לְהַזְהִיר גַּם אֶת בָּנָיו שֶׁיִּקְחוּ מִפִּיו תּוֹרָה, וְאָמַר כֵּן לִבְנֵי יִשְׂרָאֵל לְהַזְהִיר ב"ד שֶׁל יִשְׂרָאֵל עַל כָּךְ. וּבְת"כ (פרשה ג ה) מָצָאתִי, "כָּל אִישׁ", מַה תַּלְמוּד לוֹמַר, לְפִי שֶׁנֶּאֱמַר "זֶרַע אַהֲרֹן", אֵין לִי אֶלָּא זַרְעוֹ, אַהֲרֹן עַצְמוֹ מִנַּיִן, תַּלְמוּד לוֹמַר "כִּי כָל אִישׁ אֲשֶׁר בּוֹ מוּם" (ויקרא כ"א:י"ח). וְכֵן שָׁנוּ שָׁם (פרק ד א), "זֶרַע אַהֲרֹן", אֵין לִי אֶלָּא זַרְעוֹ, אַהֲרֹן עַצְמוֹ מִנַּיִן, תַּלְמוּד לוֹמַר "וְהוּא צָרוּעַ אוֹ זָב" (ויקרא כ"ב:ד'). וּפֵרוּשׁ "אַהֲרֹן עַצְמוֹ" - הַכֹּהֵן הַגָּדוֹל תַּחְתָּיו מִבָּנָיו, כִּי בַּעֲבוּר שֶׁהִתִּיר הָאֲנִינוּת לְכֹהֵן גָּדוֹל אוּלַי יַתִּיר לוֹ הַמּוּם וְהַצָּרַעַת, וְהֻצְרַךְ לְרַבּוֹתוֹ. אוֹ שֶׁתִּרְמֹז דִּין אַהֲרֹן עַצְמוֹ, כִּי לֹא תִּסְמֹךְ הַתּוֹרָה בְּאַזְהָרוֹתֶיהָ עַל הַנֵּס, אֲבָל כִּסְּתָה עַל אַהֲרֹן לִכְבוֹדוֹ וְלִרְמֹז לָנוּ שֶׁלֹּא יֶאֱרַע לוֹ כֵן:
@18 **חָרֻם אוֹ שָׂרוּעַ** כֹּל שֶׁחָטְמוֹ שָׁקוּעַ בֵּין שְׁתֵּי הָעֵינַיִם, שֶׁכּוֹחֵל שְׁתֵּי עֵינָיו כְּאַחַת, לְשׁוֹן רַשִׁ"י (רש"י על ויקרא כ"א:י"ח). וּבְתוֹרַת כֹּהֲנִים (פרשה ג ז) וּבַגְּמָרָא דִּבְכוֹרוֹת (מג) שָׁנִינוּ, חָרוּם - שֶׁחָטְמוֹ שָׁקוּעַ; חָטְמוֹ בָּלוּם, חָטְמוֹ סוֹלֵד, חָטְמוֹ נוֹטֵף מִנַּיִן, תַּלְמוּד לוֹמַר "אוֹ חָרוּם". אַבָּא יוֹסֵי אוֹמֵר, אֵין חָרוּם אֶלָּא הַכּוֹחֵל שְׁתֵּי עֵינָיו כְּאַחַת. אָמְרוּ לוֹ, הִפְלַגְתָּ, אע"פ שֶׁאֵינוֹ יָכוֹל לִכְחֹל שְׁתֵּי עֵינָיו כְּאַחַת. וּלְשׁוֹן "חָרוּם" מִלְּשׁוֹן "כָּל חֵרֶם אֲשֶׁר יָחֳרַם" (ויקרא כ"ז:כ"ט), "וְהַחֲרַמְתִּי אֶת עָרֵיהֶם" (במדבר כא ב), עִנְיַן חֻרְבָּן, וְיִקָּרֵא "חָרוּם" כִּי הַחֹטֶם הַדְרַת פָּנִים, כְּמוֹ שֶׁאָמְרוּ (יבמות קכ), אֵין מְעִידִין אֶלָּא עַל פַּרְצוּף פָּנִים עִם הַחֹטֶם, וַאֲשֶׁר אֵין חָטְמוֹ כְּתֹאַר בְּנֵי הָאָדָם צוּרָתוֹ חֲרֵבָה. וְטַעַם "אוֹ גִבֵּן" (ויקרא כ"א:כ'), נִמְשָׁךְ אֶל מִלַּת "בְּעֵינוֹ", אוֹ שֶׁהוּא גִּבֵּן בְּעֵינוֹ, אוֹ דַק אוֹ תְּבַלֻּל בְּעֵינוֹ, וְהוּא שֶׁגַּבּוֹת עֵינָיו שׁוֹכְבוֹת עֲלֵיהֶן, מִלְּשׁוֹן "גַּב הַמִּזְבֵּחַ" (יחזקאל מג יג), "עַל גַּבִּי חָרְשׁוּ חֹרְשִׁים" (תהלים קכט ג). וְהִזְכִּיר תְּחִלָּה הַמּוּם בְּחֶסְרוֹן הָאֵבָרִים, עִוֵּר אוֹ פִסֵּחַ, וְאַחֲרֵי כֵּן בְּקַטְנוּת כְּגוֹן הֶחָרוּם, וּבְגֹדֶל כְּגוֹן הַשָּׂרוּעַ, וְאח"כ בְּשִׁבְרוֹן הָעֲצָמוֹת, אע"פ שֶׁכָּל אֵבָרָיו עִמּוֹ כֵּיוָן שֶׁנִּשְׁבַּר הָעֶצֶם פָּסוּל, וְאח"כ פָּסַל אֲפִילּוּ בְּכִעוּר הַתֹּאַר, כְּגוֹן הַגִּבֵּן וַאֲשֶׁר בְּעֵינָיו הַגַּרְעִינִין, וְאַחַר כָּךְ בִּבְשַׂר הַגּוּף, כִּי צָרִיךְ שֶׁיִּהְיֶה נָקִי וְחָלָק, וְאַחֲרֵי כֵן הוֹסִיף בַּעַל הָרוּחַ אֲשֶׁר בֵּיצָיו נְפוּחִים בּוֹ, אע"פ שֶׁהוּא חֹלִי נָהוּג בַּזְּקֵנִים וְאֵינוֹ מוּם בַּעֶצֶם אוֹ בַּבָּשָׂר. וְרַבּוֹתֵינוּ בֵּאֲרוּ (בכורות פרקים ו ז) מוּמִים רַבִּים נִלְמָדִים מֵאֵלֶּה, כִּי הַנִּזְכָּרִים בַּתּוֹרָה אָבוֹת לָהֶן:
@26 **וְלֹא יְחַלְּלוּ אֶת שֵׁם קָדְשִׁי אֲשֶׁר הֵם מַקְדִּשִׁים לִי** סָרֵס הַמִּקְרָא וְדָרְשֵׁהוּ, וְיִנָּזְרוּ מִקָּדְשֵׁי בְנֵי יִשְׂרָאֵל אֲשֶׁר הֵם מַקְדִּשִׁים לִי וְלֹא יְחַלְּלוּ אֶת שֵׁם קָדְשִׁי. **אֲשֶׁר הֵם מַקְדִּשִׁים לִי** , לְרַבּוֹת קָדְשֵׁי כֹהֲנִים עַצְמָן, לְשׁוֹן רַשִׁ"י (רש"י על ויקרא כ"ב:ב'). וְאִם נְפָרֵשׁ "אֲשֶׁר הֵם מַקְדִּשִׁים לִי" בַּכֹּהֲנִים עַצְמָן, אֵין צֹרֶךְ לַסֵּרוּס הַזֶּה, אֲבָל יֹאמַר הַכָּתוּב, וְיִנָּזְרוּ מִקָּדְשֵׁי בְנֵי יִשְׂרָאֵל וְלֹא יְחַלְּלוּ בָּהֶם אֶת שֵׁם קָדְשִׁי, וַאֲשֶׁר הֵם מַקְדִּישִׁים לִי, שֶׁלֹּא יְחַלְּלוּ אֶת אֲשֶׁר אַהֲרֹן וּבָנָיו עַצְמָם מַקְדִּישִׁים לִי. וּבְתוֹרַת כֹּהֲנִים (פרשה ד א) כָּךְ הוּא נִדְרָשׁ, "וְיִנָּזְרוּ מִקָּדְשֵׁי בְנֵי יִשְׂרָאֵל", עַל קָדְשֵׁי בְּנֵי יִשְׂרָאֵל חַיָּבִים מִשּׁוּם פִּגּוּל נוֹתָר וְטָמֵא וְאֵין חַיָּבִים עַל קָדְשֵׁי גּוֹיִם מִשּׁוּם פִּגּוּל נוֹתָר וְטָמֵא. "קָדְשֵׁי יִשְׂרָאֵל", אֵין לִי אֶלָּא קָדְשֵׁי יִשְׂרָאֵל, קָדְשֵׁי עַצְמָן מִנַּיִן, תַּלְמוּד לוֹמַר "אֲשֶׁר הֵם מַקְדִּשִׁים לִי אֲנִי ה'" לְרַבּוֹת אֶת כֻּלָּם. וְלֹא הֻזְכַּר שָׁם סֵרוּס הַמִּקְרָא כְּלָל. וְעַל דֶּרֶךְ הָאֱמֶת, אֲשֶׁר הֵם מַקְדִּשִׁים לִי אֲנִי ה', שֶׁלֹּא יְחַלְּלוּ הַשֵּׁם הַמְקֻדָּשׁ לוֹ, כִּי שְׁמוֹ בְּמִקְדַּשׁ ה'. וּכְבָר רָמַזְתִּי זֶה בְּפָרָשַׁת וְיִקְחוּ לִי תְּרוּמָה:
@32 **נְבֵלָה וּטְרֵפָה לֹא יֹאכַל לְטָמְאָה בָהּ** יֹאמַר שֶׁיִּזָּהֵר מֵאֲכִילַת נְבֵלָה וּטְרֵפָה, שֶׁלֹּא יִטְמָא בָהּ וְיִצְטָרֵךְ לְהִנָּזֵר מִן הַקֳּדָשִׁים, וְלֹא יֹאכַל בָּהֶם עַד שֶׁיִּרְחַץ בְּשָׂרוֹ בַּמָּיִם וּבָא הַשֶּׁמֶשׁ וְטָהֵר. וְהַטַּעַם בַּעֲבוּר שֶׁהִזְכִּיר טֻמְאַת הָאָדָם לְכָל טֻמְאוֹתָיו, כִּי הִזְכִּיר הַצָּרַעַת וְהַזּוֹב שֶׁיִּכְלֹל הַזָּכָר וְהַנְּקֵבָה, וְטֻמְאַת הַמֵּת וְשִׁכְבַת הַזֶּרַע וְהַשֶּׁרֶץ, חָזַר לְהַזְהִיר מִן הַקֳּדָשִׁים בְּטֻמְאַת הַנְּבֵלוֹת, וְהִזְהִיר בָּהֶם דֶּרֶךְ הַתְרָאָה בַּאֲכִילָתָן. וְהַטַּעַם כִּי בַּעֲבוּר שֶׁנֶּפֶשׁ הָאָדָם קָצָה בַּאֲכִילַת הַשְּׁרָצִים וְלֹא תָּקֹץ בִּנְבֵלָה וּטְרֵפָה, הִזְהִיר עַל הַטֻּמְאָה בַּהוֹוֶה. וְהַטְּרֵפָה הַנִּזְכֶּרֶת כָּאן טְרֵפַת הָאֲרִי וְהַדֹּב שֶׁהֵמִית אוֹתָהּ בַּשָּׂדֶה, כִּי מֵחַיִּים לֹא תְּטַמֵּא, כִּי מֵעֵת שֶׁתִּטָּרֵף הַבְּהֵמָה מִן הָאֲרִי תִּקָּרֵא טְרֵפָה, בֵּין מֵחַיִּים בֵּין לְאַחַר מִיתָה. וְהִנֵּה הִזְכִּיר כָּאן כָּל הַטֻּמְאוֹת כֻּלָּן, כִּי הַבְּהֵמָה הַטְּמֵאָה אַחַר שֶׁאָמַר שֶׁאֵין לָהּ שְׁחִיטָה, כַּאֲשֶׁר פֵּרַשְׁתִּי בְּסֵדֶר וַיְהִי בַּיּוֹם הַשְּׁמִינִי (רמב"ן על ויקרא י"א:כ"ד), הִנֵּה הִיא בִּכְלַל נְבֵלָה, וְזֶה דֶּרֶךְ פְּשׁוּטוֹ. וּמִדְרָשׁוֹ (ת"כ פרק ד יב יג) גַּם כֵּן לְעִנְיַן הַקֳּדָשִׁים בְּטֻמְאָה הִזְהִיר כָּאן, וּבְנִבְלַת עוֹף טָהוֹר הַכָּתוּב מְדַבֵּר, שֶׁאֵין לָהּ טֻמְאַת מַגָּע וּמַשָּׂא אֶלָּא טֻמְאַת בֵּית הַבְּלִיעָה, וַאֲסָרוֹ לֶאֱכֹל בַּקֳּדָשִׁים. וְצָרִיךְ לוֹמַר "וּטְרֵפָה", מִי שֶׁיֵּשׁ בְּמִינוֹ טְרֵפָה, יָצָא נִבְלַת עוֹף טָמֵא שֶׁאֵין בְּמִינוֹ טְרֵפָה, כִּלְשׁוֹן רַשִׁ"י (רש"י על ויקרא כ"ב:ח'), וְטֻמְאַת שְׁאָר נְבֵלוֹת רִבּוּ אוֹתָהּ בְּת"כ (פרק ד ד) "אֲשֶׁר יִגַּע בְּשֶׁרֶץ" (ויקרא כ"ב:ה'), אֵין לִי אֶלָּא הַשֶּׁרֶץ, מִנַּיִן לְרַבּוֹת אֶת הַנְּבֵלָה, תַּלְמוּד לוֹמַר "בְּכָל":
@38 **וְנָתַן לַכֹּהֵן אֶת הַקֹּדֶשׁ** דָּבָר הָרָאוּי לִהְיוֹת קֹדֶשׁ, שֶׁאֵין פּוֹרֵעַ לוֹ מָעוֹת אֶלָּא פֵּרוֹת שֶׁל חֻלִּין וְהֵם נַעֲשִׂים תְּרוּמָה, לְשׁוֹן רַשִׁ"י (רש"י על ויקרא כ"ב:י"ד). וְהִנֵּה טַעַם הַכָּתוּב, כִּי יֹאכַל קֹדֶשׁ וְיָסַף חֲמִישִׁיתוֹ עַל הַקֹּדֶשׁ הַהוּא, וְנָתַן לַכֹּהֵן אֶת הַקֹּדֶשׁ הַזֶּה שֶׁהוּא הַקֶּרֶן וְהַחֹמֶשׁ. וּמִפְּנֵי שֶׁקְּרָאוֹ "קֹדֶשׁ" לָמַדְנוּ שֶׁהוּא נַעֲשֶׂה כִּתְרוּמָה בְּדָבָר הָרָאוּי לְכָךְ. וְזֶהוּ הַנָּכוֹן בִּפְשׁוּטוֹ וּמִדְרָשׁוֹ. וְכָךְ כָּתַב ר"א (אבן עזרא על ויקרא כ"ב:י"ד), "וְנָתַן לַכֹּהֵן אֶת הַקֹּדֶשׁ", טַעְמוֹ "עִם הַקֹּדֶשׁ", אוֹ שֶׁתִּהְיֶה מִלַּת "וְנָתַן" מוֹשֶׁכֶת עַצְמָהּ וְאַחֶרֶת עִמָּהּ, וְכֵן הוּא אוֹמֵר, וְיָסַף חֲמִשִׁיתוֹ עָלָיו וְנָתַן לַכֹּהֵן וְנָתַן אֶת הַקֹּדֶשׁ. וּלְפִי דַּעְתִּי אֵין צֹרֶךְ, בַּעֲבוּר מִלַּת "עָלָיו":
@39 **וְלֹא יְחַלְּלוּ אֶת קָדְשֵׁי בְּנֵי יִשְׂרָאֵל** לְהַאֲכִילָם לְזָרִים. **וְהִשִּׂיאוּ אוֹתָם עֲוֹן אַשְׁמָה** אֶת עַצְמָם יַטְעִינוּ עָוֹן בְּאָכְלָם אֶת הַקֳּדָשִׁים שֶׁהֻבְדְּלוּ לְשֵׁם תְּרוּמָה וְקָדְשׁוּ וְנֶאֶסְרוּ עֲלֵיהֶם. וְאוּנְקְלוֹס שֶׁתִּרְגֵּם "בְּמֵיכַלְהוֹן בְּסוֹאֲבָא", שֶׁלֹּא לְצֹרֶךְ תִּרְגְּמוֹ כֵן, לְשׁוֹן רַשִׁ"י (רש"י על ויקרא כ"ב:ט"ז) זַ"ל. וְלֹא הֲבִינוֹתִי דַּעְתּוֹ, כִּי יֵרָאֶה מִדְּבָרָיו שֶׁזֶּה הַלָּאו אַזְהָרָה בַּכֹּהֲנִים הוּא שֶׁלֹּא יַאֲכִילוּ הַתְּרוּמָה לְזָרִים, וְאִם כֵּן רָאוּי שֶׁנְּפָרֵשׁ שֶׁיִּהְיֶה "וְהִשִּׂיאוּ אוֹתָם" כִּנּוּי לְיִשְׂרָאֵל, שֶׁיַּטְעִינוּ הַכֹּהֲנִים לְיִשְׂרָאֵל עֲוֹן אַשְׁמָה כַּאֲשֶׁר יֹאכְלוּ הַקֳּדָשִׁים, וְלָמָּה הֻצְרַךְ רַבִּי יִשְׁמָעֵאל לְדָרְשׁוֹ בְּעַצְמָם (ספרי נשא לב), וְעוֹד שֶׁלֹּא הֻזְכַּר זֶה הַלָּאו בַּתַּלְמוּד אֶלָּא הוּא אָסוּר לַעֲשׂוֹת כֵּן כְּבִשְׁאָר כָּל הָאִסּוּרִין. אֲבָל טַעַם הַכָּתוּב כִּי "בְּנֵי יִשְׂרָאֵל" נִמְשָׁךְ לְמַעְלָה, וְלֹא יְחַלְּלוּ בְּנֵי יִשְׂרָאֵל אֶת קָדְשֵׁי בְּנֵי יִשְׂרָאֵל אֵת אֲשֶׁר יָרִימוּ לַה', וְהוּא אַזְהָרָה שֵׁנִית בְּזָר שֶׁלֹּא יֹאכַל קֹדֶשׁ, בַּעֲבוּר שֶׁיִּרְצֶה לְהַזְכִּיר בּוֹ הָעֹנֶשׁ. וְאָמַר, וְהִשִּׂיאוּ אֶת עַצְמָם וְגוֹ', כַּאֲשֶׁר יֹאכְלוּ אֶת קָדְשֵׁיהֶם. וְרַבּוֹתֵינוּ דָּרְשׁוּ מִפְּנֵי יִתּוּרוֹ בְּאוֹכֵל טֶבֶל, אָמְרוּ (סנהדרין פג), מִנַּיִן לָאוֹכֵל טֶבֶל שֶׁהוּא בְּמִיתָה, שֶׁנֶּאֱמַר "וְלֹא יְחַלְּלוּ אֶת קָדְשֵׁי בְּנֵי יִשְׂרָאֵל אֵת אֲשֶׁר יָרִימוּ לַה'", בַּעֲתִידִין לִתְרֹם הַכָּתוּב מְדַבֵּר, וְיָלֵף חִלּוּל חִלּוּל מִתְּרוּמָה. אֲבָל בְּת"כ (פרק ו ח-י) מָצָאתִי, "וְלֹא יְחַלְּלוּ", לְהָבִיא אֶת הַסָּךְ וְאֶת הַשּׁוֹתֶה. "אֶת קָדְשֵׁי בְּנֵי יִשְׂרָאֵל" עַל קָדְשֵׁי בְּנֵי יִשְׂרָאֵל חַיָּבִין קֶרֶן וְחֹמֶשׁ וְאֵין חַיָּבִין עַל קָדְשֵׁי גּוֹיִם קֶרֶן וְחֹמֶשׁ. יָכוֹל יְהוּ חַיָּבִין עַל הַתְּרוּמָה שֶׁבַּטֶּבֶל, תַּלְמוּד לוֹמַר "אֵת אֲשֶׁר יָרִימוּ לַה'", עַל הַמּוּרָם הֵם חַיָּבִים וְאֵין חַיָּבִין עַל הַתְּרוּמָה שֶׁבַּטֶּבֶל. "וְהִשִּׂיאוּ אוֹתָם עֲוֹן אַשְׁמָה", מְלַמֵּד שֶׁאַף עַל הַטֶּבֶל חַיָּבִין מִיתָה. וְזֶה אֵינוֹ כְּדֶרֶךְ הַגְּמָרָא, אֶלָּא שֶׁאֲנִי אוֹמֵר רִבּוּי הַסָּךְ וְהַשּׁוֹתֶה אַסְמַכְתָּא, כִּי שְׁתִיָּה בִּכְלַל אֲכִילָה וְסִיכָה מִדְּרַבָּנָן, כָּךְ מְפֹרָשׁ בַּיְּרוּשַׁלְמִי (מעשר שני פ"ב ה"א). וּמִפְּנֵי שֶׁאָמַר בְּטֶבֶל "וְלֹא יְחַלְּלוּ אֶת קָדְשֵׁי בְּנֵי יִשְׂרָאֵל" בַּעֲבוּר שֶׁהֵם עֲתִידִין לְהָרִים מִמֶּנּוּ לַה', דָּרְשׁוּ מִזֶּה שֶׁהַמּוּרָם הוּא הַנִּקְרָא קֹדֶשׁ, לֹא הַטֶּבֶל, וְא"כ אֵינֶנּוּ בִּכְלַל "כִּי יֹאכַל קֹדֶשׁ בִּשְׁגָגָה" (ויקרא כ"ב:י"ד) שֶׁיִּתְחַיֵּב בְּחֹמֶשׁ, וּלְכָךְ חָזַר וְשָׁנָה "וְהִשִּׂיאוּ אוֹתָם עֲוֹן אַשְׁמָה", מְלַמֵּד שֶׁאַף עַל הַטֶּבֶל חַיָּבִין מִיתָה, כִּי הַתְּרוּמָה שֶׁבַּטֶּבֶל הִיא שֶׁהֻזְכְּרָה כָּאן. וְהַכְּלָל כִּי הַכָּתוּב הַזֶּה בְּטֶבֶל, וְהִזְהִיר וְעָנַשׁ תְּחִלָּה עַל הַקֹּדֶשׁ הַמּוּרָם, וְחָזַר וְהִזְהִיר עַל שֶׁיָּרִימוּ בֶּעָתִיד, כְּפִי מִדְרַשׁ רַבּוֹתֵינוּ:
@42 **לְכָל נִדְרֵיהֶם וּלְכָל נִדְבוֹתָם** נִדְרֵיהֶם - הָאוֹמֵר הֲרֵי עָלַי, נִדְבוֹתָם - הָאוֹמֵר הֲרֵי זוֹ, לְשׁוֹן רַשִׁ"י (רש"י על ויקרא כ"ב:י"ח). וְהַנִּרְאֶה בְּעֵינַי בַּעֲבוּר שֶׁאָמַר הַכָּתוּב (ויקרא כ"ב:כ"א) "לְפַלֵּא נֶדֶר אוֹ לִנְדָבָה", וְכֵן יֹאמַר בְּכָל מָקוֹם, בְּפָרָשַׁת נְסָכִים (במדבר טו ג ח), וְכֵן "כִּי יַפְלִא נֶדֶר בְּעֶרְכְּךָ נְפָשֹׁת" (ויקרא כ"ז:ב'), וְכֵן בְּפָרָשַׁת נָזִיר (במדבר ו ב), כִּי הַנֶּדֶר הוּא הַבָּא עַל דָּבָר שֶׁיִּפָּלֵא מִמֶּנּוּ, שֶׁיִּדֹּר לַה' בַּצַּר לוֹ, אִם תַּעֲשֶׂה עִמִּי לְהַפְלִיא לְהַצִּילֵנִי מִן הַצָּרָה הַזֹּאת אָבִיא עוֹלָה אוֹ שְׁלָמִים, כְּעִנְיַן "וַיִּדַּר יַעֲקֹב נֶדֶר לֵאמֹר אִם יִהְיֶה אֱלֹהִים עִמָּדִי" (בראשית כח כ), "וַיִּדַּר יִשְׂרָאֵל נֶדֶר לַה' וַיֹּאמַר אִם נָתוֹן תִּתֵּן" (במדבר כא ב), "וַיִּדְּרוּ נְדָרִים" (יונה א טז), וְכֵן כֻּלָּם. וְרַבּוֹתֵינוּ אָמְרוּ (קנים פ"א מ"א), אֵי זֶהוּ נֶדֶר, הָאוֹמֵר הֲרֵי עָלַי עוֹלָה, נְדָבָה - הָאוֹמֵר הֲרֵי זוֹ עוֹלָה, וּמָה בֵּין נֶדֶר לִנְדָבָה, נֶדֶר - מֵת אוֹ נִגְנַב חַיָּב בְּאַחְרָיוּתוֹ וְכוּ', לְהַגִּיד הַחִלּוּק שֶׁבֵּינֵיהֶם, כִּי דֶּרֶךְ הַנּוֹדְרִים בְּצָרָתָם לֵאמֹר אִם יִהְיֶה אֱלֹהִים עִמָּדִי בָּזֶה עָלַי לַעֲשׂוֹת עוֹלָה אוֹ זֶבַח, וְזֶה לֹא יִקָּרֵא נְדָבָה סְתָם, וַאֲשֶׁר יַפְרִישׁוּ וְיִתֵּן מִיָּד הוּא נְדָבָה, כִּי בְּעֵת הַמַּתָּן נָדְבָה רוּחוֹ אוֹתוֹ. וְהִנֵּה אָמַר הַכָּתוּב כִּי בֵּין שֶׁיַּקְרִיב עוֹלָה אוֹ שְׁלָמִים אֲשֶׁר נָדַר עַל צָרָתוֹ אוֹ שֶׁיַּקְרִיב אוֹתָם בְּנִדְבַת רוּחוֹ, יִהְיֶה תָּמִים. אוּלַי נַחְשֹׁב כִּי הַנֶּדֶר רָאוּי לִהְיוֹתוֹ תָּמִים יוֹתֵר מִן הַנְּדָבָה. וְזֶה טַעַם הַכָּתוּב:
@47 **נְדָבָה תַּעֲשֶׂה אוֹתוֹ** לְבֶדֶק הַבַּיִת, **וּלְנֵדֶר לֹא יֵרָצֶה** לַמִּזְבֵּחַ. אֵי זֶהוּ הֶקְדֵּשׁ שֶׁבָּא לְרַצּוֹת, הֱוֵי אוֹמֵר זֶה הֶקְדֵּשׁ מִזְבֵּחַ, לְשׁוֹן רַשִׁ"י (רש"י על ויקרא כ"ב:כ"ג). וּלְפִי זֶה צָרִיךְ שֶׁנִּדְרֹשׁ "נְדָבָה תַּעֲשֶׂה אֹתוֹ וּלְנֵדֶר לֹא יֵרָצֶה" - יֹאמַר שֶׁנַּעֲשֶׂה אוֹתוֹ נְדָבָה אוֹ נֶדֶר לְבֶדֶק הַבַּיִת אֲבָל לֹא לְרָצוֹן עַל הַמִּזְבֵּחַ, כִּי אֵין בֵּין נֶדֶר וּנְדָבָה בָּעִנְיָן הַזֶּה כְּלוּם, שְׁנֵיהֶם מֻתָּרִין לְבֶדֶק הַבַּיִת וַאֲסוּרִין לַמִּזְבֵּחַ. וּכְבָר הִזְכִּיר זֶה הַכָּתוּב בָּעוֹלָה "לְכָל נִדְרֵיהֶם וּלְכָל נִדְבוֹתָם" (ויקרא כ"ב:י"ח), וּבַשְּׁלָמִים "לְפַלֵּא נֶדֶר אוֹ לִנְדָבָה" (ויקרא כ"ב:כ"א), וְכָךְ מִדְרַשׁ רַבּוֹתֵינוּ בְּת"כ (פרק ז ו). וְיִתָּכֵן שֶׁנְּתַקֵּן בְּיִשּׁוּב לְשׁוֹן הַמִּקְרָא כִּי בַּעֲבוּר שֶׁרֹב הַנְּדָבוֹת לְבֶדֶק הַבַּיִת, כְּמוֹ שֶׁאָמַר בַּמִּשְׁכָּן "כֹּל נְדִיב לֵב הֵבִיאוּ אֵת תְּרוּמַת ה'" (שמות לה ה), וְכֵן בַּמִּקְדָּשׁ "אֲנִי בְּיֹשֶׁר לְבָבִי הִתְנַדַּבְתִּי" (דברי הימים א כט יז), וְכֵן בְּבַיִת שֵׁנִי "עִם הַנְּדָבָה לְבֵית הָאֱלֹהִים" (עזרא א ד), וְכֵן כָּתוּב בְּבֶדֶק הַבַּיִת "כָּל כֶּסֶף אֲשֶׁר יַעֲלֶה עַל לֶב אִישׁ לְהָבִיא בֵּית ה'" (מלכים ב יב ה) וְהוּא הַנְּדָבָה. וְהַטַּעַם כִּי אֵין בְּעִנְיַן בֶּדֶק הַבַּיִת חִיּוּב, רַק נִדְבַת הַנֶּפֶשׁ. וּמִנְהַג הַנּוֹתְנִים לְבֶדֶק הַבַּיִת כִּי בִּנְדָבָה יָבִיאוּ "הֲרֵי זוֹ לַבִּנְיָן", לְפִיכָךְ כָּל מָקוֹם שֶׁיַּזְכִּיר נְדָבָה סְתָם הוּא לְבֶדֶק הַבַּיִת, עַד שֶׁיְּפָרֵשׁ בּוֹ לְעוֹלָה אוֹ לְזֶבַח שְׁלָמִים, כְּמוֹ שֶׁהִזְכִּיר לְמַעְלָה (בפסוקים יח כא). וְהַנֶּדֶר יֵאָמֵר סְתָם לְקָדְשֵׁי הַמִּזְבֵּחַ, "לְךָ אֶזְבַּח זֶבַח תּוֹדָה" (תהלים קטז יז), "נְדָרַי לַה' אֲשַׁלֵּם נֶגְדָה נָּא לְכָל עַמּוֹ בְּחַצְרוֹת בֵּית ה'" (שם שם יח יט), "אָבוֹא בֵיתְךָ בְעוֹלוֹת אֲשַׁלֵּם לְךָ נְדָרָי" (שם סו יג), "עָלַי אֱלֹהִים נְדָרֶיךָ אֲשַׁלֵּם תּוֹדֹת לָךְ" (שם נו יג), וְהַנּוֹתְנִים לַמִּזְבֵּחַ בִּנְדָרִים יָבִיאוּ, אִם יַצְלִיחֵנִי אֱלֹהִים אָבֹא לְפָנָיו בְּעוֹלָה. וּלְפִיכָךְ יֹאמַר הַכָּתוּב בְּכָאן וְשׁוֹר אוֹ שֶׂה שָׂרוּעַ וְקָלוּט נְדָבָה תַּעֲשֶׂה אֹתוֹ לְכָל אֲשֶׁר יִדְּבֶנּוּ לִבּוֹ, וּלְנֵדֶר לַה' לֹא יֵרָצֶה, כְּמוֹ שֶׁאָמַר (ויקרא כ"ב:כ') "לֹא תַקְרִיבוּ כִּי לֹא לְרָצוֹן יִהְיֶה לָכֶם", כִּי לֹא אָמַר הַכָּתוּב "נְדָבָה תַּקְרִיב אוֹתוֹ" כַּלָּשׁוֹן הַבָּא בְּכָל הַפָּרָשָׁה, אֲבָל אָמַר "תַּעֲשֶׂה אוֹתוֹ", כְּלוֹמַר תַּעֲשֶׂה אַתָּה מִמֶּנּוּ כֹּל אֲשֶׁר תִּמְצָא יָדְךָ לַעֲשׂוֹת בְּכֹחֲךָ, אֲבָל לְנֶדֶר לְרָצוֹן לֹא יִהְיֶה. וְהֻצְרְכוּ חֲכָמִים לֵאמֹר כָּךְ כִּי לֹא יִתָּכֵן בְּשׁוּם פָּנִים שֶׁיִּהְיוּ הַמּוּמִים כֻּלָּם, הַגָּרָב וְהַיַּלֶּפֶת וַאֲפִילּוּ הַמָּעוּךְ וְהַכָּתוּת, אֲסוּרִין בְּכָל קָרְבָּן, בֵּין בְּנֶדֶר וּבֵין בִּנְדָבָה, וְיִהְיֶה הַשָּׂרוּעַ וְהַקָּלוּט אֲסוּרִין בְּמִקְצָתָן וּמֻתָּרִין בְּמִקְצָתָן, וְלֹא יִמָּצֵא כָּכָה בַּתּוֹרָה בְּמוּמֵי הַמַּקְרִיבִים וּבַטֻּמְאָה לְחַלֵּק בַּקָּרְבָּנוֹת. וּלְכָךְ אָמְרוּ כִּי "תַּעֲשֶׂה אוֹתוֹ" אֵינֶנּוּ כְּמוֹ "תַּקְרִיב אוֹתוֹ". וְיִתָּכֵן שֶׁאָמַר כִּי שׁוֹר וָשֶׂה שָׂרוּעַ וְקָלוּט מֻתָּר לַעֲשׂוֹתוֹ נְדָבָה, לֵאמֹר "הֲרֵי זֶה", אֲבָל אִם נָדַר "הֲרֵי עָלַי שׁוֹר אוֹ שֶׂה" - אִם יְבִיאֶנּוּ מָשְׁחָת לֹא יֵרָצֶה לוֹ וְאֵינֶנּוּ פָּטוּר מִנִּדְרוֹ. וְנֹאמַר עַל דֶּרֶךְ רַבּוֹתֵינוּ שֶׁשְּׁנֵיהֶם לְבֶדֶק הַבַּיִת, כִּי אֵין "תַּעֲשֶׂה אוֹתוֹ" כְּמוֹ "תַּקְרִיב אוֹתוֹ", וְזֶה אֱמֶת הוּא בְּלִי סָפֵק. וְהִזְכִּיר הַכָּתוּב הֶתֵּר הַנְּדָבָה לְבֶדֶק הַבַּיִת בְּשָׂרוּעַ וְקָלוּט, שֶׁהֵן מוּמִין בַּיְּצִירָה מִן הַבֶּטֶן, וְכָל שֶׁכֵּן מוּמֵי הַמִּקְרֶה הַקְּטַנִּים, עַוֶּרֶת אֲשֶׁר בּוֹ עִוָּרוֹן בְּשֶׁכָּהֲתָה עֵינוֹ, וְהַשָּׁבוּר, וְאֵין צָרִיךְ לוֹמַר בַּעַל הַגָּרָב וְהַיַּלֶּפֶת. וְיִתָּכֵן כִּי הַכָּתוּב דָּבֵק, עַוֶּרֶת אוֹ שָׁבוּר אוֹ חָרוּץ אוֹ יַבֶּלֶת אוֹ גָרָב אוֹ יַלֶּפֶת וְכָל שׁוֹר וָשֶׂה שָׂרוּעַ וְקָלוּט - נְדָבָה תַּעֲשֶׂה לְכָל אֶחָד מֵאֵלֶּה, וּלְנֵדֶר לֹא יֵרָצֶה אֶחָד מֵהֶן, שֶׁאֲפִלּוּ עָלוּ יֵרְדוּ. וּבְת"כ (פרק ז ה), מִנַּיִן לְרַבּוֹת כָּל הַפְּסוּלִין שֶׁבְּשׁוֹר וָשֶׂה, תַּלְמוּד לוֹמַר "וְשׁוֹר וָשֶׂה שָׂרוּעַ וְקָלוּט" לְרַבּוֹת כָּל הַפְּסוּלִין שֶׁבְּשׁוֹר וָשֶׂה. וְכָלְלוּ רַבּוֹתֵינוּ (תמורה ז) עוֹד בִּכְלַל "נְדָבָה תַּעֲשֶׂה אוֹתוֹ" שֶׁהוּא יֵעָשֶׂה לִנְדָבָה לְכָל אֲשֶׁר יִרְצֶה, אֲבָל לֹא הַתְּמִימִים, שֶׁהַמַּקְדִּישׁ אוֹתָן לְבֶדֶק הַבַּיִת עוֹבֵר בַּעֲשֵׂה:
@52 **אֹתוֹ וְאֶת בְּנוֹ** נוֹהֵג בַּנְּקֵבָה שֶׁאָסוּר לִשְׁחֹט הָאֵם וְהַבֵּן אוֹ הָאֵם וְהַבַּת, וְאֵינוֹ נוֹהֵג בַּזְּכָרִים וּמֻתָּר לִשְׁחֹט הָאָב וְהַבֵּן, לְשׁוֹן רַשִׁ"י (רש"י על ויקרא כ"ב:כ"ח). פּוֹסֵק הָרַב הֲלָכָה כְּדִבְרֵי הָאוֹמֵר אֵין חוֹשְׁשִׁין לְזֶרַע הָאָב (חולין עט), וְכֵן דַּעַת אוּנְקְלוֹס (תרגום אונקלוס על ויקרא כ"ב:כ"ח), וְהוּא הַנָּכוֹן בַּגְּמָרָא בְּדִין אוֹתוֹ וְאֶת בְּנוֹ. אֲבָל דֶּרֶךְ הַכָּתוּב כְּשֶׁמַּזְכִּיר הַנְּקֵבָה בְּיִחוּד לִקְרוֹת אוֹתָהּ פָּרָה, וְאִם כֵּן הָיָה רָאוּי שֶׁיֹּאמַר הַכָּתוּב, וּפָרָה אוֹ כִּשְׂבָּה אוֹתָהּ וְאֶת בְּנָהּ, אֶלָּא מִפְּנֵי שֶׁהִזְכִּיר "שׁוֹר אוֹ כֶשֶׂב אוֹ עֵז כִּי יִוָּלֵד" וְהִזְכִּיר הָאֵם וְהַבֵּן "וְהָיָה שִׁבְעַת יָמִים תַּחַת אִמּוֹ", אָמַר כִּי בַּמִּינִין הַנִּזְכָּרִים הָאֵלּוּ שֶׁהֵם שׁוֹר וָשֶׂה עוֹד מִצְוָה אַחֶרֶת בָּהֶן, כִּי אוֹתוֹ וְאֶת בְּנוֹ הַנִּזְכָּרִים לֹא יִשְׁחֲטוּ בְּיוֹם אֶחָד:
@55 וְטַעַם **וּשְׁמַרְתֶּם מִצְוֹתַי** בְּכָאן יַזְהִיר אֶת יִשְׂרָאֵל לִשְׁמֹר הַמִּצְוֹת, שֶׁיִּזָּהֲרוּ בַּקָּרְבָּנוֹת בַּמּוּמִים, וּבִמְחֻסְּרֵי הַזְּמַן קֹדֶם שִׁבְעָה, וְיוֹם שֶׁנִּשְׁחֲטָה הָאֵם, וְלַעֲשׂוֹת הַזְּבָחִים וְהַתּוֹדָה וּלְשָׁחְטָם לְרָצוֹן, וְיִכְלֹל כָּל הַמִּצְוֹת בְּיַחַד. וּכְבָר הִזְכִּיר לְמַעְלָה בַּחֻקִּים וּבַמִּשְׁפָּטִים "וּשְׁמַרְתֶּם אֶת כָּל חֻקֹּתַי וְאֶת כָּל מִשְׁפָּטַי" (ויקרא י"ט:ל"ז). וְאָמַר "לֹא תְחַלְּלוּ אֶת שֵׁם קָדְשִׁי" לִהְיוֹת בָּכֶם נוֹכֵל וְזוֹבֵחַ מָשְׁחָת לַה', כְּמוֹ שֶׁאָמַר בִּבְנֵי אַהֲרֹן "וְלֹא יְחַלְּלוּ אֶת שֵׁם קָדְשִׁי" (ויקרא כ"ב:ב'), שֶׁיַּזְהִיר בַּקָּרְבָּנוֹת מִן הַטֻּמְאָה אוֹ הַמּוּמִין:
@56 וְטַעַם **וְנִקְדַּשְׁתִּי בְּתוֹךְ בְּנֵי יִשְׂרָאֵל** עַל דַּעַת רַבּוֹתֵינוּ (תו"כ פרק ט ד) מִצְוַת עֲשֵׂה, שֶׁנְּקַדֵּשׁ אֶת שְׁמוֹ בַּמִּצְוֹת לֵהָרֵג עֲלֵיהֶן וְלֹא נַעֲבֹר. וְזֶה טַעַם "הַמּוֹצִיא אֶתְכֶם מֵאֶרֶץ מִצְרַיִם לִהְיוֹת לָכֶם לֵאלֹהִים", שֶׁהוּא טַעַם יִכְלֹל כָּל הַמִּצְוֹת שֶׁרָאוּי לְקַדֵּשׁ שְׁמוֹ עֲלֵיהֶם בַּעֲבוּר שֶׁאֲנַחְנוּ עֲבָדָיו אֲשֶׁר גְּאָלָנוּ מִמִּצְרַיִם:
@59 **דַּבֵּר אֶל בְּנֵי יִשְׂרָאֵל** אֵין לַכֹּהֲנִים עֵסֶק בְּעִנְיַן הַמּוֹעֲדוֹת יוֹתֵר מֵאֲשֶׁר לְיִשְׂרָאֵל בָּהֶם, עַל כֵּן לֹא הִזְכִּיר בַּפָּרָשָׁה הַזֹּאת אַהֲרֹן וּבָנָיו, רַק "בְּנֵי יִשְׂרָאֵל", שֶׁיִּכְלֹל אֶת כֻּלָּם כְּאֶחָד, כִּי לֹא יְפָרֵשׁ קָרְבְּנוֹת הַמּוּסָפִים בַּפָּרָשָׁה הַזֹּאת. אֲבָל הִזְכִּיר הַמּוֹעֲדִים כָּאן בְּתוֹרַת כֹּהֲנִים בַּעֲבוּר שֶׁהֵם יְמֵי הַקָּרְבָּנוֹת, וְיִרְמֹז אֲלֵיהֶם כְּמוֹ שֶׁאָמַר "וְהִקְרַבְתֶּם אִשֶּׁה לַה'", וְאָמַר בְּסוֹף הַפָּרָשָׁה "אֵלֶּה מוֹעֲדֵי ה' אֲשֶׁר תִּקְרְאוּ אֹתָם מִקְרָאֵי קֹדֶשׁ לְהַקְרִיב אִשֶּׁה לַה' עֹלָה וּמִנְחָה זֶבַח וּנְסָכִים" (ויקרא כ"ג:ל"ז), אֲבָל לֹא הֶאֱרִיךְ לְבָאֵר הַמּוּסָפִים שֶׁלֹּא רָצָה שֶׁיִּנְהֲגוּ לָהֶם בַּמִּדְבָּר. וְאַחֲרֵי שֶׁמָּנָה בָּאֵי הָאָרֶץ בְּחֻמַּשׁ הַפְּקוּדִים, וְצִוָּה "לָאֵלֶּה תֵּחָלֵק הָאָרֶץ" (במדבר כו נג), בֵּאֵר הַמּוּסָפִים כֻּלָּם בְּפָרָשַׁת פִּינְחָס, שֶׁיַּעֲשׂוּ אוֹתָם בָּאָרֶץ מִיָּד וּלְדוֹרוֹת. וְעַל כֵּן אָמַר בְּיוֹם הַכִּפּוּרִים "וַיַּעַשׂ כַּאֲשֶׁר צִוָּה ה' אֶת מֹשֶׁה" (ויקרא ט"ז:ל"ד), שֶׁעָשָׂה כֵן בַּמִּדְבָּר. וְהִזְכִּיר בַּפָּרָשָׁה הַזּוֹ כֶּבֶשׂ הָעֹמֶר וְכִבְשֵׂי עֲצֶרֶת, כִּי בְּיָדוּעַ שֶׁלֹּא יִנְהֲגוּ אֶלָּא בָּאָרֶץ, שֶׁהֵן בָּאִים בִּגְלַל הַלֶּחֶם שֶׁאָמַר בּוֹ "כִּי תָבֹאוּ אֶל הָאָרֶץ וּקְצַרְתֶּם אֶת קְצִירָהּ" וְגוֹ' (ויקרא כ"ג:י'), אֲבָל הַיָּמִים עַצְמָם נוֹהֲגִים מִיָּד. וְהִזְכִּיר הַשַּׁבָּת בְּמוֹעֲדֵי ה' אֲשֶׁר תִּקְרְאוּ אֹתָם מִקְרָאֵי קֹדֶשׁ, שֶׁגַּם הוּא יוֹם מוֹעֵד נִקְרָא אוֹתוֹ מִקְרָא קֹדֶשׁ. וְאַחַר כֵּן הִבְדִּיל שְׁאָר הַמּוֹעֲדוֹת מִמֶּנּוּ וְאָמַר "אֲשֶׁר תִּקְרְאוּ אֹתָם בְּמוֹעֲדָם", כְּלוֹמַר בְּאֵי זֶה יוֹם מִן הַשָּׁבוּעַ שֶׁיַּגִּיעוּ בּוֹ, כִּי הַשַּׁבָּת קָבוּעַ הוּא בְּיוֹמוֹ יָבֹא, לֹא נִצְטָרֵךְ לִקְרֹא אוֹתוֹ בְּמוֹעֲדוֹ. וְעַל דַּעַת רַבּוֹתֵינוּ (ת"כ פרשה ט ה) "אֲשֶׁר תִּקְרְאוּ אֹתָם בְּמוֹעֲדָם", רֶמֶז לָעִבּוּרִים, שֶׁתִּקְרְאוּ אַתֶּם לָהֶם מוֹעֲדִים. וְהַנָּכוֹן בְּעֵינַי כִּי פֵּרוּשׁ "מוֹעֲדֵי ה' אֲשֶׁר תִּקְרְאוּ אֹתָם מִקְרָאֵי קֹדֶשׁ אֵלֶּה הֵם מוֹעֲדָי" עַל הַנִּזְכָּרִים לְמַטָּה בְּפָרָשִׁיּוֹת "בַּחֹדֶשׁ הָרִאשׁוֹן" וְגוֹ', וְלָכֵן חָזַר שָׁם פַּעַם אַחֶרֶת "אֵלֶּה מוֹעֲדֵי ה'" בַּעֲבוּר שֶׁהִפְסִיק בְּעִנְיַן הַשַּׁבָּת. וְהִנֵּה אָמַר "מוֹעֲדֵי ה' אֲשֶׁר תִּקְרְאוּ אֹתָם מִקְרָאֵי קֹדֶשׁ אֵלֶּה הֵם מוֹעֲדָי" בִּמְלֶאכֶת עֲבוֹדָה, אֲבָל הַשַּׁבָּת תִּשְׁמְרוּ לַעֲשׂוֹת אוֹתָהּ שַׁבַּת שַׁבָּתוֹן מִכָּל מְלָאכָה שֶׁבָּעוֹלָם, כִּי יַזְהִיר בַּשַּׁבָּת פְּעָמִים רַבּוֹת. וְיִרְמֹז עוֹד בְּכָאן כִּי גַּם בְּבוֹאוֹ בְּאֶחָד מִן הַמּוֹעֲדִים לֹא תִּדָּחֶה לַעֲשׂוֹת בָּהּ אֹכֶל נֶפֶשׁ. וְכָמוֹהוּ "אֵלֶּה הַדְּבָרִים אֲשֶׁר צִוָּה ה' לַעֲשֹׂת אֹתָם" (שמות לה א) עַל הַמִּשְׁכָּן וְכֵלָיו אֲשֶׁר יַזְכִּיר בַּפָּרָשָׁה הַשְּׁנִיָּה, וְהִפְסִיק בַּשַּׁבָּת "שֵׁשֶׁת יָמִים תֵּעָשֶׂה מְלָאכָה" וְגוֹ' (שם פסוק ב), וְחָזַר וְאָמַר "זֶה הַדָּבָר אֲשֶׁר צִוָּה ה' קְחוּ מֵאִתְּכֶם תְּרוּמָה" (שם פסוק ד), וְהִיא הַמִּצְוָה הָרִאשׁוֹנָה, בַּעֲבוּר שֶׁהִפְסִיק בָּהּ הֻצְרַךְ לַחֲזֹר וּלְהַתְחִיל בָּרִאשׁוֹנָה. וּרְאָיָה לַפֵּרוּשׁ הַזֶּה, שֶׁלֹּא הִזְכִּיר בַּשַּׁבָּת "וְהִקְרַבְתֶּם אִשֶּׁה לַה'" כַּאֲשֶׁר יַזְכִּיר בְּכָל מוֹעֵד וּמוֹעֵד, וְאָמַר בְּסוֹף הַפָּרָשָׁה (ויקרא כ"ג:ל"ז-ל"ח) "אֵלֶּה מוֹעֲדֵי ה' וְגוֹ' מִקְרָאֵי קֹדֶשׁ לְהַקְרִיב אִשֶּׁה לַה' וְגוֹ' מִלְּבַד שַׁבְּתוֹת ה'", שֶׁאֵין הַשַּׁבָּתוֹת בִּכְלַל מוֹעֲדֵי ה'. וּרְאָיָה עוֹד, כִּי לֹא אָמַר בַּפָּרָשָׁה הַשְּׁנִיָּה "וַיְדַבֵּר ה' אֶל מֹשֶׁה לֵּאמֹר" כַּאֲשֶׁר אָמַר בְּכָל מוֹעֵד וּמוֹעֵד, כִּי הַדִּבּוּר הָרִאשׁוֹן הוּא הָיָה מִצְוַת הַמּוֹעֲדִים, אֶלָּא שֶׁהִזְכִּיר לָהֶם הַשַּׁבָּת לִשְׁלֹל מִמֶּנּוּ דִּין הַמּוֹעֲדִים, לֹא לְבָאֵר מִצְוֹתָיו וְתוֹרוֹתָיו, וְלָכֵן לֹא אָמַר בּוֹ "וְהִקְרַבְתֶּם אִשֶּׁה לַה'" כַּאֲשֶׁר אָמַר בַּמּוֹעֲדִים, וְהִזְכִּירָהּ בַּסּוֹף (ויקרא כ"ג:ל"ח) עִם הַנְּדָרִים וְהַנְּדָבוֹת שֶׁלֹּא נִזְכְּרוּ כָּאן כַּאֲשֶׁר פֵּרַשְׁתִּי. וְזֶהוּ מִדְרַשׁ חֲכָמִים שֶׁאָמְרוּ (תו"כ פרשה ט ז), מָה עִנְיַן שַׁבָּת אֵצֶל הַמּוֹעֲדוֹת וְכוּ', כִּי אֵין הַשַּׁבָּת בִּכְלַל מוֹעֲדֵי ה' כְּלָל, רַק סְמָכוֹ הַכָּתוּב לָהֶם. וְטַעַם "מִקְרָאֵי קֹדֶשׁ", שֶׁיִּהְיוּ בַּיּוֹם הַזֶּה כֻּלָּם קְרוּאִים וְנֶאֱסָפִים לְקַדֵּשׁ אוֹתוֹ, כִּי מִצְוָה הִיא עַל יִשְׂרָאֵל לְהִקָּבֵץ בְּבֵית הָאֱלֹהִים בְּיוֹם מוֹעֵד לְקַדֵּשׁ הַיּוֹם בְּפַרְהֶסְיָא בִּתְפִלָּה וְהַלֵּל לָאֵל בִּכְסוּת נְקִיָּה, וְלַעֲשׂוֹת אוֹתוֹ יוֹם מִשְׁתֶּה, כְּמוֹ שֶׁנֶּאֱמַר בַּקַּבָּלָה "לְכוּ אִכְלוּ מַשְׁמַנִּים וּשְׁתוּ מַמְתַקִּים וְשִׁלְחוּ מָנוֹת לְאֵין נָכוֹן לוֹ כִּי קָדוֹשׁ הַיּוֹם לַאֲדֹנֵינוּ וְאַל תֵּעָצֵבוּ כִּי חֶדְוַת ה' הִיא מָעֻזְּכֶם" (נחמיה ח י). וְהִנֵּה "מִקְרָא קֹדֶשׁ" מִלְּשׁוֹן "קְרוּאֵי הָעֵדָה" (במדבר א טז), "אַחֲרֵי כֵן יֹאכְלוּ הַקְּרֻאִים" (שמואל א ט יג), וְכֵן "עַל כָּל מְכוֹן הַר צִיּוֹן וְעַל מִקְרָאֶהָ" (ישעיהו ד ה), הַמְּקוֹמוֹת שֶׁנִּקְרָאִים שָׁם שֶׁיִּתְקַבְּצוּ בָּהֶם קְרוּאֵי הָעֵדָה. וְאוּנְקְלוֹס (תרגום אונקלוס על ויקרא כ"ג:ב') עֲשָׂאוֹ מִלְּשׁוֹן "אֲשֶׁר יִקְרָא אֶתְכֶם בְּאַחֲרִית הַיָּמִים" (בראשית מט א) לְשׁוֹן מְאֹרָע, בְּכָל יוֹם שֶׁיֶּאֶרְעוּ תַּעֲשׂוּ אוֹתָם קֹדֶשׁ. וְרַבּוֹתֵינוּ זַ"ל אָמְרוּ (ספרי פנחס קמז), אָרְעֵם בְּמַאֲכָל וּבְמִשְׁתֶּה וּבִכְסוּת נְקִיָּה. כְּלוֹמַר, שֶׁלֹּא יְהֵא חֻקָּם אֶצְלְךָ כְּחֹק שְׁאָר הַיָּמִים, אֲבָל תַּעֲשֶׂה לָהֶם מִקְרָא שֶׁל קֹדֶשׁ לְשַׁנּוֹתָם בְּמַאֲכָל וּבְמַלְבּוּשׁ מֵחוֹל לְקֹדֶשׁ. וְגַם זֶה דַּעַת אוּנְקְלוֹס:
@64 **כָּל מְלֶאכֶת עֲבוֹדָה** אֲפִלּוּ הַמְּלָאכוֹת הַחֲשׁוּבוֹת לָכֶם עֲבוֹדָה וְצֹרֶךְ שֶׁיֵּשׁ חֶסְרוֹן כִּיס בְּבַטָּלָה שֶׁלָּהֶן, כְּגוֹן דָּבָר הָאָבֵד, כָּךְ הֵבַנְתִּי מִת"כ (פרשה יב ח) דְּקָתָנֵי, יָכוֹל אַף חֻלּוֹ שֶׁל מוֹעֵד יְהֵא אָסוּר בִּמְלֶאכֶת עֲבוֹדָה וְכוּ', לְשׁוֹן רַשִׁ"י (רש"י על ויקרא כ"ג:ח'). וְאֵינֶנּוּ נָכוֹן כְּלָל, כִּי מָה טַעַם שֶׁיֹּאמַר הַכָּתוּב לֹא תַעֲשֶׂה מְלֶאכֶת דָּבָר הָאָבֵד וְיָבֹאוּ שְׁאָר הַמְּלָאכוֹת מִק"ו, וְא"כ רָאוּי שֶׁיֹּאמַר אַף בְּשַׁבָּת כֵּן. וְעוֹד שֶׁא"כ הֲרֵי חֻלּוֹ שֶׁל מוֹעֵד רָמוּז בַּתּוֹרָה שֶׁמֻּתָּר בְּדָבָר הָאָבֵד, וְהֵם אָמְרוּ (חגיגה יח), לֹא מְסָרָהּ הַכָּתוּב אֶלָּא לַחֲכָמִים, שֶׁאֵין בַּתּוֹרָה רֶמֶז אֵיזוֹ מְלָאכָה מֻתֶּרֶת וְאֵיזוֹ מְלָאכָה אֲסוּרָה. וּלְשׁוֹן "עֲבוֹדָה" כּוֹלֵל הוּא כָּל הַמְּלָאכוֹת וְהַשִּׁמּוּשִׁים, "עֹבֵד אַדְמָתוֹ יִשְׂבַּע לָחֶם" (משלי יב יא), "וַעֲבָדְךָ שֵׁשׁ שָׁנִים" (דברים טו יח), "וְעָבַדְתָּ אֶת אוֹיְבֶיךָ" (שם כח מח), וְאֵינוֹ מְשַׁמֵּשׁ בְּשׁוּם מָקוֹם בְּדָבָר הָאָבֵד בִּלְבַד, שֶׁאִם לֹא תַעֲשֶׂה הַיּוֹם לֹא תַעֲשֶׂה לְמָחָר. אֲבָל פֵּרוּשׁ "מְלֶאכֶת עֲבוֹדָה", כָּל מְלָאכָה שֶׁאֵינָהּ לְצֹרֶךְ אֹכֶל נֶפֶשׁ, כְּעִנְיָן שֶׁנֶּאֱמַר "שֵׁשֶׁת יָמִים תַּעֲבֹד וְעָשִׂיתָ כָל מְלַאכְתֶּךָ" (שמות כ ט), "וּבְכָל עֲבוֹדָה בַּשָּׂדֶה" (שם א יד), "וְנֶעֱבַדְתֶּם וְנִזְרַעְתֶּם" (יחזקאל לו ט), "וְקַיִן הָיָה עֹבֵד אֲדָמָה" (בראשית ד ב). וּמְלָאכָה שֶׁהִיא בְּאֹכֶל נֶפֶשׁ הִיא מְלֶאכֶת הֲנָאָה, לֹא מְלֶאכֶת עֲבוֹדָה, וְזֶה מִתְבָּאֵר בַּתּוֹרָה, כִּי בְּחַג הַמַּצּוֹת שֶׁאָמַר תְּחִלָּה "כָּל מְלָאכָה לֹא יֵעָשֶׂה בָהֶם" (שמות יב טז), הֻצְרַךְ לְפָרֵשׁ "אַךְ אֲשֶׁר יֵאָכֵל לְכָל נֶפֶשׁ הוּא לְבַדּוֹ יֵעָשֶׂה לָכֶם", וּבִשְׁאָר כָּל יָמִים טוֹבִים יְקַצֵּר וְיֹאמַר "כָּל מְלֶאכֶת עֲבֹדָה לֹא תַעֲשׂוּ", לֶאֱסֹר כָּל מְלָאכָה שֶׁאֵינֶנָּה אֹכֶל נֶפֶשׁ, וּלְהוֹדִיעַ שֶׁאֹכֶל נֶפֶשׁ מֻתָּר בָּהֶן. וְלֹא יֹאמַר הַכָּתוּב לְעוֹלָם בְּאֶחָד מִכָּל שְׁאָר יָמִים טוֹבִים "כָּל מְלָאכָה", וְלֹא יְפָרֵשׁ בָּהֶם הֶתֵּר אֹכֶל נֶפֶשׁ, כִּי "מְלֶאכֶת עֲבוֹדָה" יְלַמֵּד עַל זֶה. אֲבָל בְּפָרָשַׁת כָּל הַבְּכוֹר (דברים טז ח) בְּחַג הַמַּצּוֹת אָמַר "וּבַיּוֹם הַשְּׁבִיעִי עֲצֶרֶת לַה' אֱלֹהֶיךָ לֹא תַעֲשֶׂה מְלָאכָה", וְהַטַּעַם מִפְּנֵי שֶׁכְּבָר הִתִּיר בּוֹ בְּפֵרוּשׁ אֹכֶל נֶפֶשׁ וְלֹא הֻצְרַךְ לֵאמֹר בּוֹ "כָּל מְלֶאכֶת עֲבוֹדָה", וְהִזְכִּיר "מְלָאכָה" סְתָם וְלֹא אָמַר "כָּל מְלָאכָה" כְּמוֹ שֶׁנֶּאֱמַר בְּשַׁבָּת (ויקרא כ"ג:ג') וְיוֹם הַכִּפּוּרִים (ויקרא כ"ג:כ"ח), כִּי הַכַּוָּנָה לֹא תַעֲשֶׂה מְלָאכָה אֲשֶׁר הִזְהַרְתִּיךָ עָלֶיהָ. וְכָתַב רַבֵּנוּ חֲנַנְאֵל, "כָּל מְלֶאכֶת עֲבוֹדָה", מַגִּיד שֶׁאֵינוֹ מַתִּיר אֶלָּא בִּמְלֶאכֶת אֹכֶל נֶפֶשׁ, כְּדִכְתִיב בָּעִנְיָן הַזֶּה בְּמָקוֹם אַחֵר "וּבַיּוֹם הָרִאשׁוֹן מִקְרָא קֹדֶשׁ יִהְיֶה לָכֶם כָּל מְלָאכָה לֹא יֵעָשֶׂה בָהֶם", וּמִפְּנֵי שֶׁמַּזְכִּיר שָׁם "כָּל מְלָאכָה" הֻצְרַךְ לְפָרֵשׁ "אַךְ אֲשֶׁר יֵאָכֵל לְכָל נֶפֶשׁ הוּא לְבַדּוֹ יֵעָשֶׂה לָכֶם", פֵּרוּשׁ "מְלֶאכֶת עֲבוֹדָה" מְלָאכָה הַמִּשְׁתַּמֶּרֶת לַעֲבוֹדַת קִנְיָן, כְּגוֹן זְרִיעָה וּקְצִירָה וַחֲפִירָה וְכַיּוֹצֵא בָּהֶם, אֲבָל אֹכֶל נֶפֶשׁ אֵינָהּ מְלֶאכֶת עֲבוֹדָה, זֶה לְשׁוֹנוֹ. וְהַבָּרַיְתָא שֶׁבְּת"כ (פרשה יב ה-ח) כָּךְ הִיא שְׁנוּיָה בַּנֻּסְחָאוֹת הַמְּדֻקְדָּקוֹת, "כָּל מְלָאכָה לֹא תַעֲשׂוּ", הֲרֵי זֶה בָּא לְלַמֵּד עַל יְמֵי מוֹעֵד שֶׁהֵן אֲסוּרִין בִּמְלָאכָה, יָכוֹל יְהוּ אֲסוּרִין בְּכָל מְלֶאכֶת עֲבוֹדָה, תַּלְמוּד לוֹמַר "הוּא", הוּא אָסוּר בְּכָל מְלֶאכֶת עֲבוֹדָה וְאֵין יְמֵי מוֹעֵד אֲסוּרִין בְּכָל מְלֶאכֶת עֲבוֹדָה, דִּבְרֵי רַבִּי יוֹסֵי הַגְּלִילִי. רַבִּי עֲקִיבָא אוֹמֵר, מַה תַּלְמוּד לוֹמַר "אֵלֶּה מוֹעֲדֵי ה' אֲשֶׁר תִּקְרְאוּ אֹתָם מִקְרָאֵי קֹדֶשׁ" (ויקרא כ"ג:ל"ז), אִם לְעִנְיַן יָמִים טוֹבִים הֲרֵי כְּבָר יָמִים טוֹבִים אֲמוּרִים, א"כ לָמָּה נֶאֱמַר "אֵלֶּה מוֹעֲדֵי ה' אֲשֶׁר תִּקְרְאוּ אֹתָם מִקְרָאֵי קֹדֶשׁ", אֵלּוּ יְמֵי מוֹעֵד שֶׁהֵן אֲסוּרִין בַּעֲשִׂיַּת מְלָאכָה, יָכוֹל יְהוּ אֲסוּרִין בְּכָל מְלֶאכֶת עֲבוֹדָה, תַּלְמוּד לוֹמַר "הוּא" וְכוּ'. וּפֵרוּשָׁהּ, שֶׁר' יוֹסֵי הַגְּלִילִי דּוֹרֵשׁ "לֹא תַעֲשׂוּ. אֵלֶּה מוֹעֲדֵי ה'" (להלן פסוקים לו לז), לוֹמַר שֶׁהַכָּתוּב אוֹסֵר עֲשִׂיָּה בְּמוֹעֲדֵי ה' כֻּלָּם, יָכוֹל שֶׁיְּהוּ כֻּלָּן שָׁוִין בְּאִסּוּר וְיֵאָסְרוּ בְּכָל מְלֶאכֶת עֲבוֹדָה כְּרִאשׁוֹן וּשְׁמִינִי, וְנִדְרֹשׁ "כָּל מְלֶאכֶת עֲבֹדָה לֹא תַעֲשׂוּ. אֵלֶּה מוֹעֲדֵי ה'", שֶׁהַמִּקְרָא נִדְרָשׁ לְפָנָיו וְלִפְנֵי פָנָיו, מִעֵט הַכָּתוּב "עֲצֶרֶת הִיא כָּל מְלֶאכֶת עֲבֹדָה לֹא תַעֲשׂוּ" (ויקרא כ"ג:ל"ו), שְׁמִינִי עָצוּר בְּכָל מְלֶאכֶת עֲבוֹדָה וְאֵין חֻלּוֹ שֶׁל מוֹעֵד אָסוּר כָּמוֹהוּ בְּכָל מְלֶאכֶת עֲבוֹדָה אֶלָּא בִּמְלָאכָה בִּלְבַד, שֶׁאָמַר "לֹא תַעֲשׂוּ", וְלֹא הִזְכִּירָהּ הַכָּתוּב וְלֹא רָמַז לָהּ כְּלָל וּמְסָרָהּ לַחֲכָמִים. וּלְפִי גִּרְסַת רַשִׁ"י ג"כ כָּךְ הִיא מִתְפָּרֶשֶׁת. וְהַבָּרַיְתָא הַזּוֹ הִיא שְׁנוּיָה בִּגְמָרָא חֲגִיגָה (יח), דְּקָתָנֵי, "כָּל מְלֶאכֶת עֲבֹדָה לֹא תַעֲשׂוּ", לִמֵּד עַל חֻלּוֹ שֶׁל מוֹעֵד שֶׁאָסוּר בַּעֲשִׂיַּת מְלָאכָה, דִּבְרֵי רַבִּי יוֹסֵי הַגְּלִילִי. רַבִּי עֲקִיבָא אוֹמֵר וְכוּ'. וְשָׁם שָׁנוּ עוֹד, מַה שְׁבִיעִי אָסוּר אַף שִׁשִּׁי אָסוּר, אִי מָה שְׁבִיעִי עָצוּר בְּכָל מְלָאכָה אַף שִׁשִּׁי עָצוּר בְּכָל מְלָאכָה, תַּלְמוּד לוֹמַר "הַשְּׁבִיעִי", שְׁבִיעִי עָצוּר בְּכָל מְלָאכָה וְאֵין הַשִּׁשִּׁי עָצוּר בְּכָל מְלָאכָה, שֶׁלֹּא מְסָרָן הַכָּתוּב אֶלָּא לַחֲכָמִים וְכוּ'. שָׁנוּ בַּגְּמָרָא בְּ"כָל מְלָאכָה" וְשָׁנוּ בְּת"כ בְּ"כָל מְלֶאכֶת עֲבוֹדָה" שֶׁתָּפְסוּ לָהֶם בַּמִּדְרָשׁ לְשׁוֹן הַכָּתוּב שֶׁאֵין לוֹמַר בְּיוֹם טוֹב בְּ"כָל מְלָאכָה" אֶלָּא בְּ"כָל מְלֶאכֶת עֲבוֹדָה" וּשְׁנֵיהֶם לְדָבָר אֶחָד נִתְכַּוְּנוּ שְׁיו"ט אָסוּר בְּכָל מְלֶאכֶת עֲבוֹדָה וְחוֹלוֹ שֶׁל מוֹעֵד אֵינוֹ אָסוּר בְּכָל מְלֶאכֶת עֲבוֹדָה, אֲבָל אָסוּר הוּא בְּכָל מְלָאכָה שֶׁלֹּא נִתְפָּרְשָׁה בַּתּוֹרָה וּמְסָרָהּ הַכָּתוּב לַחֲכָמִים. וּבְסִפְרֵי (ראה קלה), רַבִּי יִשְׁמָעֵאל אוֹמֵר, לְפִי שֶׁלֹּא לָמַדְנוּ שֶׁיְּמֵי מוֹעֵד אֲסוּרִין בִּמְלָאכָה, תַּלְמוּד לוֹמַר "שֵׁשֶׁת יָמִים תֹּאכַל מַצּוֹת וּבַיּוֹם הַשְּׁבִיעִי עֲצֶרֶת" (דברים טז ח), מָה שְׁבִיעִי עָצוּר אַף שִׁשִּׁי עָצוּר. אִי מָה שְׁבִיעִי עָצוּר בְּכָל מְלָאכָה אַף שִׁשִּׁי עָצוּר בְּכָל מְלָאכָה, תַּלְמוּד לוֹמַר "הַשְּׁבִיעִי", שְׁבִיעִי עָצוּר בְּכָל מְלָאכָה וְאֵין הַשִּׁשִּׁי עָצוּר בְּכָל מְלָאכָה. וְגַם זוֹ כְּפִי הַשִּׁיטָה שֶׁאָמַרְנוּ. הֲרֵי הֶאֱרַכְנוּ בְּעִנְיְנֵי הַבָּרָיְתוֹת הַשְּׁנוּיוֹת בָּעִנְיָן הַזֶּה לְהַעֲלוֹת דִּבְרֵי רז"ל עִם הַפֵּרוּשׁ הַבָּרוּר וְהַנָּכוֹן מַה שֶׁאָמַרְנוּ בַּכְּתוּבִים הָאֵלּוּ. וְעִם כָּל זֶה מָצָאתִי קֻשְׁיָא עַל דְּבָרֵינוּ מִבָּרַיְתָא הַשְּׁנוּיָה בְּסִפְרֵי (פנחס קמז), "כָּל מְלֶאכֶת עֲבֹדָה לֹא תַעֲשׂוּ" (במדבר כח יח), מַגִּיד שֶׁאָסוּר בַּעֲשִׂיַּת מְלָאכָה. מִנַּיִן לְהַתִּיר בּוֹ אֹכֶל נֶפֶשׁ, נֶאֱמַר כָּאן "מִקְרָא קֹדֶשׁ" וְנֹאמַר לְהַלָּן "מִקְרָא קֹדֶשׁ" (שמות יב טז), מַה לְהַלָּן לְהַתִּיר בּוֹ אֹכֶל נֶפֶשׁ אַף כָּאן לְהַתִּיר בּוֹ אֹכֶל נֶפֶשׁ. וְנִרְאֶה לִי כִּי "עֲבוֹדָה" אֵצֶל רַבּוֹתֵינוּ זַ"ל טֹרַח וְעָמָל שֶׁאָדָם עוֹבֵד בּוֹ לְאַחֵר, מִלְּשׁוֹן "עֲבוֹדַת עָבֶד" (ויקרא כה לט), "עֶבֶד עֲבָדִים יִהְיֶה לְאֶחָיו" (בראשית ט כה), "עָבְדוּ אֶת כְּדָרְלָעֹמֶר" (שם יד ד), וְכֵן "עֲבֹדַת עֲבֹדָה וַעֲבֹדַת מַשָּׂא" (במדבר ד מז), עֲבוֹדַת כָּל טֹרַח שֶׁבָּאֹהֶל וַעֲבוֹדַת מַשָּׂא בַּכָּתֵף. וְאִם כֵּן הָיָה בְּאֶפְשָׁר שֶׁמְּלָאכוֹת קַלּוֹת שֶׁאָדָם עוֹשֶׂה לַהֲנָאַת עַצְמוֹ מֻתֶּרֶת וְאע"פ שֶׁאֵינָהּ אֹכֶל נֶפֶשׁ, וְשֶׁיִּהְיֶה אֹכֶל נֶפֶשׁ מְרֻבֶּה שֶׁהַשַּׁמָּשׁ עוֹבֵד בּוֹ לְרַבּוֹ אָסוּר. וְעַל כֵּן שָׁאַל מִנַּיִן שֶׁהַהֶתֵּר הַזֶּה הוּא בְּאֹכֶל נֶפֶשׁ עַד שֶׁנַּתִּיר כָּל אֹכֶל נֶפֶשׁ אֲפִלּוּ בְּטֹרַח, וְנֶאֱסֹר כָּל שְׁאָר הַמְּלָאכוֹת שֶׁאֲפִלּוּ הַקַּלּוֹת שֶׁבָּהֶם מְלֶאכֶת עֲבוֹדָה אִקְּרוּ, תַּלְמוּד לוֹמַר "מִקְרָא קֹדֶשׁ" לִגְזֵרָה שָׁוָה, שֶׁשָּׁם בָּאָה כָּל מְלָאכָה לְאִסּוּר וְכָל אֹכֶל נֶפֶשׁ לְהַתִּיר. וְרָאִיתִי בַּמְּכִילְתָּא (בא ט) דְּתָנֵי, "אַךְ אֲשֶׁר יֵאָכֵל לְכָל נֶפֶשׁ" (שמות יב טז), כָּל אֹכֶל נֶפֶשׁ דּוֹחֶה י"ט וְאֵין כָּל עֲבוֹדָה דּוֹחָה י"ט. וִיהֵא מִקְצָת אֹכֶל נֶפֶשׁ דּוֹחֶה שַׁבָּת, וְהַדִּין נוֹתֵן, וּמָה אִם בְּמָקוֹם שֶׁאֵין כָּל עֲבוֹדָה דּוֹחָה י"ט כָּל אֹכֶל נֶפֶשׁ דּוֹחֶה י"ט, מָקוֹם שֶׁמִּקְצָת עֲבוֹדָה דּוֹחָה שַׁבָּת אֵינוֹ דִּין שֶׁיְּהֵא מִקְצָת אֹכֶל נֶפֶשׁ דּוֹחֶה אֶת הַשַּׁבָּת, תַּלְמוּד לוֹמַר "אֲשֶׁר יֵאָכֵל לְכָל נֶפֶשׁ", מִקְצָת עֲבוֹדָה דּוֹחָה אֶת הַשַּׁבָּת וְאֵין מִקְצָת אֹכֶל נֶפֶשׁ דּוֹחֶה אֶת הַשַּׁבָּת. וּפֵרוּשׁ מִקְצָת עֲבוֹדָה, כְּגוֹן חוֹבַת הַיּוֹם, תְּמִידִין וּמוּסָפִין, וְאֵין כָּל עֲבוֹדָה דּוֹחָה י"ט, נְדָרִים וּנְדָבוֹת אוֹ עוֹלַת נְדָבָה, אֲבָל מִקְצָת אֹכֶל נֶפֶשׁ לֹא נִתְבָּרֵר לִי פֵּרוּשׁוֹ, אֶלָּא שֶׁיִּרְמֹז לְמָה שֶׁאָמַרְנוּ, שֶׁהַבָּא בְּטֹרַח גָּדוֹל בְּדוֹמֶה לַעֲבוֹדָה יִהְיֶה בִּכְלַל אִסּוּר, וְהַבָּא בְּנָקֵל כְּמִנְהָגוֹ שֶׁל אָדָם לְעַצְמוֹ יִהְיֶה מֻתָּר, אוֹ מִקְצָתוֹ כְּדֵי חַיָּיו וְכֻלּוֹ תַּבְשִׁילִין מְרֻבִּין לְתַעֲנוּג. וְהַכְּלָל בִּ"מְלֶאכֶת עֲבוֹדָה" שֶׁהוּא לְהַתִּיר אֹכֶל נֶפֶשׁ:
@65 **וְהִקְרַבְתֶּם אִשֶּׁה לַה' שִׁבְעַת יָמִים** יֹאמַר שֶׁיִּהְיוּ כָּל שִׁבְעַת הַיָּמִים חַג לְהַקְרִיב אִשֶּׁה לַה', לֹא לְהֵאָסֵר בִּמְלָאכָה כְּרִאשׁוֹן וּשְׁבִיעִי. וְלֹא פֵּרֵשׁ הָאִשֶּׁה כִּי הוּא עָתִיד לְהַזְכִּירוֹ בְּפָרָשָׁה מְיֻחֶדֶת לְכָל אִשֵּׁי הַמּוֹעֲדִים (סוף פרשת פנחס), כַּאֲשֶׁר רָצָה שֶׁיִּנְהֲגוּ בָּהֶן וּכְפִי מַה שֶׁפֵּרַשְׁתִּי (רמב"ן על ויקרא כ"ג:ב'). וּמִדְרַשׁ רַבּוֹתֵינוּ (תו"כ פרק יא ה) לוֹמַר שֶׁנַּקְרִיב בָּהֶן אִשֶּׁה מִכָּל מָקוֹם, אע"פ שֶׁאֵין לָנוּ כָּל הַמּוּסָפִין שְׁלֵמִים. וְנָכוֹן הוּא:
@67 **דַּבֵּר אֶל בְּנֵי יִשְׂרָאֵל וְאָמַרְתָּ אֲלֵהֶם כִּי תָבֹאוּ אֶל הָאָרֶץ** בַּעֲבוּר שֶׁיְּחַדֵּשׁ בְּכָאן בְּכָל אֶחָד מִן הַמּוֹעֲדִים מִצְוָה חֲדָשָׁה מִלְּבַד הַשַּׁבָּתוֹן וְהַמִּקְרָא קֹדֶשׁ, תִּתְיַחֵד בְּכָל מוֹעֵד פָּרָשָׁה בִּפְנֵי עַצְמָהּ שֶׁיַּזְהִיר בָּהּ "דַּבֵּר אֶל בְּנֵי יִשְׂרָאֵל". וּמִפְּנֵי שֶׁחַג הַשָּׁבוּעוֹת זְמַנּוֹ תָּלוּי בָּעֹמֶר, אָמַר הַכֹּל בְּפָרָשָׁה אַחַת. וּבַעֲבוּר שֶׁיּוֹם הַזִּכָּרוֹן וְיוֹם הַכִּפּוּרִים בְּחֹדֶשׁ אֶחָד וּשְׁנֵיהֶם מֵעִנְיָן אֶחָד, בְּדִין הָעֲוֹנוֹת וְכַפָּרָתָם לַשָּׁבִים, לֹא אָמַר בְּיוֹם הַכִּפּוּרִים "דַּבֵּר אֶל בְּנֵי יִשְׂרָאֵל", כִּי יַסְפִּיק לוֹ בַּדִּבּוּר הָרִאשׁוֹן, וְעָשָׂה מֵהֶן שְׁתֵּי פָּרָשִׁיּוֹת שֶׁהֵם עִנְיָנִים שׁוֹנִים:
@67 וְטַעַם **וּקְצַרְתֶּם אֶת קְצִירָהּ** שֶׁלֹּא תִּקְצְרוּ בָּאָרֶץ קָצִיר עַד שֶׁתִּקְצְרוּ הָעֹמֶר וְתָבִיאוּ אוֹתוֹ רֵאשִׁית קְצִירְכֶם אֶל הַכֹּהֵן. וְכֵן "מֵהָחֵל חֶרְמֵשׁ בַּקָּמָה תָּחֵל לִסְפֹּר" (דברים טז ט), מֵהָחֵל לְךָ חֶרְמֵשׁ בְּשׁוּם קָמָה, כִּי אָסוּר לְהָנִיף חֶרְמֵשׁ עַל הַקָּמָה עַד יוֹם שֶׁתָּחֵל לִסְפֹּר:
@68 **מִמָּחֳרַת הַשַּׁבָּת יְנִיפֶנּוּ הַכֹּהֵן** מִמָּחֳרַת יוֹם טוֹב הָרִאשׁוֹן שֶׁל פֶּסַח, שֶׁאִם אַתָּה אוֹמֵר שַׁבַּת בְּרֵאשִׁית אֵי אַתָּה יוֹדֵעַ אֵיזֶהוּ, לְשׁוֹן רַשִׁ"י (רש"י על ויקרא כ"ג:י"א). וּבֶאֱמֶת שֶׁזּוֹ גְּדוֹלָה שֶׁבָּרְאָיוֹת בַּגְּמָרָא, כִּי מָה טַעַם שֶׁיֹּאמַר הַכָּתוּב, כִּי תָבֹאוּ אֶל הָאָרֶץ וּקְצַרְתֶּם אֶת קְצִירָהּ תָּבִיאוּ הָעֹמֶר מִמָּחֳרַת שַׁבַּת בְּרֵאשִׁית, כִּי יֵשׁ בַּמַּשְׁמָע שֶׁבְּאֵיזֶה זְמַן מִן הַשָּׁנָה שֶׁנָּבוֹא לָאָרֶץ וְנִקְצֹר קְצִירָהּ יָנִיף הַכֹּהֵן הָעֹמֶר מִמָּחֳרַת הַשַּׁבָּת הָרִאשׁוֹנָה שֶׁתִּהְיֶה אַחֲרֵי בִּיאָתֵנוּ לָאָרֶץ, וְהִנֵּה אֵין לְחַג הַשָּׁבוּעוֹת זְמַן שֶׁיִּמָּנֶה מִמֶּנּוּ. וְעוֹד עַל דֶּרֶךְ הַזֶּה לֹא נֵדַע בַּשָּׁנִים הַבָּאוֹת אַחֲרֵי כֵן מָתַי נָחֵל לִסְפֹּר, רַק מִיּוֹם הָחֵל חֶרְמֵשׁ בַּקָּמָה כְּפִי רְצוֹנֵנוּ, וְאֵלֶּה דִּבְרֵי תֹּהוּ. אֲבָל אִם יִהְיֶה "מִמָּחֳרַת הַשַּׁבָּת" יוֹם טוֹב כְּפִי קַבָּלַת רַבּוֹתֵינוּ, יָבוֹא הָעִנְיָן כַּהֹגֶן, כִּי צִוָּה הַכָּתוּב תְּחִלָּה (ויקרא כ"ג:ו'-ח') שֶׁנַּעֲשֶׂה בַּחֹדֶשׁ הָרִאשׁוֹן חַג הַמַּצּוֹת שִׁבְעַת יָמִים, וּבַיּוֹם הָרִאשׁוֹן שַׁבָּתוֹן וּבַיּוֹם הַשְּׁבִיעִי שַׁבָּתוֹן וְכָל מְלֶאכֶת עֲבוֹדָה לֹא נַעֲשֶׂה, וְאַחַר כֵּן אָמַר (ויקרא כ"ג:ט'-י"א) כִּי כַּאֲשֶׁר נָבוֹא אֶל הָאָרֶץ נָבִיא מִמָּחֳרַת הַשַּׁבָּת הַזֹּאת הַנִּזְכֶּרֶת עֹמֶר הַתְּנוּפָה, וְהִיא הַשַּׁבָּת הָרִאשׁוֹנָה הַנִּזְכֶּרֶת כָּאן, וְלִמֵּד שֶׁלֹּא יִנְהַג הָעֹמֶר בַּמִּדְבָּר וּבְחוּצָה לָאָרֶץ. אֲבָל "מִמָּחֳרַת הַשַּׁבָּת הַשְּׁבִיעִית" (ויקרא כ"ג:ט"ז) וְ"שֶׁבַע שַׁבָּתוֹת" (ויקרא כ"ג:ט"ו) לֹא יִתָּכֵן לְפָרֵשׁ אוֹתָם יוֹם טוֹב, אֲבָל תִּרְגֵּם בּוֹ אוּנְקְלוֹס לְשׁוֹן שָׁבוּעַ, וְא"כ יִהְיוּ שְׁתֵּי לְשׁוֹנוֹת בְּפָסוּק אֶחָד. וְהַמְּפָרְשִׁים אָמְרוּ כִּי הוּא דֶּרֶךְ צַחוֹת, כְּמוֹ "רֹכְבִים עַל שְׁלֹשִׁים עֲיָרִים וּשְׁלֹשִׁים עֲיָרִים לָהֶם" (שופטים י ד), וּבְמָקוֹם אַחֵר (דברים טז ט) פֵּרֵשׁ "שִׁבְעָה שָׁבוּעוֹת", וְכֵן "בָּאֵי הַשַּׁבָּת עִם יוֹצְאֵי הַשַּׁבָּת" (מלכים ב יא ט), שָׁבוּעַ, וְכֵן "מָתַי יַעֲבֹר הַחֹדֶשׁ וְנַשְׁבִּירָה שֶּׁבֶר וְהַשַּׁבָּת וְנִפְתְּחָה בָּר" (עמוס ח ה), כִּי בַּעֲבוּר שֶׁיֵּשׁ בְּכָל שִׁבְעָה יָמִים שַׁבָּת אַחַת, וְחֶשְׁבּוֹן הַיָּמִים מִמֶּנּוּ, יִקָּרֵא שָׁבוּעַ אֶחָד - שַׁבָּת אֶחָד, וְהוּא לָשׁוֹן יָדוּעַ וּמֻרְגָּל בְּדִבְרֵי רַבּוֹתֵינוּ, שֶׁפַּעֲמַיִם בַּשַּׁבָּת ב"ד יוֹשְׁבִין בָּעֲיָרוֹת (כתובות ב). וְיִתָּכֵן שֶׁיִּהְיֶה כָּל "הַשַּׁבָּת" הַנִּזְכָּר בַּפָּרָשָׁה - שָׁבוּעַ, וְיִהְיֶה טַעַם "מִמָּחֳרַת הַשַּׁבָּת" לוֹמַר כִּי בְּיוֹם הֲנָפַת הָעֹמֶר יַתְחִיל לַעֲשׂוֹת הַשָּׁבוּעַ בְּמִנְיָנוֹ, אִם כֵּן יִהְיֶה הַיּוֹם הַהוּא מִמָּחֳרַת הַשָּׁבוּעַ שֶׁעָבַר, כְּאִלּוּ אָמַר יִהְיֶה יוֹם הַתְּנוּפָה מִמָּחֳרַת שָׁבוּעַ לַיָּמִים הָעוֹבְרִים, וְרִאשׁוֹן לַשָּׁבוּעוֹת שֶׁיִּסְפֹּר עַד שֶׁיַּשְׁלִים שֶׁבַע שַׁבָּתוֹת. וּבַעֲבוּר שֶׁהִזְכִּיר (ויקרא כ"ג:ו') "וּבַחֲמִשָּׁה עָשָׂר יוֹם" אָמַר שֶׁיָּנִיף אֶת הָעֹמֶר מִמָּחֳרַת הַשָּׁבוּעַ הַנִּזְכָּר וְיִסְפֹּר מִמֶּנּוּ שֶׁבַע שַׁבָּתוֹת. וְאֵין לִטְעוֹת בְּיוֹם אַרְבָּעָה עָשָׂר, כִּי לֹא הִזְכִּיר מִמֶּנּוּ רַק "בֵּין הָעַרְבָּיִם" (ויקרא כ"ג:ה'). וְטַעַם "תְּמִימוֹת תִּהְיֶינָה" (ויקרא כ"ג:ט"ו), כִּי הַשַּׁבָּת עִם שֵׁשֶׁת הַיָּמִים תִּקָּרֵא שַׁבָּת שְׁלֵמָה. וּפֵרוּשׁ "מִמָּחֳרַת הַשַּׁבָּת" כְּמוֹ בְּמָחֳרַת הַשַּׁבָּת, וְכֵן "עַד מִמָּחֳרַת הַשַּׁבָּת הַשְּׁבִיעִת תִּסְפְּרוּ" (ויקרא כ"ג:ט"ז), וְכֵן "בְּיוֹם (ההוא) זִבְחֲכֶם יֵאָכֵל וּמִמָּחֳרָת" (ויקרא י"ט:ו'). וְאָמְרוּ כִּי לֹא יָבֹא בֵּי"ת בְּמִלַּת מָחָר וּמָחֳרָת, "וַיְהִי מִמָּחֳרָת וַיֵּשֶׁב מֹשֶׁה לִשְׁפֹּט אֶת הָעָם" (שמות יח יג), "וַיַּעַשׂ ה' אֶת הַדָּבָר הַזֶּה מִמָּחֳרָת" (שם ט ו), וְכֵן כֻּלָּם:
@72 וְטַעַם **וּסְפַרְתֶּם לָכֶם** כְּמוֹ "וּלְקַחְתֶּם לָכֶם" (ויקרא כ"ג:מ'), שֶׁתְּהֵא סְפִירָה וּלְקִיחָה לְכָל אֶחָד וְאֶחָד שֶׁיִּמְנֶה בְּפִיו וְיַזְכִּיר חֶשְׁבּוֹנוֹ כַּאֲשֶׁר קִבְּלוּ רַבּוֹתֵינוּ. וְאֵין כֵּן "וְסָפַר לוֹ" (ויקרא ט"ו:י"ג) "וְסָפְרָה לָּהּ" (שם פסוק כח) דְּזָבִין, שֶׁהֲרֵי אִם רָצוּ עוֹמְדִים בְּטֻמְאָתָם, אֶלָּא שֶׁלֹּא יִשְׁכָּחוּהוּ. וְכֵן "וְסָפַרְתָּ לְךָ" (ויקרא כ"ה:ח') דְּיוֹבֵל, שֶׁתִּזָּהֵר בַּמִּסְפָּר שֶׁלֹּא תִּשְׁכַּח. וּבְת"כ (בהר פרשה ב א), "וְסָפַרְתָּ לְךָ" - בְּב"ד. וְלֹא יָדַעְתִּי אִם לוֹמַר שֶׁיִּהְיוּ ב"ד הַגָּדוֹל חַיָּבִין לִסְפֹּר שָׁנִים וְשָׁבוּעוֹת בְּרֹאשׁ כָּל שָׁנָה וּלְבָרֵךְ עֲלֵיהֶן, כְּמוֹ שֶׁנַּעֲשֶׂה בִּסְפִירַת הָעֹמֶר, אוֹ לוֹמַר שֶׁיִּזָּהֲרוּ ב"ד בַּמִּנְיָן וִיקַדְּשׁוּ שְׁנַת הַחֲמִשִּׁים. וְהִנֵּה מִסְפַּר הַיָּמִים מִיּוֹם הַתְּנוּפָה עַד יוֹם מִקְרָא קֹדֶשׁ כְּמִסְפַּר הַשָּׁנִים מִשְּׁנוֹת הַשְּׁמִטָּה עַד הַיּוֹבֵל, וְהַטַּעַם בָּהֶם אֶחָד, עַל כֵּן "תִּסְפְּרוּ חֲמִשִּׁים יוֹם", שֶׁיִּסְפֹּר שֶׁבַע שַׁבָּתוֹת תֵּשַׁע וְאַרְבָּעִים יוֹם וִיקַדֵּשׁ יוֹם הַחֲמִשִּׁים הַנִּסְפָּר בְּיָדוֹ, כְּמוֹ שֶׁאָמַר בַּיּוֹבֵל. וְזֶה טַעַם "תְּמִימוֹת", שֶׁתִּהְיֶינָה מְכֻוָּנוֹת, לֹא פָּחוֹת וְלֹא יוֹתֵר, כְּטַעַם "תְּמִימִים יִהְיוּ" (במדבר כח יט), שֶׁהַיָּתֵר כְּמוֹ הֶחָסֵר אֵינֶנּוּ תָּמִים. וְהִנֵּה טַעַם הַפָּרָשָׁה שֶׁיַּתְחִיל לִסְפֹּר בִּתְחִלַּת קְצִיר שְׂעוֹרִים וְיָבִיא רֵאשִׁית קְצִירוֹ כַּרְמֶל מִנְחָה לַשֵּׁם וְיַקְרִיב עָלָיו קָרְבָּן, וְיַשְׁלִים מִסְפָּרוֹ בִּתְחִלַּת קְצִיר חִטִּים כַּעֲלוֹת גָּדִישׁ בְּעִתּוֹ וְיָבִיא מִמֶּנּוּ סֹלֶת חִטִּים מִנְחָה לַשֵּׁם (ויקרא כ"ג:ט"ז-י"ז) וְיָבִיא קָרְבָּן עָלָיו (שם יח-כ). וּלְכָךְ הִזְכִּיר הַקָּרְבָּנוֹת הָאֵלֶּה בַּפָּרָשָׁה כִּי הֵם בִּגְלַל הַמְּנָחוֹת שֶׁהֵם הָעִקָּר בֶּחָג הַזֶּה, וְלֹא הִזְכִּיר הַמּוּסָפִין בָּהֶן כַּאֲשֶׁר לֹא הִזְכִּירָם בִּשְׁאָר הַמּוֹעֲדִים:
@73 וְטַעַם **מִנְחָה חֲדָשָׁה** שֶׁלֹּא יוּבָא בֵּית ה' מִנְחָה עַד שֶׁיָּבִיאוּ זֹאת, כְּמוֹ שֶׁפֵּרְשׁוּ רַבּוֹתֵינוּ (מנחות פג). וְהֻצְרַךְ לוֹמַר "חֻקַּת עוֹלָם לְדֹרֹתֵיכֶם בְּכֹל מֹשְׁבֹתֵיכֶם" בְּאִסּוּר הֶחָדָשׁ (ויקרא כ"ג:י"ד) וּבִשְׁבִיתַת חַג הַשָּׁבוּעוֹת (ויקרא כ"ג:כ"א), מִפְּנֵי שֶׁהוּא תָּלוּי בַּהֲנָפַת הָעֹמֶר וּבְמִנְחָה חֲדָשָׁה, לוֹמַר שֶׁאֲפִלּוּ אַחֲרֵי גָּלוּתֵנוּ בְּחוּצָה לָאָרֶץ שֶׁאֵין עֹמֶר וּמִנְחָה יְצַוֶּה בָּהֶם, כִּי הֶחָדָשׁ אָסוּר מִן הַתּוֹרָה בְּכָל מָקוֹם. וְלֹא הֻצְרַךְ לְהַזְכִּיר כֵּן בְּיוֹם הַזִּכָּרוֹן, וְכֵן בְּחַג הַסֻּכּוֹת (ויקרא כ"ג:מ"א) לֹא הִזְכִּיר "בְּכָל מוֹשְׁבוֹתֵיכֶם", וְהִזְכִּיר כֵּן בְּיוֹם הַכִּפּוּרִים (ויקרא כ"ג:ל"א), כִּי בַּעֲבוּר שֶׁתָּלָה כַּפָּרָתֵנוּ בַּקָּרְבָּנוֹת כַּאֲשֶׁר הִזְכִּיר בְּפָרָשַׁת אַחֲרֵי מוֹת, אָמַר בְּכָאן כִּי אִסּוּרוֹ נוֹהֵג בְּכָל מָקוֹם, כִּי יוֹם כִּפֻּרִים הוּא לְכַפֵּר עֲלֵיכֶם בְּעִנּוּי וּבִשְׁבִיתַת הַמְּלָאכָה, וְאֵין הַקָּרְבָּנוֹת מְעַכְּבִין כַּפָּרָה מִמֶּנּוּ. וְכֵן לֹא הֻזְכַּר בְּכָאן בְּחַג הַמַּצּוֹת "חֻקַּת עוֹלָם בְּכָל מוֹשְׁבֹתֵיכֶם לְדֹרֹתֵיכֶם", אֲבָל בְּפָרָשַׁת "הַחֹדֶשׁ הַזֶּה לָכֶם" (שמות י"ב:ב' פסוקים יד יז כ) הִזְכִּיר כֵּן, מִפְּנֵי שֶׁתָּלָה שָׁם הַדָּבָר בַּפֶּסַח, "עַל מַצּוֹת וּמְרֹרִים יֹאכְלֻהוּ" (שם יב ח), הֻצְרַךְ לוֹמַר שֶׁיִּהְיֶה "חֻקַּת עוֹלָם בְּכָל מוֹשְׁבֹתֵיכֶם". וְהִזְכִּיר בְּשַׁבָּת "בְּכֹל מוֹשְׁבֹתֵיכֶם" (ויקרא כ"ג:ג'), וְהַטַּעַם מִפְּנֵי שֶׁהֻתְּרָה מְלָאכָה בַּמִּקְדָּשׁ בִּתְמִידִין וּמוּסָפִין, אוֹמֵר שֶׁיִּנְהַג הָאִסּוּר בְּכָל מוֹשְׁבוֹתֵינוּ, כִּי לֹא נֶאֱמַר בּוֹ "חֻקַּת עוֹלָם לְדֹרֹתֵיכֶם בְּכֹל מוֹשְׁבוֹתֵיכֶם", כִּי אֵינֶנּוּ אֶלָּא לוֹמַר בְּכָל מוֹשְׁבוֹתֵיכֶם - לֹא בְּבֵית הַשֵּׁם. וְכָךְ אָמְרוּ בַּמְּכִילְתָּא (ויקהל א), בַּמּוֹשָׁבוֹת אִי אַתָּה מַבְעִיר אֲבָל אַתָּה מַבְעִיר בְּבֵית הַמִּקְדָּשׁ. וְכֵן נֶאֱמַר (ויקרא ג':י"ז) "חֻקַּת עוֹלָם לְדֹרֹתֵיכֶם בְּכֹל מוֹשְׁבֹתֵיכֶם" בְּאִסּוּר חֵלֶב וְדָם, כִּי הוּא נֶאֱסָר מִפְּנֵי הַקָּרְבָּנוֹת. וְכֵן אָמְרוּ בְּמַסֶּכֶת קִדּוּשִׁין (לז), "מוֹשְׁבוֹתֵיכֶם" דְּכָתַב רַחֲמָנָא בְּחֵלֶב וָדָם לָמָּה לִי, סָלְקָא דַעְתָּךְ אָמֵינָא, הוֹאִיל וּבְעִנְיָנָא דְּקָרְבָּנוֹת כְּתִיב, בִּזְמַן דְּאִיכָּא קָרְבָּן אִין, בִּזְמַן דְּלֵיכָּא קָרְבָּן לָא, קָא מַשְׁמָע לַן. וְשָׁם אָמְרוּ, "מוֹשְׁבוֹתֵיכֶם" דְּכָתַב רַחֲמָנָא בְּשַׁבָּת (ויקרא כ"ג:ג') לָמָּה לִי, סָלְקָא דַּעְתָּךְ אָמֵינָא הוֹאִיל וּבְעִנְיָנָא דְמוֹעֲדוֹת כְּתִיבָא, תִּבְּעֵי קִדּוּשׁ בֵּית דִּין כְּמוֹעֲדוֹת, קָא מַשְׁמָע לַן. וְהַכְּלָל כִּי לֹא יַזְכִּיר בַּתּוֹרָה כֵּן בְּכָל הַמִּצְוֹת שֶׁהֵן חוֹבַת הַגּוּף רַק מִפְּנֵי צֹרֶךְ עִנְיָן. וְאֵין "מִמּוֹשְׁבֹתֵיכֶם תָּבִיאּוּ לֶחֶם תְּנוּפָה" (ויקרא כ"ג:י"ז) כְּמוֹ "מִכָּל מוֹשְׁבוֹתֵיכֶם", אֲבָל טַעְמוֹ "מֵאֶרֶץ מוֹשְׁבוֹתֵיכֶם", לְהוֹצִיא חוּצָה לָאָרֶץ, כְּמוֹ שֶׁנֶּאֱמַר "כִּי תָבוֹאוּ אֶל אֶרֶץ מוֹשְׁבֹתֵיכֶם אֲשֶׁר אֲנִי נֹתֵן לָכֶם" (במדבר טו ב), וְכָךְ שָׁנִינוּ (מנחות פג), כָּל קָרְבְּנוֹת הַצִּבּוּר וְהַיָּחִיד בָּאִין מִן הָאָרֶץ וְחוּצָה לָאָרֶץ חוּץ מִן הָעֹמֶר וּשְׁתֵּי הַלֶּחֶם. וַאֲפִילּוּ לְדִבְרֵי הָאוֹמֵר עֹמֶר בָּא מֵחוּצָה לָאָרֶץ (שם פד), מוֹדֶה בִּשְׁתֵּי הַלֶּחֶם שֶׁאֵינָן בָּאִין אֶלָּא מִן הָאָרֶץ:
@74 **חָמֵץ תֵּאָפֶינָה** צִוָּה הַכָּתוּב שֶׁתִּהְיֶינָה חָמֵץ, לְפִי שֶׁהֵם תּוֹדָה לַשֵּׁם כִּי חֻקּוֹת קָצִיר שָׁמַר לָנוּ, וְקָרְבַּן תּוֹדָה יָבוֹא עַל לֶחֶם חָמֵץ. וְאוּלַי אִסּוּר הֶחָמֵץ מִפְּנֵי שֶׁיִּרְמֹז אֶל מִדַּת הַדִּין, כִּי נִקְרָא "חָמֵץ" כַּאֲשֶׁר יִקָּרֵא הַיַּיִן אֲשֶׁר יִקְהֶה "חֹמֶץ יַיִן וְחֹמֶץ שֵׁכָר" (במדבר ו ג), וְהַלָּשׁוֹן נִגְזַר מִלְּשׁוֹן "מְעַוֵּל וְחוֹמֵץ" (תהלים עא ד), כִּי נִגְזָל מֵהֶם טַעְמָם וְלֹא יֵאָכְלוּ. וְכֵן "כִּי יִתְחַמֵּץ לְבָבִי" (שם עג כא), יִכְעֹס וְיֹאבַד טַעְמוֹ מִמֶּנּוּ. וּבַעֲבוּר שֶׁהַקָּרְבָּנוֹת לְרָצוֹן לַשֵּׁם הַנִּכְבָּד לֹא יוּבְאוּ מִן הַדְּבָרִים אֲשֶׁר לָהֶם הַיָּד הַחֲזָקָה לְשַׁנּוֹת הַטְּבָעִים. וְכֵן לֹא יָבֹאוּ מִן הַדְּבָרִים הַמְּתוּקִים לְגַמְרֵי, כְּגוֹן הַדְּבַשׁ, רַק מִן הַדְּבָרִים הַמְּזוּגִים, כַּאֲשֶׁר אָמְרוּ בִּבְרִיאַת הָעוֹלָם (ב"ר יב טו), שִׁתֵּף מִדַּת רַחֲמִים בְּמִדַּת הַדִּין וּבְרָאוֹ. וְהִנֵּה בְּחַג הַשָּׁבוּעוֹת שֶׁהוּא יוֹם מַתַּן תּוֹרָה יָבִיא הַקָּרְבָּן בְּדִין תּוֹדָה, כִּי הוּא יוֹם הָעֲצֶרֶת, וְהַמַּשְׂכִּיל יָבִין. וְזֶה סוֹד מַה שֶׁאָמְרוּ רַבּוֹתֵינוּ (ויק"ר ט ג), כָּל הַקָּרְבָּנוֹת בְּטֵלִין וְקָרְבַּן תּוֹדָה אֵינוֹ בָּטֵל לְעוֹלָם וְכוּ', כִּי בּוֹ מַצָּה וְחָמֵץ, כָּעִנְיָן בָּעוֹלָם הַבָּא:
@79 **וּבְקֻצְרְכֶם אֶת קְצִיר אַרְצְכֶם לֹא תְכַלֶּה** לְשׁוֹן רַשִׁ"י (רש"י על ויקרא כ"ג:כ"ב), חָזַר וְשָׁנָה בָּהֶם לַעֲבֹר עֲלֵיהֶם בִּשְׁנֵי לָאוִין. וְר"א אָמַר (אבן עזרא על ויקרא כ"ג:כ"ב) כִּי הַטַּעַם בַּעֲבוּר כִּי חַג הַשָּׁבוּעוֹת בִּכּוּרֵי קְצִיר חִטִּים הִזְהִיר שֶׁלֹּא תִּשְׁכַּח מַה שֶׁצִּוִּיתִיךָ לַעֲשׂוֹת בַּיָּמִים הָהֵם. וְהַנָּכוֹן בְּעֵינַי כִּי "וּבְקֻצְרְכֶם אֶת קְצִיר אַרְצְכֶם" רֶמֶז לַקָּצִיר הַנִּזְכָּר בְּרֹאשׁ הַפָּרָשָׁה (ויקרא כ"ג:י'), יֹאמַר כִּי כְּשֶׁתָּבוֹאוּ אֶל הָאָרֶץ וּקְצַרְתֶּם אֶת הָעֹמֶר רֵאשִׁית קְצִירְכֶם, לֹא תְּכַלֶּה פְּאַת הַשָּׂדֶה הַהוּא לְצֹרֶךְ הָעֹמֶר וְלֹא תְּלַקֵּט הַלֶּקֶט, לוֹמַר שֶׁלֹּא תִּדְחֶה הַמִּצְוָה הַהִיא אֶת הַלָּאוִין הָאֵלֶּה:
@81 **יִהְיֶה לָכֶם שַׁבָּתוֹן** שֶׁיִּהְיֶה יוֹם שְׁבִיתָה לָנוּחַ בּוֹ, וְאָמְרוּ רַבּוֹתֵינוּ (שבת כד), "שַׁבָּתוֹן" - עֲשֵׂה הוּא. וְהִנֵּה הָעוֹשֶׂה מְלָאכָה בְּי"ט עוֹבֵר בְּלָאו וַעֲשֵׂה, וְהַשּׁוֹבֵת בּוֹ מְקַיֵּם עֲשֵׂה. וְעַל דַּעְתָּם הַמּוֹעֲדוֹת כֻּלָּם הֻקְשׁוּ זֶה לָזֶה, כִּי לֹא נֶאֱמַר "שַׁבָּתוֹן" בְּחַג הַמַּצּוֹת וְלֹא בַּעֲצֶרֶת. וּבַמְּכִילְתָּא (בא ט) רָאִיתִי בְּפָרָשַׁת הַחֹדֶשׁ, "וּשְׁמַרְתֶּם אֶת הַיּוֹם הַזֶּה" (שמות יב יז) לָמָּה נֶאֱמַר, וַהֲלֹא כְּבָר נֶאֱמַר "כָּל מְלָאכָה לֹא יֵעָשֶׂה בָהֶם" (שם פסוק טז), אֵין לִי אֶלָּא דְּבָרִים שֶׁהֵן מִשּׁוּם מְלָאכָה, דְּבָרִים שֶׁהֵן מִשּׁוּם שְׁבוּת מִנַּיִן, תַּלְמוּד לוֹמַר "וּשְׁמַרְתֶּם אֶת הַיּוֹם הַזֶּה" לְהָבִיא דְּבָרִים שֶׁהֵן מִשּׁוּם שְׁבוּת. יָכוֹל אַף חֻלּוֹ שֶׁל מוֹעֵד יְהֵא אָסוּר מִשּׁוּם שְׁבוּת, וְהַדִּין נוֹתֵן, תַּלְמוּד לוֹמַר "בַּיּוֹם הָרִאשׁוֹן שַׁבָּתוֹן" (להלן כט לט). וְהִנֵּה יִדְרְשׁוּ "שַׁבָּתוֹן" לִשְׁבּוֹת בּוֹ לְגַמְרֵי אֲפִלּוּ מִדְּבָרִים שֶׁאֵינָן מֵאֲבוֹת מְלָאכוֹת וְתוֹלְדוֹתֵיהֶן. אֲבָל לֹא נִתְבָּרֵר לִי זֶה, שֶׁאִם תֹּאמַר שֶׁהוּא אַסְמַכְתָּא, מָה טַעַם שֶׁיֹּאמְרוּ בַּלָּשׁוֹן הַזֶּה, כִּי "שְׁבוּת" בִּלְשׁוֹנָם נֶאֱמַר לְעוֹלָם עַל שֶׁל דִּבְרֵיהֶם, וְהָאֵיךְ יִתָּכֵן לוֹמַר דְּבָרִים שֶׁהֵן אֲסוּרִין מִשּׁוּם שְׁבוֹת שֶׁל דִּבְרֵיהֶם מִנַּיִן שֶׁיְּהוּ אֲסוּרִין מִן הַכָּתוּב, וְדֶרֶךְ הָאַסְמַכְתּוֹת לִשְׁנוֹת שֶׁהֵם מִן הַתּוֹרָה, לֹא שֶׁיֹּאמְרוּ דָּבָר זֶה שֶׁהוּא מִדִּבְרֵי סוֹפְרִים מִנַּיִן מִן הַתּוֹרָה, אֲבָל הָיָה לוֹ לוֹמַר דְּבָרִים שֶׁאֵינָן מְלָאכָה מִנַּיִן, תַּלְמוּד לוֹמַר "שַׁבָּתוֹן". וְנִרְאֶה שֶׁהַמִּדְרָשׁ הַזֶּה לוֹמַר שֶׁנִּצְטַוִּינוּ מִן הַתּוֹרָה לִהְיוֹת לָנוּ מְנוּחָה בְּי"ט אֲפִלּוּ מִדְּבָרִים שֶׁאֵינָן מְלָאכָה, לֹא שֶׁיִּטְרַח כָּל הַיּוֹם לִמְדֹּד הַתְּבוּאוֹת וְלִשְׁקֹל הַפֵּרוֹת וְהַמַּתָּכוֹת וּלְמַלֵּא הֶחָבִיּוֹת יַיִן וּלְפַנּוֹת הַכֵּלִים וְגַם הָאֲבָנִים מִבַּיִת לְבַיִת וּמִמָּקוֹם לְמָקוֹם, וְאִם הָיְתָה עִיר מֻקֶּפֶת חוֹמָה וּדְלָתוֹת נְעוּלוֹת בַּלַּיְלָה יִהְיוּ עֹמְסִים עַל הַחֲמוֹרִים, וְאַף יַיִן וַעֲנָבִים וּתְאֵנִים וְכָל מַשָּׂא יָבִיאוּ בְּי"ט, וְיִהְיֶה הַשּׁוּק מָלֵא לְכָל מִקָּח וּמִמְכָּר, וְתִהְיֶה הַחֲנוּת פְּתוּחָה וְהַחֶנְוָנִי מַקִּיף וְהַשֻּׁלְחָנִים עַל שֻׁלְחָנָם וְהַזְּהוּבִים לִפְנֵיהֶם, וְיִהְיוּ הַפּוֹעֲלִים מַשְׁכִּימִין לִמְלַאכְתָּן וּמַשְׂכִּירִין עַצְמָם כְּחוֹל לִדְבָרִים אֵלּוּ וְכַיּוֹצֵא בָּהֶן, וְהֻתְרוּ הַיָּמִים הַטּוֹבִים הָאֵלּוּ וַאֲפִלּוּ הַשַּׁבָּת עַצְמָהּ, שֶׁבְּכָל זֶה אֵין בָּהֶם מִשּׁוּם מְלָאכָה. לְכָךְ אָמְרָה תּוֹרָה "שַׁבָּתוֹן", שֶׁיִּהְיֶה יוֹם שְׁבִיתָה וּמְנוּחָה לֹא יוֹם טֹרַח. וְזֶהוּ פֵּרוּשׁ טוֹב וְיָפֶה. וְאַחֲרֵי כֵן רָאִיתִי בִּמְכִילְתָּא אַחֲרִיתִי דְּרַבִּי שִׁמְעוֹן בֶּן יוֹחַאי (יב טז) שֶׁשָּׁנוּ בָּהּ לָשׁוֹן אַחֵר, אֵין לִי אֶלָּא מְלָאכָה שֶׁחַיָּבִין עַל מִינָהּ חַטָּאת, מְלָאכָה שֶׁאֵין חַיָּבִין עַל מִינָהּ חַטָּאת מִנַּיִן, כְּגוֹן לֹא עוֹלִין בָּאִילָן וְלֹא רוֹכְבִים עַל גַּבֵּי בְּהֵמָה וְלֹא שָׁטִין עַל פְּנֵי הַמַּיִם וְלֹא מְסַפְּקִים וְלֹא מְטַפְּחִין, תַּלְמוּד לוֹמַר "כָּל מְלָאכָה". אֵין לִי אֶלָּא בִּרְשׁוּת, בְּמִצְוָה מִנַּיִן שֶׁאֵין מַקְדִּישִׁין וְאֵין מַעֲרִיכִין וְאֵין מַחְרִימִין וְאֵין מַגְבִּיהִין תְּרוּמָה וּמַעַשְׂרוֹת, תַּלְמוּד לוֹמַר "שַׁבָּתוֹן" - שְׁבוּת. וּכְעִנְיָן זֶה הִיא שְׁנוּיָה בְּת"כ (אחרי פרק ז ט) בְּיוֹם הַכִּפּוּרִים. וְאע"פ שֶׁאֵלּוּ הַבָּרָיְתוֹת חֲלוּקוֹת בִּלְשׁוֹנָן וּבְמִדְרְשֵׁיהֶן, שֶׁמָּא לְדָבָר אֶחָד נִתְכַּוְּנוּ לְהָבִיא אַסְמַכְתָּא לִשְׁבוּת דְּרַבָּנָן. וּמִכָּל מָקוֹם בֵּין שֶׁיִּהְיֶה פֵּרוּשׁ הַבָּרַיְתָא הָרִאשׁוֹנָה כְּמוֹ שֶׁאָמַרְנוּ אוֹ שֶׁהֵן כֻּלָּן אַסְמַכְתּוֹת, אֲבָל פֵּרוּשׁ "שַׁבָּתוֹן" כָּךְ הוּא, שֶׁתִּהְיֶה לָנוּ מְנוּחָה מִן הַטֹּרַח וְהֶעָמָל כְּמוֹ שֶׁבֵּאַרְנוּ, וְהוּא עִנְיָן הָגוּן וְטוֹב מְאֹד. וְהִנֵּה הֻזְהֲרוּ עַל הַמְּלָאכוֹת בְּשַׁבָּת בְּלָאו וְעָנַשׁ כָּרֵת וּמִיתָה, וְהַטְּרָחִים וְהֶעָמָל בַּעֲשֵׂה, וּבְי"ט הַמְּלָאכָה בְּלָאו וְהַטֹּרַח בַּעֲשֵׂה. וּמִמֶּנּוּ אָמַר הַנָּבִיא (ישעיהו נח יג) "מֵעֲשׂוֹת דְּרָכֶיךָ מִמְּצוֹא חֶפְצְךָ וְדַבֵּר דָּבָר". וְכֵן "שַׁבַּת שַׁבָּתוֹן יִהְיֶה לָאָרֶץ" (ויקרא כ"ה:ד'), שַׁבָּת שֶׁל מְנוּחָה, שֶׁלֹּא יַחֲרֹשׁ וְלֹא יַעֲבֹד אוֹתָהּ כְּלָל. וְזֶהוּ מַה שֶׁדָּרְשׁוּ שֶׁאֵין בְּחֻלּוֹ שֶׁל מוֹעֵד מִשּׁוּם שְׁבוּת, וְזֶה מִן הַתּוֹרָה, שֶׁאִלּוּ מִדִּבְרֵיהֶם כָּל דָּבָר שֶׁאֵינוֹ עוֹשֶׂה אֵינוֹ אוֹמֵר לְגוֹי וְעֹשֶׂה (מו"ק יב), שֶׁאֲפִלּוּ בִּשְׁבוּת דַּאֲמִירָה הֶחְמִירוּ בָּהּ:
@81 **זִכְרוֹן תְּרוּעָה** פְּסוּקֵי זִכְרוֹנוֹת וּפְסוּקֵי שׁוֹפָרוֹת, לִזְכֹּר לָכֶם עֲקֵדַת יִצְחָק שֶׁקָּרַב תַּחְתָּיו אַיִל, לְשׁוֹן רַשִׁ"י (רש"י על ויקרא כ"ג:כ"ד). וְהָיָה צָרִיךְ הָרַב לְהָבִיא גַּם פְּסוּקֵי הַמַּלְכֻיוֹת מִן הַמִּדְרָשׁ, שֶׁלֹּא יִתָּכֵן שֶׁיַּזְכִּיר הַכָּתוּב פְּסוּקֵי הַזִּכְרוֹנוֹת וְשׁוֹפָרוֹת וְלֹא יַזְכִּיר הַמַּלְכֻיוֹת. וּכְבָר דָּרְשׁוּ אוֹתָם מִפָּסוּק "וְהָיוּ לָכֶם לְזִכָּרוֹן לִפְנֵי ה' אֱלֹהֵיכֶם" (במדבר י י), שֶׁאֵין תַּלְמוּד לוֹמַר "אֲנִי ה' אֱלֹהֵיכֶם", וּמַה תַּלְמוּד לוֹמַר "אֲנִי ה' אֱלֹהֵיכֶם", אֶלָּא זֶה בִּנְיַן אָב, כָּל מָקוֹם שֶׁאַתָּה אוֹמֵר זִכְרוֹנוֹת אַתָּה סוֹמֵךְ לָהֶם אֶת הַמַּלְכֻיוֹת, כִּדְאִיתָא בְּת"כ (פרשה יא ב) וּבְמַסֶּכֶת רֹאשׁ הַשָּׁנָה (ראש השנה ל"ב). אֲבָל כָּל זֶה אַסְמַכְתָּא מִדִּבְרֵיהֶם. וּמְפֹרָשׁ אָמְרוּ (שם לד), הוֹלְכִין לִמְקוֹם שֶׁתּוֹקְעִין וְאֵין הוֹלְכִין לִמְקוֹם שֶׁמְּבָרְכִין. פְּשִׁיטָא, הָא דְּאוֹרָיְתָא וְהָא דְּרַבָּנָן, לָא צְרִיכָה דְּאע"ג דְּהָא וַדַּאי וְהָא סָפֵק. אֲבָל "זִכְרוֹן תְּרוּעָה" כְּמוֹ "יוֹם תְּרוּעָה יִהְיֶה לָכֶם" (במדבר כט א), יֹאמַר שֶׁנָּרִיעַ בַּיּוֹם הַזֶּה וְיִהְיֶה לָנוּ לְזִכָּרוֹן לִפְנֵי הַשֵּׁם, כְּמוֹ שֶׁנֶּאֱמַר לְהַלָּן (שם י י) "וּתְקַעְתֶּם בַּחֲצוֹצְרוֹת וְהָיוּ לָכֶם לְזִכָּרוֹן לִפְנֵי אֱלֹהֵיכֶם". וּבַעֲבוּר שֶׁאָמַר שָׁם "וּבְיוֹם שִׂמְחַתְכֶם וּבְמוֹעֲדֵיכֶם וּתְקַעְתֶּם בַּחֲצֹצְרֹת עַל עֹלֹתֵיכֶם וְעַל זִבְחֵי שַׁלְמֵיכֶם" וְכָאן צִוָּה בִּתְרוּעָה סְתָם בַּמּוֹעֵד הַזֶּה בִּלְבַד, וְאַחֲרֵי כֵּן אָמַר (ויקרא כ"ג:י"א) "וְהִקְרַבְתֶּם אִשֶּׁה", הִנֵּה הַתְּרוּעָה הַזֹּאת אֵינָהּ הַתְּרוּעָה הַהִיא, שֶׁהִיא בַּחֲצוֹצְרוֹת עַל הַקָּרְבָּן וְזֹאת אֵינָהּ עַל הַקָּרְבָּן, אֲבָל הִיא חוֹבָה בְּכָל יִשְׂרָאֵל וְהִיא בְּשׁוֹפָר, כִּי לֹא צִוָּהוּ עֲדַיִן לַעֲשׂוֹת חֲצוֹצְרוֹת, וּסְתָם כָּל תְּרוּעָה בְּשׁוֹפָר הִיא, כְּמוֹ שֶׁנֶּאֱמַר (ויקרא כ"ה:ט') "וְהַעֲבַרְתָּ שׁוֹפַר תְּרוּעָה". וְלֹא פֵּרֵשׁ הַכָּתוּב טַעַם הַמִּצְוָה הַזֹּאת לָמָּה הַתְּרוּעָה, וְלָמָּה נִצְטָרֵךְ זִכָּרוֹן לִפְנֵי הַשֵּׁם בַּיּוֹם הַזֶּה יוֹתֵר מִשְּׁאָר הַיָּמִים, וְלָמָּה יְצַוֶּה לִהְיוֹתוֹ מִקְרָא קֹדֶשׁ, אֲבָל מִפְּנֵי שֶׁהוּא בְּחָדְשׁוֹ שֶׁל יוֹם הַכִּפּוּרִים בְּרֹאשׁ הַחֹדֶשׁ נִרְאֶה שֶׁבּוֹ יִהְיֶה דִּין לְפָנָיו יִתְבָּרַךְ, כִּי בָם יָדִין עַמִּים, בְּרֹאשׁ הַשָּׁנָה יֵשֵׁב לְכִסֵּא שׁוֹפֵט צֶדֶק, וְאַחֲרֵי כֵן בַּעֲשֶׂרֶת הַיָּמִים יִשָּׂא לְפֶשַׁע עֲבָדָיו, רָמַז הַכָּתוּב הָעִנְיָן כַּאֲשֶׁר נוֹדַע בְּיִשְׂרָאֵל מִפִּי הַנְּבִיאִים וְאָבוֹת קְדוֹשִׁים. וְעַל דֶּרֶךְ הָאֱמֶת, תְּרוּעָה הִיא שֶׁעָמְדָה לַאֲבוֹתֵינוּ וְלָנוּ, שֶׁנֶּאֱמַר "אַשְׁרֵי הָעָם יוֹדְעֵי תְרוּעָה" (תהלים פט טז), וּכְעִנְיָן שֶׁכָּתוּב "תְּרוּעַת מִלְחָמָה" (ירמיהו ד יט), כִּי הַשֵּׁם אִישׁ מִלְחָמָה. אִם כֵּן "יוֹם תְּרוּעָה יִהְיֶה לָכֶם", שֶׁיִּהְיֶה הַיּוֹם לִתְרוּעָה לָנוּ. וְכֵן "זִכְרוֹן תְּרוּעָה מִקְרָא קֹדֶשׁ", שֶׁיִּהְיֶה הַזִּכָּרוֹן בִּתְרוּעָה וּלְפִיכָךְ הוּא מִקְרָא קֹדֶשׁ. וְלֹא הֻצְרַךְ לְהַזְכִּיר שׁוֹפָר, כִּי הַשּׁוֹפָר רָמַז בְּ"יוֹם" וְהַ"תְּרוּעָה" בּוֹ, וְהִנֵּה הוּא יוֹם דִּין בְּרַחֲמִים, לֹא תְּרוּעַת מִלְחָמָה. וּמִפְּנֵי זֶה הִזְכִּיר הַכָּתוּב הַתְּרוּעָה, שֶׁכְּבָר קַבָּלָה בְּיַד רַבּוֹתֵינוּ וְכָל יִשְׂרָאֵל רוֹאִים עַד מֹשֶׁה רַבֵּינוּ שֶׁכָּל תְּרוּעָה פְּשׁוּטָה לְפָנֶיהָ וּפְשׁוּטָה לְאַחֲרֶיהָ, וְלָמָּה יַזְכִּיר הַכָּתוּב תְּרוּעָה וְלֹא יַזְכִּיר הַתְּקִיעוֹת כְּלָל, לֹא בְּרֹאשׁ הַשָּׁנָה וְלֹא בְּיוֹם הַכִּפּוּרִים, אֲבָל הַתְּקִיעָה הִיא הַזִּכָּרוֹן, וְהוּא הַשּׁוֹפָר, וְהַתְּרוּעָה כִּשְׁמָהּ, וּמִפְּנֵי שֶׁהִיא כְּלוּלָה מִן הָרַחֲמִים, תְּקִיעָה לְפָנֶיהָ וּלְאַחֲרֶיהָ. וּלְפִיכָךְ אָמַר בְּ"יוֹדְעֵי תְּרוּעָה" כִּי בִּצְדָקָה יָרוּמוּ, "כִּי תִפְאֶרֶת עֻזָּמוֹ אָתָּה". וְהִנֵּה זֶה מְבֹאָר כִּי הַכֹּל תָּלוּי בִּתְשׁוּבָה, אֶלָּא בְּרֹאשׁ הַשָּׁנָה מִתְיַחֵד בְּמִדַּת הַדִּין וּמַנְהִיג עוֹלָמוֹ, וּבְיוֹם הַכִּפּוּרִים בְּמִדַּת הָרַחֲמִים, וְהוּא מַאֲמָרָם (ר"ה לב), מֶלֶךְ יוֹשֵׁב עַל כִּסֵּא דִין וְכוּ', רֹאשׁ הַשָּׁנָה יוֹם דִּין בְּרַחֲמִים וְיוֹם הַכִּפּוּרִים יוֹם רַחֲמִים בַּדִּין. וּמִן הָעִנְיָן שֶׁפֵּרַשְׁנוּ תָּבִין טַעַם הַכָּתוּב בַּמַּסָּעוֹת (במדבר י ו ז) "תְּרוּעָה יִתְקְעוּ לְמַסְעֵיהֶם וּבְהַקְהִיל אֶת הַקָּהָל תִּתְקְעוּ וְלֹא תָרִיעוּ", כִּי בְּמַסְעֵיהֶם כָּתוּב "וַיִּסַּע מַלְאַךְ הָאֱלֹהִים" (שמות יד יט), וְכָתוּב "וְיָפֻצוּ אֹיְבֶיךָ וְיָנֻסוּ מְשַׂנְאֶיךָ מִפָּנֶיךָ" (במדבר י לה), כְּטַעַם "פְּנֵי ה' בְּעֹשֵׂי רָע" (תהלים לד יז), וּבְהַקְהִיל אֶת הַקָּהָל נֶאֱמַר (במדבר י לו) "שׁוּבָה ה' רִבְבוֹת", כְּטַעַם "וַיְהִי בִישֻׁרוּן מֶלֶךְ בְּהִתְאַסֵּף רָאשֵׁי עָם יַחַד" (דברים לג ה). וַעֲשֶׂרֶת הַיָּמִים שֶׁבֵּין רֹאשׁ הַשָּׁנָה לְיוֹם הַכִּפּוּרִים יִרְמֹז לְעֶשֶׂר סְפִירוֹת, כִּי בְּיוֹם הַכִּפּוּרִים יִתְעַלֶּה בָּהֶם וְיִגְבַּהּ ה' צְבָאוֹת בַּמִּשְׁפָּט כַּיָּדוּעַ בַּקַּבָּלָה, וְגַם יֵשׁ בָּזֶה אוֹת בַּשָּׁמַיִם, שֶׁהַחֹדֶשׁ הַזֶּה מַזָּלוֹ מֹאזְנַיִם כִּי בּוֹ פֶּלֶס וּמֹאזְנֵי מִשְׁפָּט לַה':
@84 **אַךְ בֶּעָשׂוֹר לַחֹדֶשׁ** כָּל אַכִין וְרַקִּין שֶׁבַּתּוֹרָה מִעוּטִין (ר"ה יז סנהדרין מט), מְכַפֵּר הוּא עַל הַשָּׁבִים וְאֵינוֹ מְכַפֵּר עַל שֶׁאֵינָן שָׁבִים, לְשׁוֹן רַשִׁ"י (רש"י על ויקרא כ"ג:כ"ז) מִדִּבְרֵי רַבּוֹתֵינוּ (בת"כ כאן שבועות יג). וְאִם כֵּן יִהְיֶה טַעַם הַכָּתוּב כִּי בְּאֶחָד לַחֹדֶשׁ יִהְיֶה לָכֶם לְכֻלְּכֶם יוֹם זִכְרוֹן תְּרוּעָה, שֶׁתִּהְיוּ כֻּלְּכֶם נִדּוֹנִין לְפָנָיו, אַךְ יִהְיֶה לְמִקְצַתְכֶם בֶּעָשׂוֹר לַחֹדֶשׁ הַזֶּה יוֹם הַכִּפּוּרִים. וְהִנֵּה הוּא כְּטַעַם "בִּלְבַד", וְכֵן "שָׂא נָא חַטָּאתִי אַךְ הַפַּעַם" (שמות י יז), וְכֵן "הֲרַק אַךְ בְּמֹשֶׁה" (במדבר יב ב) הַבִּלְבַד בְּמֹשֶׁה, וְכֵן "אַךְ בַּחֲמִשָּׁה עָשָׂר יוֹם לַחֹדֶשׁ הַשְּׁבִיעִי" (ויקרא כ"ג:ל"ט), יֹאמַר בִּלְבַד בַּחֲמִשָּׁה עָשָׂר תָּחֹגּוּ אֶת חַג ה' שִׁבְעַת יָמִים, לֹא רְצוּפִים, שֶׁאֵין חֲגִיגָה דּוֹחָה שַׁבָּת. וּבַדֶּרֶךְ הַזֶּה תְּפָרְשֶׁנּוּ בְּכָל הַמִּצְוֹת כְּפִי קַבָּלַת רַבּוֹתֵינוּ. וְכָמוֹהוּ "אַךְ טָרֹף טֹרָף" (בראשית מד כח), שֶׁלֹּא נַעֲשָׂה בּוֹ עִנְיָן אַחֵר לְבַד הַטֶּרֶף. וְכֵן "כִּי הָיוּ בְנֵי יִשְׂרָאֵל וּבְנֵי יְהוּדָה אַךְ עֹשִׂים הָרַע בְּעֵינַי מִנְּעֻרֹתֵיהֶם כִּי בְנֵי יִשְׂרָאֵל אַךְ מַכְעִסִים אֹתִי" (ירמיהו לב ל), שֶׁלֹּא יַעֲשׂוּ דָּבָר אַחֵר. וְעַל דֶּרֶךְ הַפְּשָׁט "אַךְ" טַעְמוֹ "אָכֵן", לְאַמֵּת הָעִנְיָן, "אָכֵן נוֹדַע הַדָּבָר" (שמות יב יד), "אָכֵן כְּאָדָם תְּמֻתוּן" (תהלים פב ז), אָכֵן בֶּעָשׂוֹר לַחֹדֶשׁ יוֹם הַכִּפּוּרִים הוּא, הַבְטָחָה בַּאֲמִתַּת הָעִנְיָן, יֹאמַר בְּאֶחָד לַחֹדֶשׁ יוֹם הַדִּין, אָמְנָם בֶּעָשׂוֹר לַחֹדֶשׁ יוֹם כִּפּוּרִים עַל כֵּן תְּעַנּוּ אֶת נַפְשֹׁתֵיכֶם וְכָל מְלָאכָה לֹא תַעֲשׂוּ. וְכֵן "אַךְ עַצְמִי וּבְשָׂרִי אָתָּה" (בראשית כט יד), "אַךְ מֶלֶךְ יִשְׂרָאֵל הוּא" (מלכים א כב לב), "אַךְ טוֹב לְיִשְׂרָאֵל אֱלֹהִים לְבָרֵי לֵבָב" (תהלים עג א). וְכֵן פֵּרוּשׁ "אַךְ אֶת שַׁבְּתֹתַי תִּשְׁמֹרוּ" (שמות לא יב) הִנֵּה צִוִּיתִי אֶתְכֶם בִּמְלֶאכֶת הַמִּשְׁכָּן, אָכֵן אֶת שַׁבְּתֹתַי תִּשְׁמְרוּ לְעוֹלָם. וְכֵן כֻּלָּם יִתְפָּרְשׁוּ לְךָ בַּדֶּרֶךְ הַזֶּה אִם תַּשְׂכִּיל בָּהֶם:
@85 **בְּעֶצֶם הַיּוֹם הַזֶּה** אָמְרוּ הַמְפָרְשִׁים שֶׁפֵּרוּשׁוֹ בְּגוּף הַיּוֹם הַזֶּה, וְכֵן "וְלֶחֶם וְקָלִי וְכַרְמֶל לֹא תֹאכְלוּ עַד עֶצֶם הַיּוֹם הַזֶּה" (ויקרא כ"ג:י"ד) עַד גּוּף הַיּוֹם, וְכֵן "וּכְעֶצֶם הַשָּׁמַיִם לָטֹהַר" (שמות כד י) גּוּף הַשָּׁמַיִם. וְלֹא נוּכַל לְפָרֵשׁ שֶׁיִּרְמֹז אֶל עֶצֶם הַיּוֹם הַזֶּה וְכֹחוֹ, כְּמוֹ שֶׁאָמְרוּ רַבּוֹתֵינוּ (ספרי האזינו שלז) בְּפָסוּק "בְּעֶצֶם הַיּוֹם הַזֶּה בָּא נֹחַ" (בראשית ז יג), "בְּעֶצֶם הַיּוֹם הַזֶּה הוֹצִיא ה' אֶת בְּנֵי יִשְׂרָאֵל" (שמות יב נא), כִּי כָּתוּב (ויקרא כ"ג:ל"ב) "בְּתִשְׁעָה לַחֹדֶשׁ בָּעֶרֶב מֵעֶרֶב עַד עֶרֶב", וְכֵן "וּקְרָאתֶם בְּעֶצֶם הַיּוֹם הַזֶּה מִקְרָא קֹדֶשׁ" (ויקרא כ"ג:כ"א) - גַּם הַלַּיְלָה בִּכְלָל. וְהִנֵּה לֹא הִזְכִּיר "בְּעֶצֶם הַיּוֹם הַזֶּה" בְּשַׁבָּת וְלֹא בַּמּוֹעֲדִים, רַק בְּחַג הַשָּׁבוּעוֹת (ויקרא כ"ג:כ"א) וּבְיוֹם הַכִּפּוּרִים (כאן), וְכֵן בְּאִסּוּר הֶחָדָשׁ אָמַר (ויקרא כ"ג:י"ד) "עַד עֶצֶם הַיּוֹם הַזֶּה". וְהַנִּרְאֶה בְּטַעַם הַדָּבָר, כִּי בַּעֲבוּר שֶׁאָמַר בְּשָׁבוּעוֹת "מִיּוֹם הֲבִיאֲכֶם אֶת עֹמֶר הַתְּנוּפָה וְגוֹ' תִּסְפְּרוּ חֲמִשִּׁים יוֹם", וְאָמַר "וְהִקְרַבְתֶּם מִנְחָה חֲדָשָׁה מִמּוֹשְׁבוֹתֵיכֶם תָּבִיאּוּ" וּגְמַר הָעִנְיָן (ויקרא כ"ג:ט"ו-י"ז), וְהֶאֱרִיךְ לְצַוּוֹת בַּקָּרְבָּנוֹת (ויקרא כ"ג:י"ח-כ'), הֻצְרַךְ לוֹמַר (ויקרא כ"ג:כ"א) "וּקְרָאתֶם בְּעֶצֶם הַיּוֹם הַזֶּה מִקְרָא קֹדֶשׁ", כִּי גּוּף הַיּוֹם הוּא קָדוֹשׁ וְאָסוּר בַּעֲשִׂיַּת מְלָאכָה, וְאֵינֶנּוּ תָּלוּי בָּעֹמֶר וְלֹא בַּקָּרְבָּנוֹת. וְכֵן בְּיוֹם הַכִּפּוּרִים מִפְּנֵי שֶׁאָמַר (ויקרא כ"ג:כ"ז) "וְעִנִּיתֶם אֶת נַפְשֹׁתֵיכֶם וְהִקְרַבְתֶּם אִשֶּׁה לַה'" וּבְפָרָשַׁת אַחֲרֵי מוֹת תָּלָה עוֹד הַכַּפָּרָה בַּקָּרְבָּנוֹת וּבְשָׂעִיר הַמִּשְׁתַּלֵּחַ, מִפְּנֵי כֵן הֻצְרַךְ לוֹמַר (כאן) וְכָל מְלָאכָה לֹא תַעֲשׂוּ בְּגוּף הַיּוֹם הַזֶּה כִּי יוֹם כִּפֻּרִים הוּא, בְּגוּפוֹ לְכַפֵּר עֲלֵיכֶם מִלְּבַד כַּפָּרַת הַקָּרְבָּנוֹת. וְכֵן "עַד עֶצֶם הַיּוֹם הַזֶּה" בֶּחָדָשׁ (ויקרא כ"ג:י"ד), עַד גּוּף הַיּוֹם הַזֶּה, שֶׁהוּא יוֹם הֲבִיאֲכֶם אֶת קָרְבַּן אֱלֹהֵיכֶם, שֶׁאֲפִלּוּ לֹא יָבֹא הַקָּרְבָּן, הַמִּצְוָה נוֹהֶגֶת בְּגוּף הַיּוֹם הַזֶּה לִהְיוֹת הֶחָדָשׁ אָסוּר לְפָנָיו וּמֻתָּר לְאַחֲרָיו. וְזֶה טַעַם אָמְרוֹ (ויקרא כ"ג:י"ד) "חֻקַּת עוֹלָם לְדֹרֹתֵיכֶם בְּכֹל מוֹשְׁבֹתֵיכֶם" כְּמוֹ שֶׁפֵּרַשְׁתִּי (רמב"ן על ויקרא כ"ג:ט"ז). וּמָצָאנוּ עוֹד שֶׁהִזְכִּיר הַכָּתוּב "בְּעֶצֶם הַיּוֹם הַזֶּה" בְּעִנְיָנִים נִגְזָרִים לְעִתִּים מְזֻמָּנִים, אָמַר בְּנֹחַ "בְּעֶצֶם הַיּוֹם הַזֶּה בָּא נֹחַ" וְגוֹ' "וַיְהִי בְּעֶצֶם הַיּוֹם הַזֶּה יָצְאוּ כָּל צִבְאוֹת ה' מֵאֶרֶץ מִצְרָיִם" (שמות יב מא), "וַיְדַבֵּר ה' אֶל מֹשֶׁה בְּעֶצֶם הַיּוֹם הַזֶּה עֲלֵה אֶל הַר הָעֲבָרִים" (דברים לב מח מט), וְהַטַּעַם בְּאֵלּוּ מִפְּנֵי שֶׁיִּתָּכֵן שֶׁהִכְנִיס נֹחַ בַּתֵּבָה קֹדֶם לָכֵן הַרְבֵּה מִן הַחַיָּה וְהָעוֹף; וְכֵן יִתָּכֵן שֶׁיָּצְאוּ מִקְצָת יִשְׂרָאֵל מִמִּצְרַיִם קֹדֶם לָכֵן וּבַיּוֹם הַהוּא נִגְמַר הָעִנְיָן; וְכֵן קֹדֶם לַיּוֹם הַהוּא הָיְתָה צַוָּאָה לְמֹשֶׁה רַבֵּינוּ בָּעֲלִיָּה הַהִיא וּבַיּוֹם הַהוּא עָלָה; לְכָךְ פֵּרֵשׁ הַכָּתוּב בְּכֻלָּן שֶׁהָיוּ בְּגוּף הַיּוֹם הַהוּא, לֹא שֶׁהֻתְחַל בָּהֶם מִתְּחִלָּה וְנִשְׁלַם עִנְיָנָם בַּיּוֹם הַהוּא, רַק הַכֹּל הָיָה בְּגוּף הַיּוֹם הַזֶּה. וְכֵן "בְּעֶצֶם הַיּוֹם הַזֶּה נִמּוֹל אַבְרָהָם" וְגוֹ' (בראשית יז כו), שֶׁנִּמּוֹלוּ עַם רַב בְּיוֹם אֶחָד, לְהַגִּיד זְרִיזוּתוֹ בַּמִּצְוֹת. וְכֵן נִרְאֶה לִי עוֹד כִּי "עֶצֶם" כָּל דָּבָר - כֹּחוֹ וְתָקְפּוֹ, נִגְזַר מִלְּשׁוֹן "כֹּחִי וְעֹצֶם יָדִי" (דברים ח יז), "עֹז וְתַעֲצוּמוֹת" (תהלים סח לו), וְכֵן "זֶה יָמוּת בְּעֶצֶם תֻּמּוֹ" (איוב כא כג) - בְּתֹקֶף שְׁלֵמוּתוֹ. וּבַעֲבוּר שֶׁהָעֲצָמוֹת מוֹסְדוֹת הַגּוּף וְתָקְפּוֹ יִקָּרְאוּ כֵן. וְהִנֵּה "כְּעֶצֶם הַשָּׁמַיִם לָטֹהַר" (שמות כד י), שֶׁטַּהֲרַת הַדָּבָר שֶׁרָאוּ בְּרוּרָה וַחֲזָקָה כְּחֹזֶק טֹהַר הַשָּׁמַיִם. וּלְכָךְ יַזְכִּיר בַּיָּמִים הַנִּזְכָּרִים "עֶצֶם הַיּוֹם", כִּי הָעִנְיָן בָּהֶם בְּעַצְמָם, לֹא בְּדָבָר אַחֵר נוֹסָף בָּהֶם, שֶׁהוּא הַקָּרְבָּנוֹת אֲשֶׁר יַקְרִיבוּ בָּהֶם. וְכֵן אָמַר אוּנְקְלוֹס (תרגום אונקלוס על ויקרא כ"ג:כ"ח) "בִּקְרַן יוֹמָא הָדֵין", בְּקַרְנוֹ שֶׁל יוֹם, בְּגוּפוֹ וְכֹחוֹ, מִלְּשׁוֹן "וְכָל קַרְנֵי רְשָׁעִים אֲגַדֵּעַ" (תהלים עה יא), "מָגִנִּי וְקֶרֶן יִשְׁעִי" (כב ג), כִּי בַּעֲבוּר שֶׁהַכּוֹחַ בַּקַּרְנַיִם יִקְרְאוּ גּוּף הַדָּבָר קַרְנוֹ. וּבִלְשׁוֹן חֲכָמִים (תרומות פ"ז מ"א), מְשַׁלֵּם אֶת הַקֶּרֶן וְאֵינוֹ מְשַׁלֵּם אֶת הַחֹמֶשׁ. וְיֵשׁ גּוֹרְסִין בַּתַּרְגּוּם "בִּכְרַן" בְּכָ"ף, וְהַכֹּל אֶחָד, כִּי בַּכָּתוּב "כּוֹבַע" וְ"קוֹבַע" שָׁוִים, וְיִשְׁתַּמְּשׁוּ חֲכָמִים בְּכָל לְשׁוֹן עַכָּבָה בְּכָ"ף, נִגְזַר מִ"וְלֹא יְעַקְּבֵם כִּי יִשָּׁמַע קוֹלוֹ" (איוב לז ד), וְיֹאמְרוּ מִתְקַשֵּׁט (תוספתא כתובות ז ג) מִן תַּכְשִׁיטִין, וְאָמְרוּ קִרְסְמוּהָ נְמָלִים (פאה פ"ב מ"ז) מִן "יְכַרְסְמֶנָּה חֲזִיר מִיָּעַר" (תהלים פ יד). וְהַנֶּאֱמָר בַּמְּקוֹמוֹת הַנִּזְכָּרִים "בְּעֶצֶם הַיּוֹם הַזֶּה" גַּם כֵּן פֵּרוּשׁוֹ בְּכֹחַ הַיּוֹם הַהוּא, שֶׁהֵם עִנְיָנִים לֹא יֵעָשׂוּ בְּיוֹם אֶחָד כְּמִנְהָגוֹ שֶׁל עוֹלָם. לְפִיכָךְ אָמַר כִּי כָּל הַחַיָּה וְכָל הַבְּהֵמָה וְכָל הָעוֹף וְכָל רוֹמֵשׂ עַל הָאֲדָמָה נֶאֶסְפוּ בְּכֹחַ הַיּוֹם הַהוּא בִּגְזֵרַת הָאֵל עֲלֵיהֶם, כִּי פִּיו הוּא צִוָּה וְרוּחוֹ הוּא קִבְּצָן. וְכֵן לֹא יֵאָסְפוּ שֵׁשׁ מֵאוֹת אֶלֶף רַגְלִי הַגְּבָרִים לְבַד מִטָּף וְיֵצְאוּ כְּאִישׁ אֶחָד מֵאֶרֶץ מִצְרַיִם, רַק בְּכֹחַ הַיּוֹם הַנִּגְזָר עָלָיו כֵּן מִפִּי עֶלְיוֹן. וְכֵן בְּעִנְיַן מֹשֶׁה רַבֵּינוּ, לְהַגִּיד כִּי בַּיּוֹם שֶׁנִּצְטַוָּה בַּשִּׁירָה וּכְתָבָהּ וַיְלַמְּדָהּ אֶת בְּנֵי יִשְׂרָאֵל (דברים לא כב), וַיְכַל לְדַבֵּר אֶת כָּל הַדְּבָרִים הָאֵלֶּה (שם לב מה), נִגְזַר עָלָיו שֶׁיַּעֲלֶה בְּכֹחַ הַיּוֹם הַהוּא שֶׁהַגְּזֵרָה בּוֹ אֶל הַר הָעֲבָרִים, וְאָמַר וְזֹאת הַבְּרָכָה וְעָלָה שָׁם. וְהוּא עִנְיָן רָאוּי לְיָמִים רַבִּים אֲבָל נַעֲשָׂה בְּכֹחוֹ וְעִצּוּמוֹ שֶׁל יוֹם. וְכֵן מִילַת שְׁלֹשׁ מֵאוֹת וּשְׁמֹנָה עָשָׂר אִישׁ בְּיוֹם אֶחָד בְּבֵית אַבְרָהָם מֵה' הוּא. וְאָמַר יְחֶזְקֵאל (ב ג) "הֵמָּה וַאֲבוֹתָם פָּשְׁעוּ בִי עַד עֶצֶם הַיּוֹם הַזֶּה", לְהַכְנִיס הַיּוֹם בַּכְּלָל הַהוּא. וְכֵן "עַד עֶצֶם הַיּוֹם הַזֶּה" דְּחָדָשׁ, שֶׁהוּא עַד וְעַד בִּכְלָל, כִּי גּוּף הַדָּבָר כֹּחוֹ וְתָקְפּוֹ. וְרַבּוֹתֵינוּ דָּרְשׁוּ (תו"כ פרק יד ז ח) מִלְּשׁוֹן "בְּעֶצֶם הַיּוֹם הַזֶּה" דְּמוֹעֲדִים, עִצּוּמוֹ שֶׁל יוֹם, כְּלוֹמַר מֵעֵת צֵאת הַכּוֹכָבִים עַד צֵאתָם בְּלֵיל הַמָּחֳרָת, לְמַעֵט הַתּוֹסֶפֶת שֶׁלָּמְדוּ לְהוֹסִיף מֵחֹל עַל הַקֹּדֶשׁ. וְיִדְרְשׁוּ (בספרי דברים לב מח) בְּנֹחַ וּבִיצִיאַת מִצְרַיִם וּמֹשֶׁה בְּעִצּוּמוֹ שֶׁל יוֹם - בַּחֲצִי הַיּוֹם, כִּדְאִיתָא בְּסִפְרֵי, וּכְתָבוֹ רַשִׁ"י בְּפָרָשַׁת הַאֲזִינוּ (דברים לב מח):
@93 **עֲצֶרֶת הִיא** עָצַרְתִּי אֶתְכֶם לְפָנַי, כְּמֶלֶךְ שֶׁזִּמֵּן אֶת בָּנָיו לִסְעוּדָה לְכָךְ וְכָךְ יָמִים, כֵּיוָן שֶׁהִגִּיעַ זְמַנָּן לִפָּטֵר, אָמַר, בְּבַקָּשָׁה מִכֶּם עַכְּבוּ עִמִּי עוֹד יוֹם אֶחָד שֶׁקָּשָׁה עָלַי פְּרֵדַתְכֶם, לְשׁוֹן רַשִׁ"י (רש"י על ויקרא כ"ג:ל"ו). וְאַגָּדָה זוֹ שְׁנוּיָה בְּוַיִּקְרָא רַבָּה. וְעַל דֶּרֶךְ הָאֱמֶת, כִּי שֵׁשֶׁת יָמִים עָשָׂה ה' אֶת הַשָּׁמַיִם וְאֶת הָאָרֶץ (שמות כ יא) וְיוֹם הַשְּׁבִיעִי הוּא שַׁבָּת וְאֵין לוֹ בֶּן זוּג, וּכְנֶסֶת יִשְׂרָאֵל הִיא בַּת זוּגוֹ, שֶׁנֶּאֱמַר "וְאֶת הָאָרֶץ", וְהִנֵּה הִיא שְׁמִינִית, "עֲצֶרֶת הִיא", כִּי שָׁם נֶעְצַר הַכֹּל. וְצִוָּה בְּחַג הַמַּצּוֹת שִׁבְעָה יָמִים בִּקְדֻשָּׁה לִפְנֵיהֶם וּלְאַחֲרֵיהֶם, כִּי כֻּלָּם קְדֹשִׁים וּבְתוֹכָם ה', וּמָנָה מִמֶּנּוּ תִּשְׁעָה וְאַרְבָּעִים יוֹם, שִׁבְעָה שָׁבוּעוֹת כִּימֵי עוֹלָם, וְקִדֵּשׁ יוֹם שְׁמִינִי כִּשְׁמִינִי שֶׁל חָג, וְהַיָּמִים הַסְּפוּרִים בֵּינְתַיִם כְּחֻלּוֹ שֶׁל מוֹעֵד בֵּין הָרִאשׁוֹן וְהַשְּׁמִינִי בֶּחָג, וְהוּא יוֹם מַתַּן תּוֹרָה, שֶׁהֶרְאָם בּוֹ אֶת אִשּׁוֹ הַגְּדוֹלָה וּדְבָרָיו שָׁמְעוּ מִתּוֹךְ הָאֵשׁ. וּלְכָךְ יִקְרְאוּ רַבּוֹתֵינוּ זַ"ל בְּכָל מָקוֹם חַג הַשָּׁבוּעוֹת - עֲצֶרֶת, כִּי הוּא כְּיוֹם שְׁמִינִי שֶׁל חַג שֶׁקְּרָאוֹ הַכָּתוּב כֵּן. וְזֶהוּ מַאֲמָרָם (חגיגה יז), שְׁמִינִי רֶגֶל בִּפְנֵי עַצְמוֹ הוּא לְעִנְיַן פז"ר קש"ב, וְתַשְׁלוּמִין דְּרִאשׁוֹן הוּא, כִּי הוּא אֲצִילוּת הָרִאשׁוֹנִים וְאֵינוֹ כְּאַחְדוּת שֶׁלָּהֶם, וּלְכָךְ יַזְכִּיר בְּפָרָשַׁת כָּל הַבְּכוֹר (דברים טז טו) בְּשָׁלֹשׁ רְגָלִים, חַג הַמַּצּוֹת וְחַג הַשָּׁבוּעוֹת וְחַג הַסֻּכּוֹת שִׁבְעַת יָמִים, וְלֹא יַזְכִּיר הַשְּׁמִינִי, כִּי שָׁם אָמַר "יֵרָאֶה כָל זְכוּרְךָ" וְגוֹ' וְהִנֵּה זֶה מְבֹאָר:
@96 **בְּאָסְפְּכֶם אֶת תְּבוּאַת הָאָרֶץ** שֶׁיְּהֵא חֹדֶשׁ שְׁבִיעִי זֶה בִּזְמַן אֲסִיפָה. מִכָּאן שֶׁנִּצְטַוּוּ לְעַבֵּר אֶת הַשָּׁנִים, שֶׁאִם אֵין הָעִבּוּר - פְּעָמִים שֶׁהוּא בָּא בְּאֶמְצַע הַקַּיִץ אוֹ הַחֹרֶף, לְשׁוֹן רַשִׁ"י (רש"י על ויקרא כ"ג:ל"ט). וּלְשׁוֹן ת"כ (פרק טו ו ז), עַבֵּר אֶת הַשָּׁנִים שֶׁתַּעֲשֶׂה הֶחָג בַּאֲסִיפַת הַפֵּרוֹת. יָכוֹל בַּאֲסִיפַת כָּל הַפֵּרוֹת, תַּלְמוּד לוֹמַר "מִגָּרְנְךָ וּמִיִּקְבֶךָ", מִגָּרְנְךָ לֹא כָּל גָּרְנְךָ, וּמִיִּקְבֶךָ לֹא כָּל יִקְבֶךָ. אִי "בְּאָסְפְּךָ מִגָּרְנְךָ", יָכוֹל מִקְצָת, תַּלְמוּד לוֹמַר "בְּאָסְפְּכֶם אֶת תְּבוּאַת הָאָרֶץ". הָא כֵיצַד, הִשְׁתַּדֵּל לְעַבֵּר אֶת הַשָּׁנָה שֶׁתַּעֲשֶׂה הֶחָג בְּרוֹב אֲסִיפַת כָּל הַפֵּרוֹת. וּכְבָר לָמְדוּ הָעִבּוּר מֵחֹדֶשׁ הָאָבִיב (ר"ה כא), אֲבָל שָׁם לִמֵּד עַל הָאָבִיב וְכָאן לִמֵּד עַל פֵּרוֹת הָאִילָן, שֶׁכָּךְ שָׁנוּ חֲכָמִים (סנהדרין יא), עַל שְׁלֹשָׁה דְּבָרִים מְעַבְּרִין אֶת הַשָּׁנָה, עַל הָאָבִיב וְעַל פֵּרוֹת הָאִילָן וְעַל הַתְּקוּפָה. וְהִנֵּה הָעִבּוּר נִלְמַד מֵאֵלָיו שֶׁהֶחָג הַזֶּה בִּזְמַן אֲסִיפָה, אֲבָל עִנְיַן שִׁיטַת הַכָּתוּב שֶׁיֹּאמַר אֵלֶּה מוֹעֲדֵי ה' אֲשֶׁר תִּקְרְאוּ אֹתָם כֻּלָּם מִקְרָאֵי קֹדֶשׁ לְהַקְרִיב בְּכֻלָּם אִשֶּׁה לַה', אָכֵן בְּיוֹם חֲמִשָּׁה עָשָׂר לַחֹדֶשׁ הַשְּׁבִיעִי הַזֶּה בַּעֲבוּר שֶׁהוּא עֵת אָסְפְּכֶם אֶת תְּבוּאַת הָאָרֶץ תָּחֹגּוּ אֶת חַג ה' בְּשִׁבְעַת יָמִים. וְהוֹסִיף לוֹמַר בְּכָאן, "בַּיּוֹם הָרִאשׁוֹן שַׁבָּתוֹן וּבַיּוֹם הַשְּׁמִינִי שַׁבָּתוֹן", שֶׁתִּשְׁבְּתוּ וְתָנוּחוּ בָּהֶם כַּאֲשֶׁר פֵּרַשְׁתִּי (רמב"ן על ויקרא כ"ג:כ"ד), וְאָמַר עוֹד שֶׁתּוֹסִיפוּ לִשְׂמֹחַ לִפְנֵי הַשֵּׁם בְּלוּלָב וְאֶתְרוֹג שִׁבְעַת יָמִים, כִּי הוּא זְמַן שִׂמְחָה שֶׁבֵּרַךְ הַשֵּׁם אוֹתְךָ בְּכָל תְּבוּאָתְךָ וּבְכֹל מַעֲשֵׂה יָדֶיךָ, וְהָיִיתָ אַךְ שָׂמֵחַ לְפָנָיו. וְטַעַם "תָּחֹגּוּ אֶת חַג ה'", שֶׁתָּחֹגּוּ לְפָנָיו לָתֵת הוֹדָאָה לִשְׁמוֹ עַל אֹסֶף מַעֲשֵׂיכֶם כִּי בָא, וְחָזַר וְאָמַר עוֹד (ויקרא כ"ג:מ"א) "וְחַגֹּתֶם אֹתוֹ חַג לַה'" לִסְמֹךְ אֵלָיו "בַּסֻּכּוֹת תֵּשְׁבוּ" (ויקרא כ"ג:מ"ב). וְטַעְמוֹ, וְחַגּוֹתֶם אוֹתוֹ חַג שִׁבְעַת יָמִים בַּשָּׁנָה שֶׁתֵּשְׁבוּ בַּסֻּכּוֹת, וְכָל הָאֶזְרָח בְּיִשְׂרָאֵל יֵשְׁבוּ בַּסֻּכֹּת, לוֹמַר שֶׁיַּעֲשׂוּ חַג שִׁבְעָה בְּלוּלָב וְשִׂמְחָה וּבְסֻכָּה. וּמִדְרָשׁוֹ, "וְחַגֹּתֶם אֹתוֹ חַג לַה'", מַה תַּלְמוּד לוֹמַר, לְפִי שֶׁנֶּאֱמַר "שִׁבְעַת יָמִים תָּחֹג לַה' אֱלֹהֶיךָ" (דברים טז טו), יָכוֹל יִטְעֹן חֲגִיגָה כָּל שִׁבְעָה, תַּלְמוּד לוֹמַר "אוֹתוֹ" וְכוּ' בְּתוֹרַת כֹּהֲנִים (פרק יז א):
@97 **פְּרִי עֵץ הָדָר** שֶׁטַּעַם עֵצוֹ וּפִרְיוֹ שָׁוֶה, "הָדָר" הַדָּר בְּאִילָנוֹ מִשָּׁנָה לְשָׁנָה, וְזֶה אֶתְרוֹג, לְשׁוֹן רַשִׁ"י (רש"י על ויקרא כ"ג:מ'). וְהֵן אַסְמַכְתּוֹת שֶׁעָשׂוּ רַבּוֹתֵינוּ (ת"כ כאן סוכה לה) לְקַבָּלָתָם. וְר"א כָּתַב, וְהָאֱמֶת אָמְרוּ כִּי אֵין פְּרִי עֵץ יוֹתֵר הָדָר מִמֶּנּוּ, וְדָרְשׁוּ בּוֹ "הַדָּר בְּאִילָנוֹ" אַסְמַכְתָּא. וְהַנָּכוֹן בְּעֵינַי, כִּי הָאִילָן הַנִּקְרָא בִּלְשׁוֹן אֲרַמִּית "אֶתְרוֹג" נִקְרָא שְׁמוֹ בִּלְשׁוֹן הַקֹּדֶשׁ "הָדָר", כִּי פֵּרוּשׁ אֶתְרוֹג - חֶמְדָּה, כְּדִמְתַרְגְּמִינַן "נֶחְמָד לְמַרְאֶה" (בראשית ב ט) - "דִּמְרַגַּג לְמִחְזֵי", "לֹא תַחְמֹד" (דברים ה יח) - "לֹא תִרֹג", וְאָמְרִינַן, מִכָּל שְׁפַר אֲרַג נִכְסִין. וּלְשׁוֹן חֶמְדָּה וְהָדָר שָׁוִים בַּטַּעַם. וְנִקְרָא הָעֵץ וְהַפְּרִי בְּשֵׁם אֶחָד, כִּי כֵן הַמִּנְהָג בְּרוֹב הַפֵּרוֹת: תְּאֵנָה אֱגוֹז רִמּוֹן זַיִת וְזוּלָתָם. וְכֵן זֶה שֵׁם הָעֵץ וְהַפְּרִי, שְׁנֵיהֶם בַּאֲרָמִית אֶתְרוֹג וּבִלְשׁוֹן הַקֹּדֶשׁ הָדָר. וּפְשׁוּטוֹ שֶׁל מִקְרָא יֹאמַר שֶׁנִּקַּח לָנוּ פְּרִי עֵץ הָדָר וְנִקַּח כַּפּוֹת תְּמָרִים וְעָנָף אֶחָד מֵעֵץ עָבוֹת וְעָנָף אֶחָד מֵעַרְבֵי נַחַל, וְהִנֵּה הֵם אֶחָד מִכָּל מִין, כִּי כַּפּוֹת תְּמָרִים מְחֻבָּר אֶל "וּלְקַחְתֶּם לָכֶם" שֶׁהֵם הָרַבִּים, כִּי הֲלָכָה הִיא כְּרַבִּי עֲקִיבָא שֶׁאוֹמֵר (סוכה לד), כְּשֵׁם שֶׁלּוּלָב אֶחָד וְאֶתְרוֹג אֶחָד כָּךְ הֲדַס אֶחָד וַעֲרָבָה אַחַת. וּלְכָךְ תִּרְגֵּם אוּנְקְלוֹס (תרגום אונקלוס על ויקרא כ"ג:מ') בְּכֻלָּן בִּלְשׁוֹן רַבִּים, מְחֻבָּר אֶל "וּלְקַחְתֶּם לָכֶם" שֶׁהֵם הָרַבִּים. וּבְטַעַם הַמִּצְוָה הַזֹּאת אָמְרוּ (תענית ב) עַל דֶּרֶךְ הָאַגָּדוֹת, שֶׁהַמִּינִין הַלָּלוּ בָּאִין לְרַצּוֹת עַל הַמַּיִם. וְעַל דֶּרֶךְ הָאֱמֶת "פְּרִי עֵץ הָדָר" הוּא הַפְּרִי שֶׁבּוֹ רֹב הַתַּאֲוָה וּבוֹ חָטָא אָדָם הָרִאשׁוֹן, שֶׁנֶּאֱמַר (בראשית ג ו) "וַתֵּרֶא הָאִשָּׁה כִּי טוֹב הָעֵץ לְמַאֲכָל וְכִי תַאֲוָה הוּא לָעֵינַיִם וְנֶחְמָד הָעֵץ לְהַשְׂכִּיל וַתִּקַּח מִפִּרְיוֹ וַתֹּאכַל", וְהִנֵּה הַחֵטְא בּוֹ לְבַדּוֹ, וַאֲנַחְנוּ נְרַצֶּה לְפָנָיו עִם שְׁאָר הַמִּינִים. וְ"כַפּוֹת תְּמָרִים" הוּא הָרֹאשׁ הַקַּו אֶמְצָעִי כָּפוּל וְגָבוֹהַּ עַל כֻּלָּם. "וַעֲנַף עֵץ עָבֹת" רֶמֶז לְשָׁלֹשׁ סְפִירוֹת בְּבַד אֶחָד, כְּעִנְיָן שֶׁנֶּאֱמַר "מִידֵי אֲבִיר יַעֲקֹב" (שם מט כד). "וְעַרְבֵי נָחַל" כְּעִנְיָן שֶׁנֶּאֱמַר "סֹלּוּ לָרֹכֵב בָּעֲרָבוֹת" (תהלים סח ה), כִּי יִתְעָרְבוּ מִדַּת הַדִּין בְּמִדַּת הָרַחֲמִים. מִכָּאן תָּבִין וְתֵדַע שֶׁאֵין הָאֶתְרוֹג עִמָּהֶם בַּאֲגֻדָּה, וְהוּא מְעַכֵּב בָּהֶם, כִּי הוּא כְּנֶגֶד הָעֲצֶרֶת שֶׁהוּא רֶגֶל בִּפְנֵי עַצְמוֹ וְתַשְׁלוּמִין דְּרִאשׁוֹן, וְהִנֵּה הֵם אֶחָד בְּכֹחַ וְלֹא בְּפֹעַל, וּכְבָר פֵּרַשְׁתִּי (רמב"ן על ויקרא כ"ג:ל"ו) טַעַם זֶה. וְהִנֵּה טַעַם כָּל הַפָּרָשָׁה, תָּחֹגּוּ אֶת חַג הַשֵּׁם הַגָּדוֹל שִׁבְעַת יָמִים שֶׁבְּמַעֲשֶׂה בְּרֵאשִׁית וְתִסְמְכוּ לָהֶם הַשְּׁמִינִי עֲצֶרֶת, כְּעִנְיָן שֶׁנֶּאֱמַר "לַמְנַצֵּחַ עַל הַשְּׁמִינִית" (תהלים ו א), וְגַם בְּאוֹתָן הַשִּׁבְעָה תִּקְחוּ בָּהֶם פְּרִי עֵץ הָדָר וְהַלּוּלָב בַּאֲגֻדָּה, וּלְכָךְ הִקְדִּים הָאֶתְרוֹג, אֲבָל בַּשְּׁמִינִי אֵינוֹ צָרִיךְ כִּי הוּא עַצְמוֹ הָדָר. וְזֶה טַעַם "וְחַגֹּתֶם אֹתוֹ חַג לַה' שִׁבְעַת יָמִים בַּשָּׁנָה", שֶׁתָּחֹגּוּ שִׁבְעַת הַיָּמִים עִם הַשָּׁנָה, עִנְיַן סִבּוּב וְהַקָּפָה, מִלְּשׁוֹן "וְחוּג שָׁמַיִם" (איוב כב יד), "וּבַמְּחוּגָה יְתָאֳרֵהוּ" (ישעיהו מד יג), וְכֵן "הָמוֹן חוֹגֵג" (תהלים מב ה). וּכְבָר רָמְזוּ רַבּוֹתֵינוּ הַסּוֹד הַזֶּה, אָמְרוּ בְּוַיִּקְרָא רַבָּה (ל ט), "פְּרִי עֵץ הָדָר" זֶה הקב"ה, שֶׁנֶּאֱמַר "הוֹד וְהָדָר לְפָנָיו" (תהלים צו ו), "כַּפּוֹת תְּמָרִים" זֶה הקב"ה, שֶׁנֶּאֱמַר "צַדִּיק כַּתָּמָר יִפְרָח" (שם צב יג), "וַעֲנַף עֵץ עָבֹת" זֶה הקב"ה, שֶׁנֶּאֱמַר "וְהוּא עֹמֵד בֵּין הַהֲדַסִּים אֲשֶׁר בַּמְּצֻלָה" (זכריה א ח), "וְעַרְבֵי נָחַל" זֶה הקב"ה, שֶׁנֶּאֱמַר "סֹלּוּ לָרֹכֵב בָּעֲרָבוֹת" (תהלים סח ה). וּבְמִדְרָשׁוֹ שֶׁל רַבִּי נְחוּנְיָה בֶּן הַקָּנָה, מַאי "פְּרִי עֵץ הָדָר", כְּדִמְתַרְגְּמִינַן "פֵּירֵי אִילָנָא אֶתְרוֹגִין וְלוּלַבִּין", וּמַאי "הָדָר", הַיְנוּ הֲדַר הַכֹּל, וְהַיְנוּ הֲדַר שִׁיר הַשִּׁירִים דִּכְתִיב בְּהוּ "מִי זֹאת הַנִּשְׁקָפָה כְּמוֹ שָׁחַר" וְגוֹ' (ו י), וְלָמָּה נִקְרָא שְׁמוֹ "הָדָר", אַל תִּקְרֵי הָדָר אֶלָּא הַדָּר, זֶה אֶתְרוֹג שֶׁהוּא נִפְרָד מֵאֶגֶד הַלּוּלָב וְאֵין מִצְוַת לוּלָב קַיֶּמֶת אֶלָּא בּוֹ, וְהוּא אָגוּד עִם הַכֹּל, שֶׁעִם כָּל אֶחָד הוּא וְעִם כֻּלָּם יַחַד הוּא. וּמַאי לוּלָב, כְּנֶגֶד חוּט הַשִּׁדְרָה. וַעֲנַף עֵץ עָבֹת, שֶׁעֲנָפָיו חוֹפִין אֶת רֻבּוֹ, מָשָׁל לְאָדָם שֶׁבִּזְרוֹעוֹתָיו יָגֵן עַל רֹאשׁוֹ, עָנָף לִשְׂמֹאל עָבוֹת לְיָמִין, נִמְצָא עֵץ בָּאֶמְצַע, וְלָמָּה נֶאֱמַר בּוֹ "עֵץ", שֶׁהוּא שֹׁרֶשׁ הָאִילָן. וּמַאי "עַרְבֵי נָחַל", עַל שֵׁם הַמָּקוֹם שֶׁהֵם קְבוּעִים בּוֹ שֶׁשְּׁמוֹ נַחַל, דִּכְתִיב "כָּל הַנְּחָלִים הֹלְכִים אֶל הַיָּם" וְגוֹ' (קהלת א ז), וּמַאי נִיהוּ יָם, הֱוֵי אוֹמֵר זֶה אֶתְרוֹג. וּמְנָא לָן דְּכָל מִדָּה וּמִדָּה מִכָּל אֵלּוּ הַשִּׁבְעָה אִקְּרִי נַחַל, שֶׁנֶּאֱמַר "וּמִמַּתָּנָה נַחֲלִיאֵל" (במדבר כא יט), אַל תִּקְרֵי נַחֲלִיאֵל אֶלָּא נַחֲלֵי אֵל וְכוּ'. וְהַמִּדְרָשׁ הַזֶּה עַל דַּעַת שְׁלֹשָׁה הֲדַסִּים וּשְׁתֵּי עֲרָבוֹת לוּלָב אֶחָד וְאֶתְרוֹג אֶחָד, וְהִיא הֲלָכָה לְדִבְרֵי הַגְּאוֹנִים וְהָרִאשׁוֹנִים כֻּלָּם:
@99 **אֶזְרָח** זֶה אֶזְרָח, "הָאֶזְרָח" - לְהוֹצִיא אֶת הַנָּשִׁים, שֶׁלֹּא תִּלְמֹד מֵחֲמִשָּׁה עָשָׂר שֶׁל חַג הַמַּצּוֹת לְחַיְּבָן בְּסֻכָּה כְּמַצָּה. "בְּיִשְׂרָאֵל" - לְרַבּוֹת הַגֵּרִים, לְשׁוֹן רַשִׁ"י (רש"י על ויקרא כ"ג:מ"ב). וּבְת"כ (פרק יז ט) "אֶזְרָח" זֶה אֶזְרָח, "הָאֶזְרָח" לְהוֹצִיא אֶת הַנָּשִׁים, "כָּל הָאֶזְרָח" לְרַבּוֹת אֶת הַגֵּרִים וַעֲבָדִים מְשֻׁחְרָרִים. וּפְשׁוּטוֹ שֶׁל מִקְרָא עַל דֶּרֶךְ הַקַּבָּלָה, מִפְּנֵי שֶׁאָמַר הַכָּתוּב "(תורה) חֻקָּה אַחַת יִהְיֶה לָכֶם וְלַגֵּר וּלְאֶזְרַח הָאָרֶץ" (במדבר ט יד), וְאָמַר (שם טו טו) "כָּכֶם כַּגֵּר יִהְיֶה לִפְנֵי ה'", לֹא יִצְטָרֵךְ לְהָשִׁיב וּלְהַזְכִּיר בְּכָל מָקוֹם כָּל הָאֶזְרָח וְהַגֵּר, וְאָמַר "כָּל הָאֶזְרָח בְּיִשְׂרָאֵל", כְּלוֹמַר כָּל אֲשֶׁר הוּא מִיִּשְׂרָאֵל, מִגְּדוֹלָם וְעַד קְטַנָּם, שֶׁלֹּא יִהְיֶה דַּי בְּאֶחָד מִבְּנֵי הַבַּיִת לָדוּר בַּסֻּכָּה וְהַשְּׁאָר יֵשְׁבוּ בַּבָּתִּים, אֲבָל כֻּלָּם יֵשְׁבוּ בַּסֻּכּוֹת. וְיִתָּכֵן שֶׁיֹּאמַר כָּל אֲשֶׁר כְּאֶזְרָח רַעֲנָן בְּבֵיתוֹ, לְהוֹצִיא מְפָרְשֵׁי יַמִּים וְהוֹלְכֵי עַל דֶּרֶךְ:
@100 **כִּי בַסֻּכּוֹת הוֹשַׁבְתִּי אֶת בְּנֵי יִשְׂרָאֵל** עַנְנֵי כָבוֹד, לְשׁוֹן רַשִׁ"י (רש"י על ויקרא כ"ג:מ"ג), וְהוּא הַנָּכוֹן בְּעֵינַי עַל דֶּרֶךְ הַפְּשָׁט, כִּי צִוָּה שֶׁיֵּדְעוּ הַדּוֹרוֹת אֶת כָּל מַעֲשֵׂי ה' הַגָּדוֹל אֲשֶׁר עָשָׂה עִמָּהֶם לְהַפְלִיא, שֶׁשִּׁכֵּן אוֹתָם בְּעַנְנֵי כְּבוֹדוֹ כְּסֻכָּה, כְּעִנְיָן שֶׁנֶּאֱמַר "וּבָרָא ה' עַל כָּל מְכוֹן הַר צִיּוֹן וְעַל מִקְרָאֶהָ עָנָן יוֹמָם וְעָשָׁן וְנֹגַהּ אֵשׁ לֶהָבָה לָיְלָה כִּי עַל כָּל כָּבוֹד חֻפָּה וְסֻכָּה תִּהְיֶה לְצֵל יוֹמָם מֵחֹרֶב" וְגוֹ' (ישעיה ד ה ו). וּמִפְּנֵי שֶׁכְּבָר פֵּרֵשׁ שֶׁעֲנַן ה' עֲלֵיהֶם יוֹמָם וְעַמּוּד הָאֵשׁ בַּלַּיְלָה, אָמַר סְתָם כִּי בַסֻּכּוֹת הוֹשַׁבְתִּי, שֶׁעָשִׂיתִי לָהֶם עַנְנֵי כְּבוֹדִי סֻכּוֹת לְהָגֵן עֲלֵיהֶם. וְהִנֵּה צִוָּה בִּתְחִלַּת יְמוֹת הַחַמָּה בְּזִכְרוֹן יְצִיאַת מִצְרַיִם בְּחָדְשׁוֹ וּבְמוֹעֲדוֹ, וְצִוָּה בְּזִכְרוֹן הַנֵּס הַקַּיָּם הַנַּעֲשֶׂה לָהֶם כָּל יְמֵי עֲמִידָתָם בַּמִּדְבָּר בִּתְחִלַּת יְמוֹת הַגְּשָׁמִים. וְעַל דַּעַת הָאוֹמֵר סֻכּוֹת מַמָּשׁ עָשׂוּ לָהֶם (סוכה יא), הֵחֵלּוּ לַעֲשׂוֹתָן בִּתְחִלַּת הַחֹרֶף מִפְּנֵי הַקֹּר כְּמִנְהַג הַמַּחֲנוֹת, וְלָכֵן צִוָּה בָּהֶן בַּזְּמַן הַזֶּה. וְהַזִּכָּרוֹן שֶׁיֵּדְעוּ וְיִזְכְּרוּ שֶׁהָיוּ בַּמִּדְבָּר, לֹא בָּאוּ בְּבַיִת וְעִיר מוֹשָׁב לֹא מָצָאוּ אַרְבָּעִים שָׁנָה, וְהַשֵּׁם הָיָה עִמָּהֶם לֹא חָסְרוּ דָּבָר:
@101 וְטַעַם **וַיְדַבֵּר מֹשֶׁה אֶת מֹעֲדֵי ה' אֶל בְּנֵי יִשְׂרָאֵל** כִּי הַפָּרָשִׁיּוֹת שֶׁל מַעְלָה אַזְהָרוֹת בְּאַהֲרֹן וּבָנָיו, וּמֹשֶׁה יְדַבֵּר בָּהֶן אֶל אַהֲרֹן וְאֶל בָּנָיו וּפְעָמִים יַזְכִּיר אַחֲרֵיהֶם גַּם בְּנֵי יִשְׂרָאֵל, כְּמוֹ שֶׁאָמַר בְּסוֹף פָּרָשַׁת מוּמִין (ויקרא כ"א:כ"ד) "וַיְדַבֵּר מֹשֶׁה אֶל אַהֲרֹן וְאֶל בָּנָיו וְאֶל כָּל בְּנֵי יִשְׂרָאֵל", כִּי אע"פ שֶׁלֹּא נִצְטַוָּה אֶלָּא "דַּבֵּר אֶל אַהֲרֹן אִישׁ מִזַּרְעֲךָ" (שם פסוק יז) רָצָה לְהַזְהִיר ב"ד שֶׁל יִשְׂרָאֵל עַל כָּךְ. וְאוּלַי הַטַּעַם מִפְּנֵי שֶׁאָדָם מְכַסֶּה עַל מוּמָיו, וְאֵין הַכֹּהֵן חָפֵץ עוֹד לְהִפָּסֵל מִן הָעֲבוֹדָה, כִּי בֹּשֶׁת הִיא וּכְלִמָּה לוֹ, וְעַל כֵּן יַזְהִיר ב"ד בְּעִנְיָן זֶה. אֲבָל בְּכָאן אָמַר שֶׁדִּבֵּר אֶת מֹעֲדֵי ה' אֶל בְּנֵי יִשְׂרָאֵל, לְכֻלָּם כְּאֶחָד, לֹא יִחֵד בָּהֶם בְּנֵי אַהֲרֹן. וְהַטַּעַם מִפְּנֵי שֶׁהָאַזְהָרָה בְּכֻלָּם שָׁוָה, כִּי עִקַּר הַפָּרָשִׁיּוֹת לִשְׁבּוֹת בַּשַּׁבָּתוֹת וּבַמּוֹעֲדִים וְלִקְרוֹתָם מִקְרָא קֹדֶשׁ, וְלֹא נִזְכַּר בָּהֶן מִן הַקָּרְבָּנוֹת לְבַד קָרְבַּן הָעֹמֶר (ויקרא כ"ג:י"ב-י"ג) וּשְׁתֵּי הַלֶּחֶם (פסוקים יח כ), שֶׁהֵם הַגּוֹרְמִים. וּבְפָרָשַׁת עִקַּר הַקָּרְבָּנוֹת שֶׁל יוֹם הַכִּפּוּרִים אָמַר (ויקרא ט"ז:ב') "דַּבֵּר אֶל אַהֲרֹן אָחִיךָ". וְרַבּוֹתֵינוּ דָּרְשׁוּ בּוֹ (ת"כ פרק יז יב) "וַיְדַבֵּר מֹשֶׁה אֶת מֹעֲדֵי ה' אֶל בְּנֵי יִשְׂרָאֵל", מְלַמֵּד שֶׁהָיָה מֹשֶׁה אוֹמֵר לָהֶם לְיִשְׂרָאֵל הִלְכוֹת פֶּסַח בְּפֶסַח וְהִלְכוֹת עֲצֶרֶת בַּעֲצֶרֶת וְהִלְכוֹת הֶחָג בֶּחָג, בַּלָּשׁוֹן שֶׁהוּא שׁוֹמֵעַ בּוֹ בַּלָּשׁוֹן הַהוּא אוֹמֵר לָהֶם כָּל הַפָּרָשִׁיּוֹת. וְאוּנְקְלוֹס (תרגום אונקלוס על ויקרא כ"ג:מ"ד) גַּם הוּא נִתְכַּוֵּן לָזֶה, שֶׁאָמַר "וּמַלֵּל מֹשֶׁה יָת סְדַר מוֹעֲדַיָּא דַּה' וְאַלֵּפִנּוּן". וְהַנִּרְאֶה כִּי דַּעְתּוֹ לִרְמֹז שֶׁלִּמְּדָם סֵדֶר הַמּוֹעֲדוֹת בְּתִקּוּנֵי הָעִבּוּר הַנִּמְסָר לוֹ עַל פֶּה בְּסִינַי, וְנִרְמָז בְּ"אֲשֶׁר תִּקְרְאוּ אֹתָם מִקְרָאֵי קֹדֶשׁ" (לעיל פסוק ד), וְהוּא לִמְּדָם עַל פֶּה כָּל הַסֵּדֶר הַמְקֻבָּל בְּסוֹד הָעִבּוּר:
@103 **צַו אֶת בְּנֵי יִשְׂרָאֵל** זוֹ פָּרָשַׁת מִצְוַת הַנֵּרוֹת, וּפָרָשַׁת "וְאַתָּה תְּצַוֶּה" (שמות כז כ) לֹא נֶאֶמְרָה אֶלָּא עַל סֵדֶר מְלֶאכֶת הַמִּשְׁכָּן לְפָרֵשׁ צֹרֶךְ הַמְּנוֹרָה, וְכָךְ מַשְׁמָעָהּ, וְאַתָּה סוֹפְךָ לְצַוּוֹת אֶת בְּנֵי יִשְׂרָאֵל עַל כָּךְ, לְשׁוֹן רַשִׁ"י (רש"י על ויקרא כ"ד:ב'). וְאֵינֶנּוּ נָכוֹן בְּעֵינַי, שֶׁאֵין הַפָּרָשָׁה הַהִיא סְמוּכָה לְפָרָשַׁת הַמְּנוֹרָה, וּכְבָר נֶאֱמַר "וַיַּעַל הַנֵּרֹת לִפְנֵי ה' כַּאֲשֶׁר צִוָּה ה' אֶת מֹשֶׁה" (שם מ כה), וְהִנֵּה הַמִּצְוָה וְהַמַּעֲשֶׂה נִזְכָּרִים וְנַעֲשִׂים כְּבָר. אֲבָל צֹרֶךְ הַפָּרָשָׁה הַזֹּאת לִשְׁנֵי דְּבָרִים, שֶׁשָּׁם צִוָּה וְיִקְחוּ אֵלֶיךָ שֶׁמֶן זַיִת זָךְ מֵאֵת בְּנֵי יִשְׂרָאֵל, כְּלוֹמַר מֵאֵת כָּל אִישׁ אֲשֶׁר נִמְצָא אִתּוֹ שֶׁמֶן זַיִת זַךְ לַמָּאוֹר עִם שְׁאָר תְּרוּמַת הַמִּשְׁכָּן, וְכֵן עָשׂוּ, כְּמוֹ שֶׁנֶּאֱמַר "וְהַנְּשִׂיאִים הֵבִיאוּ וְגוֹ' אֶת הַבֹּשֶׂם וְאֶת הַשָּׁמֶן לְמָאוֹר" (שם לה כז כח), וְאע"פ שֶׁאָמַר שָׁם "חֻקַּת עוֹלָם לְדֹרֹתָם" (שם כז כא), הוּא עַל הַהַדְלָקָה, וְעַכְשָׁו כָּלָה הַשֶּׁמֶן הַהוּא שֶׁהֵבִיאוּ הַנְּשִׂיאִים נְדָבָה, וְצִוָּה שֶׁיִּקְחוּ בְּנֵי יִשְׂרָאֵל מִשֶּׁל צִבּוּר לְדֹרֹתָם שֶׁמֶן זַיִת זָךְ כָּתִית כַּשֶּׁמֶן הָרִאשׁוֹן, כְּטַעַם "וְיִקְחוּ אֵלֶיךָ פָרָה אֲדֻמָּה" (במדבר יט ב), שֶׁיְּבַקְשׁוּ אוֹתָהּ וִיבִיאוּהָ הַצִּבּוּר. וְשָׁם עוֹד לֹא אָמַר אֶלָּא "יַעֲרֹךְ אֹתוֹ אַהֲרֹן וּבָנָיו" וְגוֹ', וְהָיָה בַּמַּשְׁמָע עַל הַמְּנוֹרָה אוֹ בְּלֹא מְנוֹרָה אִם תִּשָּׁבֵר אוֹ תֹּאבַד, כַּאֲשֶׁר הָיָה בְּשׁוּבָם מִן הַגּוֹלָה, וְעַכְשָׁו אָמַר בְּפֵרוּשׁ "עַל הַמְּנוֹרָה הַטְּהוֹרָה" (ויקרא כ"ד:ד'), שֶׁלֹּא יַדְלִיקוּ אֶלָּא עַל מְנוֹרָה הַטְּהוֹרָה. וּמִדְרַשׁ רַבּוֹתֵינוּ (ת"כ פרשה יג יב), "עַל הַמְּנוֹרָה הַטְּהוֹרָה" - עַל טָהֳרָהּ שֶׁל מְנוֹרָה, שֶׁלֹּא יִסְמְכֵם בִּקְסָמִים וּבִצְרוֹרוֹת. "יַעֲרֹךְ אֶת הַנֵּרוֹת לִפְנֵי ה'" - שֶׁלֹּא יְתַקֵּן מִבַּחוּץ וְיַכְנִיס. "תָּמִיד" - אַף בְּשַׁבָּת. "תָּמִיד" - אַף בְּטֻמְאָה:
@110 **וְהָיְתָה לְאַהֲרֹן וּלְבָנָיו** הַמִּנְחָה הַזֹּאת, שֶׁכָּל דָּבָר הַבָּא מִן הַתְּבוּאָה בִּכְלַל מִנְחָה הוּא. **וַאֲכָלוּהוּ** מוּסָב עַל הַלֶּחֶם, לְשׁוֹן רַשִׁ"י (רש"י על ויקרא כ"ד:ט'). וְיִתָּכֵן כִּי "וְהָיְתָה" עַל כָּל אַחַת מִן הַמַּעֲרָכוֹת. וְעַל דֶּרֶךְ הָאֱמֶת, וְהָיְתָה לְאַהֲרֹן וּלְבָנָיו בְּרִית עוֹלָם, כְּדֶרֶךְ "בְּרִיתִי הָיְתָה אִתּוֹ הַחַיִּים וְהַשָּׁלוֹם" (מלאכי ב ה):
@111 **וַיֵּצֵא בֶּן אִשָּׁה יִשְׂרְאֵלִית** טַעְמוֹ "וַיֵּצֵא בְּתוֹךְ בְּנֵי יִשְׂרָאֵל", וְכֵן "וַיֵּצֵא בְּתוֹךְ הָעִיר" (אסתר ד א), כִּי יָצָא מִבֵּיתוֹ אוֹ מִמְּקוֹם מוֹשָׁבוֹ אֶל הָעִיר, וְכֵן זֶה יָצָא מֵאָהֳלוֹ אוֹ מִמְּקוֹמוֹ וּבָא בְּתוֹךְ הָעָם, וַיִּנָּצוּ שָׁם. וְטַעַם "בַּמַּחֲנֶה", כִּי הָיְתָה הַמְּרִיבָה בַּמַּחֲנֶה, וְשָׁמְעוּ רַבִּים וְתָפְשׂוּ בּוֹ וַיָּבִיאוּ אֹתוֹ אֶל מֹשֶׁה הָאֹהֱלָה. וְטַעַם הַזְכִּיר זֶה בְּכָאן כְּדִבְרֵי הָאוֹמֵר מִפָּרָשָׁה שֶׁל מַעְלָה יָצָא (ויק"ר לב ג), כִּי חָטָא בִּשְׂפָתָיו עַל אִשֵּׁי ה', וְהוֹכִיחוֹ הָאִישׁ הַיִּשְׂרְאֵלִי, וַיִּנָּצוּ שְׁנֵיהֶם, וַיִּחַר אַפּוֹ וְקִלֵּל בְּנַפְשׁוֹ. וְטַעַם "בֶּן הַיִּשְׂרְאֵלִית וְאִישׁ הַיִּשְׂרְאֵלִי", לְהוֹרוֹת כִּי הַגּוֹי הַבָּא עַל בַּת יִשְׂרָאֵל הַוָּלָד אֵינוֹ יִשְׂרְאֵלִי. וְאע"פ שֶׁפָּסַקְנוּ בַּגְּמָרָא (יבמות מה) דְּגוֹי הַבָּא עַל בַּת יִשְׂרָאֵל הַוָּלָד כָּשֵׁר בֵּין בִּפְנוּיָה בֵּין בְּאֵשֶׁת אִישׁ, הֲרֵי אָמְרוּ (בכורות מז), מְזַהֲמִין אֶת הַוָּלָד, לוֹמַר שֶׁהוּא פָּגוּם לַכְּהֻנָּה וְכָל שֶׁכֵּן שֶׁאֵינוֹ יִשְׂרְאֵלִי בִּשְׁמוֹ לְעִנְיַן הַיַּחַס בַּדְּגָלִים וּבְנַחֲלַת הָאָרֶץ, כִּי "לִשְׁמוֹת מַטּוֹת אֲבֹתָם" כָּתוּב בָּהֶן (במדבר כו נה). וּמַה שֶׁאָמַר בְּת"כ (פרשה יד א), "בְּתוֹךְ בְּנֵי יִשְׂרָאֵל", מְלַמֵּד שֶׁנִּתְגַּיֵּר, אֵינוֹ שֶׁיִּצְטָרֵךְ בְּגֵרוּת אֶלָּא כְּכָל יִשְׂרָאֵל שֶׁנִּכְנְסוּ לַבְּרִית בְּמִילָה וּטְבִילָה וְהַרְצָאַת דָּמִים בִּשְׁעַת מַתַּן תּוֹרָה (כריתות ט), אֲבָל נִתְכַּוְּנוּ לוֹמַר שֶׁהָלַךְ אַחֲרֵי אִמּוֹ וְנִדְבַּק בְּיִשְׂרָאֵל. וְזֶה טַעַם "בְּתוֹךְ בְּנֵי יִשְׂרָאֵל", שֶׁהָיָה עִמָּהֶם וְלֹא רָצָה לָלֶכֶת אַחֲרֵי אָבִיו לִהְיוֹת מִצְרִי. וְכֵן מַה שֶׁאָמְרוּ בְּת"כ (שם), אע"פ שֶׁלֹּא הָיוּ מַמְזֵרִים בְּאוֹתָהּ שָׁעָה הוּא הָיָה כְּמַמְזֵר, כְּדִבְרֵי יָחִיד הִיא שְׁנוּיָה, וַהֲלָכָה הַוָּלָד כָּשֵׁר. וְהַצָּרְפָתִים אוֹמְרִים כִּי טַעַם הַגֵּרוּת מִפְּנֵי שֶׁהָיָה קֹדֶם מַתַּן תּוֹרָה, וְהָיָה מִשְׁפָּטוֹ לֵילֵךְ אַחַר הַזָּכָר, מִמַּה שֶׁאָמְרוּ (יבמות עח), בָּאֻמּוֹת הַלֵּךְ אַחַר הַזָּכָר, וְכַאֲשֶׁר נוֹלַד זֶה לֹא מָלוּ אוֹתוֹ, כִּי מִצְרִי הָיָה בְּדִינוֹ, אֲבָל כְּשֶׁגָּדַל נִתְגַּיֵּר לְדַעְתּוֹ וְנִמּוֹל. וְאֵין דַּעְתִּי כָּךְ, כִּי מֵעֵת שֶׁבָּא אַבְרָהָם בַּבְּרִית הָיוּ יִשְׂרָאֵל וּבַגּוֹיִם לֹא יִתְחַשָּׁבוּ, וּכְמוֹ שֶׁאָמַר בְּעֵשָׂו (קידושין יח), וְדִלְמָא יִשְׂרָאֵל מְשֻׁמָּד שָׁאנֵי, וְק"ו הַדָּבָר, אִם לְאַחַר מַתַּן תּוֹרָה שֶׁהַגּוֹי הַבָּא עַל בַּת אַבְרָהָם מֵחַיָּבֵי לָאוִין וְאֵין לוֹ בָּהּ קִדּוּשִׁין, הִיא מִקְוֶה טַהֲרָה לָאֻמּוֹת לְהַכְשִׁיר אֶת וְלָדָהּ לִהְיוֹת כָּמוֹהָ, לֹא כָל שֶׁכֵּן קֹדֶם הַתּוֹרָה, שֶׁתְּהֵא מְטַהֶרֶת וְלָדָהּ לִהְיוֹת כָּמוֹהָ, לְחַיְּבוֹ בְּמִילָה כְּזַרְעוֹ שֶׁל אַבְרָהָם וְיִהְיֶה מִכְּלַל בְּנֵי יִשְׂרָאֵל:
@119 אֵין **נֶפֶשׁ תַּחַת נָפֶשׁ** בַּבְּהֵמָה מַמָּשׁ, שֶׁיִּצְטָרֵךְ לִקְנוֹת לוֹ בְּהֵמָה כִּבְהֶמְתּוֹ, אֲבָל שֶׁיְּשַׁלֵּם לוֹ דָּמִים בְּשׁוֹוִי הַנֶּזֶק אֲשֶׁר עָשָׂה לוֹ. וְכֵן "שֶׁבֶר תַּחַת שֶׁבֶר עַיִן תַּחַת עַיִן" (ויקרא כ"ד:כ') עַל דַּעַת רַבּוֹתֵינוּ (ב"ק פג):
@124 **וּבְנֵי יִשְׂרָאֵל עָשׂוּ כַּאֲשֶׁר צִוָּה ה' אֶת מֹשֶׁה** אַף לִסְמִיכָה אַף לִדְחִיָּה אַף לִתְלִיָּה אַף לְ"לֹא תָלִין נִבְלָתוֹ עַל הָעֵץ", תּוֹרַת כֹּהֲנִים (פרק כ י). וְר"א אָמַר (אבן עזרא על ויקרא כ"ד:כ"ג) בִּפְשׁוּטוֹ, כִּי עָשׂוּ מֵאוֹתוֹ הַיּוֹם וָהָלְאָה כַּמִּשְׁפָּט הַזֶּה בְּחוֹבֵל. וְאֵינוֹ נָכוֹן שֶׁיִּהְיֶה כָּתוּב עַל הֶעָתִיד. וּפְשׁוּטוֹ "וַיִּרְגְּמוּ אוֹתוֹ אָבֶן" כִּי עָשׂוּ בְּנֵי יִשְׂרָאֵל הַמִּצְוָה אֲשֶׁר צִוָּה ה' אֶת מֹשֶׁה, כִּי כֵן יִכְפֹּל בְּכָל הַשּׁוֹמְרִים מִצְוַת הַשֵּׁם, כְּמוֹ שֶׁנֶּאֱמַר בְּפָרָשַׁת הַפֶּסַח (שמות יב כח), וּכְמוֹ שֶׁאָמַר בְּפָרָשַׁת הַפְּקוּדִים "וַיַּעֲשׂוּ בְּנֵי יִשְׂרָאֵל כְּכֹל אֲשֶׁר צִוָּה ה' אֶת מֹשֶׁה כֵּן עָשׂוּ" (במדבר א נד), וְכֵן בְּמַטּוֹת הַנְּשִׂיאִים "וַיַּעַשׂ מֹשֶׁה כַּאֲשֶׁר צִוָּה ה' אֹתוֹ כֵּן עָשָׂה" (שם יז כו). וְהַנָּכוֹן בְּעֵינַי בְּכָאן, מִפְּנֵי שֶׁפֵּרֵט בַּתְּחִלָּה הַסְּקִילָה וְאַחַר כֵּן חָזַר וְאָמַר "וּבְנֵי יִשְׂרָאֵל עָשׂוּ", כִּי טַעַם הַכָּתוּב לוֹמַר כִּי כַּאֲשֶׁר דִּבֶּר מֹשֶׁה אֶל בְּנֵי יִשְׂרָאֵל הוֹצִיאוּ מִיָּד אֶת הַמְקַלֵּל וְרָגְמוּ אוֹתוֹ, וְעָשׂוּ כֵּן כָּל בְּנֵי יִשְׂרָאֵל לִשְׁמֹר וְלַעֲשׂוֹת כַּאֲשֶׁר צִוָּה הַשֵּׁם אֶת מֹשֶׁה, לֹא לְשִׂנְאַת בֶּן הַמִּצְרִי שֶׁנָּצָה עִם הַיִּשְׂרְאֵלִי, אֶלָּא לְבַעֵר הַפָּגוּם מִתּוֹכָם:
